window.HB_TR["luke"]["ur"]=["1۔ چونکہ بہت سے لوگوں نے ان چیزوں کا اعلان ترتیب دیا ہے جو ہمارے درمیان یقینا یقین کی جاتی ہیں، \n2۔ جب انہوں نے انہیں ہمیں پہنچایا، جو ابتدا سے ہی عینی شاہد اور کلام کے خادم تھے؛ \n3۔ مجھے یہ بھی اچھا لگا، جب میں نے ابتدا سے ہی سب کچھ مکمل طور پر سمجھا تھا، کہ میں آپ کو ترتیب وار لکھوں، سب سے بہترین تھیوفیلس، \n4۔ تاکہ تم ان باتوں کی یقین دہانی جان سکو جن میں تمہیں تعلیم دی گئی ہے۔ \n5۔ ہیرودیس کے زمانے میں، یہودیہ کے بادشاہ، ایک خاص کاہن تھا جس کا نام زکریا تھا، جو ابیا کے راستے کا تھا: اور اس کی بیوی ہارون کی بیٹیوں کی تھی، اور اس کا نام الزبتھ تھا۔ \n6۔ اور وہ دونوں خدا کے سامنے نیک تھے، خداوند کے تمام احکامات اور احکام میں بے قصور چلتے ہوئے۔ \n7۔ اور ان کا کوئی بچہ نہیں تھا، کیونکہ وہ الزبتھ بانجھ تھی، اور دونوں {اب} عمر رسیدہ تھے۔ \n8۔ اور ایسا ہوا کہ جب اس نے خدا کے سامنے پادری کا کام اپنے راستے کے مطابق انجام دیا، \n9۔ پادری کے عہدے کی رسم کے مطابق، اس کا مقدر تھا کہ جب وہ خداوند کے مندر میں جائے تو لوبان جلائے گا۔ \n10۔ اور تمام لوگ دھوئیں کے وقت بغیر دعا کر رہے تھے۔ \n11۔ اور اس کے سامنے خداوند کا ایک فرشتہ ظاہر ہوا جو خوشبو کے محراب کے دائیں جانب کھڑا تھا۔ \n12۔ اور جب زکریا نے اسے دیکھا تو وہ پریشان ہو گیا، اور خوف اس پر چھا گیا۔ \n13۔ لیکن فرشتے نے اس سے کہا، زکریاس، ڈرو مت، کیونکہ تمہاری دعا سنی جا رہی ہے؛ اور تمہاری بیوی الزبتھ تمہیں بیٹا دے گی، اور تم اس کا نام جان رکھو گے۔ \n14۔ اور تمہیں خوشی اور خوشی ملے گی؛ اور بہت سے لوگ اس کی پیدائش پر خوش ہوں گے۔ \n15۔ کیونکہ وہ خداوند کی نظر میں عظیم ہوگا، نہ شراب پئے گا نہ تیز مشروب؛ اور وہ روح القدس سے بھرا جائے گا، حتیٰ کہ اپنی ماں کے پیٹ سے۔ \n16۔ اور وہ اسرائیل کے بہت سے بچے خداوند اپنے خدا کی طرف رجوع کریں گے۔ \n17۔ اور وہ ایلیا کی روح اور طاقت میں اس کے سامنے جائے گا، تاکہ باپوں کے دل بچوں کی طرف موڑ دے، اور نافرمان راستوں کی حکمت کی طرف؛ ایک ایسی قوم تیار کرے جو خداوند کے لیے تیار ہو۔ {حکمت کے لیے: یا حکمت کے ذریعے}\n18۔ اور زکریا نے فرشتے سے کہا، میں یہ کیسے جانوں؟ کیونکہ میں بوڑھا آدمی ہوں، اور میری بیوی عمر رسیدہ ہے۔ \n19۔ اور جواب دینے والے فرشتے نے کہا، میں جبرائیل ہوں، جو خدا کے حضور کھڑا ہوں؛ اور میں تم سے بات کرنے اور تمہیں یہ خوشخبری دینے کے لیے بھیجا گیا ہوں۔ \n20. اور دیکھو، تم گونگے رہو گے، اور بولنے کے قابل نہیں رہو گے، جب تک کہ یہ کام انجام نہ ہوں، کیونکہ تم میرے الفاظ پر یقین نہیں کرتے، جو اپنے وقت پر پورا ہوں گے۔ \n21۔ اور لوگ زکریا کا انتظار کر رہے تھے، اور حیران ہوئے کہ وہ مندر میں اتنا دیر ٹھہرا۔ \n22۔ اور جب وہ باہر آیا، تو وہ ان سے بات نہ کر سکا: اور انہوں نے محسوس کیا کہ اس نے مندر میں ایک خواب دیکھا ہے، کیونکہ اس نے انہیں بلایا اور خاموش رہا۔ \n23۔ اور ایسا ہوا کہ جیسے ہی اس کی خدمت کے دن مکمل ہوئے، وہ اپنے گھر چلا گیا۔ \n24۔ اور ان دنوں کے بعد اس کی بیوی الزبتھ حاملہ ہوئی، اور پانچ ماہ چھپائی اور کہا، \n25. خداوند نے میرے ساتھ ان دنوں میں ایسا ہی سلوک کیا جب وہ مجھے دیکھ رہا تھا، تاکہ لوگوں میں میری ملامت دور کر سکے۔ \n26۔ اور چھٹے مہینے میں فرشتہ جبرائیل خدا کی طرف سے گلیل کے ایک شہر ناصرت بھیجا گیا، \n27۔ ایک کنواری کو جو ایک ایسے شخص سے منسوب ہوئی جس کا نام یوسف تھا، جو داؤد کے گھرانے سے تھا؛ اور کنواری کا نام مریم تھا۔ \n28۔ اور فرشتہ اس کے پاس آیا اور کہا، سلام، {تم جو بہت مہربان ہو}، خداوند {ہے} تمہارے ساتھ ہے: مبارک {ہو} عورتوں میں۔ {انتہائی...: یا، مہربانی سے قبول کیا گیا، یا، بہت فضل کا حامل ہو}\n29۔ اور جب اس نے {اسے} کو دیکھا، تو اس کی بات سن کر پریشان ہوئی، اور اس نے اپنے ذہن میں سوچا کہ یہ سلام کیسا ہونا چاہیے۔ \n30۔ اور فرشتے نے اس سے کہا، \"ڈرو مت، مریم، کیونکہ تم نے خدا کی مہربانی پا لی ہے۔ \n31۔ اور دیکھو، تم اپنے پیٹ میں حاملہ ہو گے، بیٹا پیدا کرو گے، اور اس کا نام یسوع رکھو گے۔ \n32۔ وہ عظیم ہوگا، اور اسے سب سے بلند کا بیٹا کہا جائے گا: اور خداوند خدا اسے اس کے والد داؤد کا تخت دے گا: \n33۔ اور وہ ہمیشہ کے لیے یعقوب کے گھر پر حکومت کرے گا؛ اور اس کی بادشاہی کا کوئی اختتام نہیں ہوگا۔ \n34۔ پھر مریم نے فرشتے سے کہا، یہ کیسے ہوگا، جب میں کسی کو نہیں جانتی؟ \n35۔ اور فرشتے نے جواب دیا اور اس سے کہا، روح القدس تم پر آئے گا، اور اعلیٰ کی طاقت تم پر چھا جائے گی؛ اسی لیے وہ مقدس چیز جو تم سے پیدا ہوگی، اسے خدا کا بیٹا کہا جائے گا۔ \n36۔ اور دیکھو، تمہاری کزن الزبتھ نے بھی اپنی بڑھاپے میں بیٹا پیدا کیا ہے: اور یہ اس کے ساتھ چھٹا مہینہ ہے، جسے بانجھ کہا جاتا تھا۔ \n37۔ کیونکہ خدا کے ساتھ کچھ بھی ناممکن نہیں ہوگا۔ \n38۔ اور مریم نے کہا، دیکھو خداوند کی خادمہ؛ یہ میرے لیے ہو جیسا کہ تیرے کلام کے مطابق ہے۔ اور فرشتہ اس سے جدا ہو گیا۔ \n39۔ اور مریم ان دنوں اٹھی، اور جلدی سے پہاڑی علاقے میں چلی گئی، یہودا کے شہر میں؛ \n40۔ اور زکریا کے گھر میں داخل ہوا اور الزبتھ کو سلام کیا۔ \n41۔ اور ایسا ہوا کہ جب الزبتھ نے مریم کا سلام سنا، تو بچہ اس کے پیٹ میں چھلانگ لگا گیا؛ اور الزبتھ روح القدس سے بھر گئی: \n42۔ اور اس نے بلند آواز میں کہا اور کہا، تم عورتوں میں مبارک ہو، اور تمہارے پیٹ کا پھل مبارک ہے۔ \n43۔ اور یہ میرے لیے کہاں سے ہے، کہ میرے رب کی ماں میرے پاس آئے؟ \n44۔ کیونکہ، جیسے ہی تمہاری سلام کی آواز میرے کانوں میں آئی، بچہ خوشی سے میرے پیٹ میں چھلانگ لگا گیا۔ \n45. اور وہ بابرکت {ہے} جس نے ایمان لایا: کیونکہ وہ باتیں جو اسے خداوند کی طرف سے بتائی گئی تھیں، اس کی انجام ہوگی۔ {وہ...: یا، جو وہاں ایمان لیتی تھی}\n46۔ اور مریم نے کہا، میری جان خداوند کو جلال دیتی ہے، \n47۔ اور میری روح نے میرے نجات دہندہ خدا میں خوشی منائی۔ \n48۔ کیونکہ اس نے اپنی خادمہ کی کم تر حیثیت کو دیکھا ہے: کیونکہ دیکھو، اب سے تمام نسلیں مجھے بابرکت کہیں گی۔ \n49۔ کیونکہ جو طاقتور ہے اس نے میرے ساتھ عظیم کام کیے ہیں؛ اور اس کا نام مقدس ہے۔ \n50۔ اور اس کی رحمت ان لوگوں پر ہے جو نسل در نسل اس سے ڈرتے ہیں۔ \n51۔ اس نے اپنے بازو سے طاقت دکھائی ہے؛ اس نے ان کے دلوں میں فخر کو بکھیر دیا ہے۔ \n52۔ اس نے طاقتوروں کو ان کی نشستوں سے نیچے اتارا، اور انہیں کمتر مقام پر بلند کیا۔ \n53۔ اس نے بھوکوں کو اچھی چیزوں سے بھر دیا؛ اور امیروں کو خالی کر دیا۔ \n54۔ اس نے اپنے بندے اسرائیل کو اپنی رحمت کی یاد میں تھام لیا ہے؛ \n55۔ جیسا کہ اس نے ہمارے آباؤ اجداد، ابراہیم اور اپنی نسل سے ہمیشہ کے لیے کہا۔ \n56۔ اور مریم تقریبا تین ماہ اس کے ساتھ رہی، اور پھر اپنے گھر واپس چلی گئی۔ \n57۔ اب الزبتھ کا پورا وقت آیا کہ وہ پیدا ہوئی؛ اور اس نے ایک بیٹا پیدا کیا۔ \n58۔ اور اس کے پڑوسیوں اور کزنز نے سنا کہ خداوند نے اس پر بہت رحم کیا ہے؛ اور وہ اس کے ساتھ خوش ہوئے۔ \n59۔ اور ایسا ہوا کہ آٹھویں دن وہ بچے کا ختنہ کرنے آئے؛ اور انہوں نے اسے زکریا کہا، اس کے والد کے نام پر۔ \n60۔ اور اس کی ماں نے جواب دیا اور کہا، 'ایسا نہیں}؛ لیکن اسے جان کہا جائے گا۔ \n61۔ اور انہوں نے اس سے کہا، تمہارے رشتہ داروں میں سے کوئی اس نام سے نہیں پکارا جاتا۔ \n62۔ اور انہوں نے اس کے والد کو اشارے دیے کہ وہ اسے بلانا چاہتا ہے۔ \n63۔ اور اس نے لکھنے کی میز مانگی، اور لکھا، اس کا نام جان ہے۔ اور سب حیران رہ گئے۔ \n64۔ اور اس کا منہ فورا کھل گیا، اور اس کی زبان کھلی گئی، اور اس نے بولا، اور خدا کی حمد کی۔ \n65۔ اور ان سب پر خوف طاری ہو گیا جو ان کے ارد گرد تھے: اور یہ تمام اقوال یہودیہ کے پہاڑی علاقوں میں پھیل گئے۔ {اقوال: یا، چیزیں}\n66۔ اور جن سب نے سنا {ان} نے اپنے دلوں میں {ان} رکھ دیے، کہنے لگے، یہ کیسا بچہ ہوگا! اور خداوند کا ہاتھ اس کے ساتھ تھا۔ \n67۔ اور اس کا باپ زکریا روح القدس سے بھر گیا، اور اس نے نبوت کی، کہا، \n68۔ مبارک ہو خداوند اسرائیل کے خدا؛ کیونکہ اس نے اپنے لوگوں سے ملاقات کی اور نجات دی، \n69۔ اور اس نے اپنے خادم داؤد کے گھر میں ہمارے لیے نجات کا سینگ اٹھایا؛ \n70۔ جیسا کہ اس نے اپنے مقدس نبیوں کے منہ سے کہا، جو دنیا کے آغاز سے ہیں: \n71۔ کہ ہم اپنے دشمنوں سے اور ان سب کے ہاتھوں سے بچ جائیں جو ہم سے نفرت کرتے ہیں؛ \n72۔ اپنے آباؤ اجداد سے دی گئی رحمت کو پورا کرنا، اور اس کے مقدس عہد کو یاد کرنا؛ \n73۔ وہ قسم جو اس نے ہمارے والد ابراہیم سے کی تھی، \n74۔ کہ وہ ہمیں عطا کرے، تاکہ ہم اپنے دشمنوں کے ہاتھوں سے آزاد ہو کر بغیر خوف کے اس کی خدمت کر سکیں، \n75۔ اس کے سامنے پاکیزگی اور راستبازی میں، ہماری زندگی کے تمام دن۔ \n76۔ اور تم، بچے، اعلیٰ ترین کے نبی کو کہا جائے گا: کیونکہ تم خداوند کے سامنے اس کے راستے تیار کرنے کے لیے جاؤ گے؛ \n77۔ اپنے لوگوں کو ان کے گناہوں کی معافی کے ذریعے نجات کا علم دینا، {بذریعہ: یا، لیے}\n78۔ ہمارے خدا کی نرم رحمت سے؛ جس کے ذریعے اوپر سے آنے والا دن کا چشمہ ہمیں آ گیا ہے، {نرم...: یا، رحمت کے اندرونی حصے} {دن کا چشمہ: یا، سورج نکلتا ہے، یا، شاخ}\n79۔ ان لوگوں کو روشنی دینا جو اندھیرے میں بیٹھے ہیں اور موت کے سائے میں ہیں، تاکہ ہمارے قدم امن کی راہ میں رہنمائی کریں۔ \n80۔ اور بچہ بڑا ہوا، اور روح میں مضبوط ہوا، اور اس دن تک صحرا میں رہا جب تک اس نے اسرائیل کو دکھایا۔","1۔ اور ان دنوں ایسا ہوا کہ قیصر آگسٹس کی طرف سے ایک فرمان جاری ہوا کہ پوری دنیا پر ٹیکس عائد کیا جائے۔ {ٹیکس: یا، اندراج}\n2. ({اور} یہ ٹیکس سب سے پہلے اس وقت لگایا گیا جب سیرینیس شام کا گورنر تھا۔)\n3۔ اور سب کچھ ٹیکس کے لیے چلا گیا، ہر ایک اپنے شہر میں۔ {ٹیکس شدہ: یا، اندراج}\n4۔ اور یوسف بھی گلیل سے ناصری شہر سے نکل کر یہودیہ کے شہر میں گیا، جو بیت لحم کہلاتا ہے؛ (کیونکہ وہ داؤد کے گھر اور نسل سے تھا:)\n5۔ مریم کے ساتھ ٹیکس عائد کرنا، جو اس کی حاملہ بیوی تھی، کیونکہ وہ حاملہ تھی۔ {ٹیکس شدہ: یا، اندراج}\n6۔ اور یوں یہ ہوا کہ جب وہ وہاں تھے، تو وہ دن گزر گئے جب اسے جنم دیا جانا تھا۔ \n7۔ اور اس نے اپنے پہلے بیٹے کو جنم دیا، اسے لپیٹ کر کپڑوں میں لپیٹ دیا اور ایک چرنی میں لٹا دیا؛ کیونکہ ان کے لیے سرائے میں جگہ نہیں تھی۔ \n8۔ اور اسی دیہات میں چرواہے میدان میں رہتے تھے، رات کو اپنے ریوڑ کی نگرانی کرتے تھے۔ {واچ: یا، رات کی پہریدار}\n9۔ اور دیکھو، خداوند کا فرشتہ ان پر آیا، اور خداوند کی شان ان کے گرد چمکی: اور وہ شدید خوفزدہ ہو گئے۔ \n10۔ اور فرشتے نے ان سے کہا، خوف نہ کرو، کیونکہ دیکھو، میں تمہیں بڑی خوشخبری لاتا ہوں، جو سب لوگوں کے لیے ہوگی۔ \n11۔ کیونکہ آج تمہارے لیے پیدا ہوا ہے، داؤد کے شہر میں ایک نجات دہندہ، جو مسیح خداوند ہے۔ \n12۔ اور یہ {تمہارے} کے لیے ایک نشانی ہوگی؛ تم بچے کو لپیٹے ہوئے کپڑوں میں لپٹا ہوا پاؤ گے، جو ایک چرنے میں پڑا ہے۔ \n13۔ اور اچانک فرشتے کے ساتھ آسمانی لشکر کا ایک ہجوم تھا جو خدا کی تعریف کر رہا تھا اور کہہ رہا تھا، \n14۔ سب سے بلند خدا کی شان اور زمین پر انسانوں کے لیے امن، نیک خواہش۔ \n15۔ اور ایسا ہوا، جب فرشتے ان سے دور ہو کر آسمان میں چلے گئے، چرواہوں نے ایک دوسرے سے کہا، آؤ اب بیت لحم کی طرف چلیں، اور اس واقعے کو دیکھیں جو ہو چکی ہے، جو خداوند نے ہمیں بتائی ہے۔ {چرواہے: Gr. مرد چرواہے}\n16۔ اور وہ جلدی سے آئے، اور مریم، یوسف اور بچہ کو ایک چرنی میں پڑا پایا۔ \n17۔ اور جب انہوں نے اسے دیکھا، تو انہوں نے اس بچے کے بارے میں بتایا گیا کہاوت پھیلائی۔ \n18۔ اور جو بھی سنتے تھے وہ ان باتوں پر حیران ہوتے جو چرواہوں نے انہیں بتائی تھیں۔ \n19۔ لیکن مریم نے یہ سب باتیں سنبھال کر رکھیں، اور اپنے دل میں ان پر غور کیا۔ \n20۔ اور چرواہے واپس آئے، خدا کی تعریف کرتے ہوئے جو کچھ انہوں نے سنا اور دیکھا تھا، جیسا کہ انہیں بتایا گیا تھا۔ \n21۔ اور جب بچے کی ختنہ کے لیے آٹھ دن مکمل ہوئے تو اس کا نام یسوع رکھا گیا، جو اس فرشتے کے نام پر تھا جب وہ رحم میں حاملہ نہیں ہوا تھا۔ \n22۔ اور جب موسیٰ کے قانون کے مطابق اس کی پاکیزگی کے دن مکمل ہوئے، تو اسے یروشلم لے آئے تاکہ وہ اسے خداوند کے سامنے پیش کرے؛ \n23. (جیسا کہ خداوند کے قانون میں لکھا ہے، ہر مرد جو رحم کھولتا ہے اسے خداوند کے لیے مقدس کہا جائے گا؛)\n24۔ اور خداوند کے قانون کے مطابق قربانی پیش کرنا، ایک جوڑا کبوتر یا دو نوجوان کبوتر۔ \n25۔ اور دیکھو، یروشلم میں ایک آدمی تھا، جس کا نام {تھا} شمعون تھا؛ اور وہی شخص {تھا} عادل اور دیندار، اسرائیل کی تسلی کا انتظار کر رہا تھا: اور روح القدس اس پر تھا۔ \n26۔ اور روح القدس نے اسے ظاہر کیا کہ وہ موت کو نہیں دیکھے گا، اس سے پہلے کہ وہ خداوند کے مسیح کو دیکھے۔ \n27۔ اور وہ روح کے ذریعے مندر میں آیا: اور جب والدین نے بچے یسوع کو لایا، تاکہ وہ شریعت کے مطابق اس کے لیے کام کرے، \n28۔ پھر اس نے اسے اپنی بانہوں میں اٹھایا اور خدا کو برکت دی اور کہا، \n29۔ اے خداوند، اب تو اپنے خادم کو اپنے کلام کے مطابق امن سے جانے دو: \n30۔ کیونکہ میری آنکھوں نے تیری نجات دیکھی ہے، \n31۔ جو تم نے سب لوگوں کے سامنے تیار کیا ہے؛ \n32۔ غیر یہودیوں کو روشن کرنے کے لیے روشنی، اور تیری قوم اسرائیل کی شان کے لیے۔ \n33۔ اور یوسف اور اس کی ماں ان باتوں پر حیران تھے جو اس کے بارے میں کہی گئیں۔ \n34۔ اور شمعون نے انہیں برکت دی، اور اپنی ماں مریم سے کہا، دیکھو، یہ {بچہ} اسرائیل میں بہت سے لوگوں کے زوال اور دوبارہ زندہ ہونے کے لیے تیار ہے؛ اور ایک نشان کے لیے جس کے خلاف بات کی جائے گی؛ \n35۔ (ہاں، تلوار تمہاری اپنی روح میں بھی گھس جائے گی،) تاکہ بہت سے دلوں کے خیالات ظاہر ہوں۔ \n36۔ اور ایک حنا تھی، جو ایک نبی تھی، فانیول کی بیٹی، قبیلہ آسر سے: وہ بہت بڑی عمر کی تھی، اور اپنے کنواری ہونے سے سات سال بعد شوہر کے ساتھ رہتی تھی؛ \n37۔ اور وہ تقریبا چالیس چار سال کی بیوہ تھی، جو مندر سے نہیں گئی بلکہ رات اور دن روزے اور دعاؤں کے ساتھ خدا کی خدمت کرتی رہی۔ \n38۔ اور اسی لمحے وہ آئی اور اسی طرح خداوند کا شکر ادا کیا، اور اس کے بارے میں ان سب لوگوں سے بات کی جو یروشلم میں نجات کی تلاش میں تھے۔ {یروشلم: یا، اسرائیل}\n39۔ اور جب انہوں نے خداوند کے قانون کے مطابق سب کچھ کیا، تو وہ گلیل واپس آئے، اپنے شہر ناصرت میں۔ \n40۔ اور بچہ بڑا ہوا، اور روح میں مضبوط ہوا، حکمت سے بھرپور: اور خدا کا فضل اس پر تھا۔ \n41۔ اب اس کے والدین ہر سال عید فصح کے موقع پر یروشلم جاتے تھے۔ \n42۔ اور جب وہ بارہ سال کا تھا، تو وہ تہوار کی رسم کے مطابق یروشلم چلے گئے۔ \n43۔ اور جب وہ دن مکمل کر چکے تھے، جب وہ واپس آئے، تو بچہ یسوع یروشلم میں رکا رہا؛ اور یوسف اور اس کی ماں کو اس کا علم نہیں تھا۔ \n44۔ لیکن انہوں نے، یہ سمجھتے ہوئے کہ وہ کمپنی میں ہے، ایک دن کا سفر طے کیا؛ اور انہوں نے اسے اپنے رشتہ داروں اور جاننے والوں میں تلاش کیا۔ \n45۔ اور جب وہ اسے نہ پا سکے تو وہ دوبارہ یروشلم کی طرف مڑے، اسے تلاش کرنے لگے۔ \n46۔ اور ایسا ہوا کہ تین دن بعد انہوں نے اسے مندر میں پایا، ڈاکٹروں کے درمیان بیٹھا ہوا، دونوں سن رہے تھے اور سوالات کر رہے تھے۔ \n47۔ اور جو بھی اسے سنتا تھا وہ اس کی سمجھ اور جوابات پر حیران رہ گیا۔ \n48۔ اور جب انہوں نے اسے دیکھا تو حیران رہ گئے: اور اس کی ماں نے اس سے کہا، بیٹا، تم نے ہمارے ساتھ ایسا کیوں کیا؟ دیکھو، تمہارے والد اور میں نے تمہیں غمگین کرنے کی کوشش کی ہے۔ \n49۔ اور اس نے ان سے کہا، تم نے مجھے کیسے تلاش کیا؟ کیا تم نہیں جانتے کہ مجھے اپنے والد کے کام میں مصروف ہونا چاہیے؟ \n50۔ اور وہ اس کہاوت کو نہ سمجھ سکے جو اس نے ان سے کہا۔ \n51۔ اور وہ ان کے ساتھ نیچے گیا، ناصرت پہنچا، اور ان کے تابع رہا، لیکن اس کی ماں نے یہ سب باتیں دل میں رکھیں۔ \n52۔ اور یسوع نے حکمت اور قد میں اضافہ کیا، اور خدا و انسان کی پسندیدگی میں اضافہ ہوا۔ {قد: یا، عمر}","1۔ اب ٹائبیریئس سیزر کی حکومت کے پندرہویں سال میں، پونٹیئس پیلاطس یہودیہ کا گورنر تھا، اور ہیرودیس گلیل کا ٹیٹرارک تھا، اور اس کا بھائی فلپ ایتوریا اور ٹراکونائٹس کے علاقے کا ٹیٹرارک تھا، اور لیسانیاس ابیلین کا ٹیٹرارک، {ٹیٹرارک: یا، چار صوبوں کا گورنر}\n2۔ ایناس اور قیافا چونکہ اعلیٰ کاہن، خدا کا کلام یوحنا زکریا کے بیٹے کو صحرا میں آیا۔ \n3۔ اور وہ اردن کے ارد گرد پورے علاقے میں آیا، گناہوں کی معافی کے لیے توبہ کی تبلیغ کی؛ \n4۔ جیسا کہ یسعیاس نبی کے الفاظ کی کتاب میں لکھا ہے، جو کہتا ہے: بیابان میں پکار کرنے والے کی آواز، خداوند کے راستے تیار کرو، اس کے راستے سیدھے کرو۔ \n5۔ ہر وادی بھر جائے گی، اور ہر پہاڑ اور پہاڑی کو نیچے لایا جائے گا؛ اور ٹیڑھے کو سیدھا کیا جائے گا، اور کھردرے راستے ہموار کیے جائیں گے؛ \n6۔ اور ہر انسان خدا کی نجات دیکھے گا۔ \n7۔ پھر اس نے ان لوگوں سے کہا جو اس کی بپتسمہ لینے آئے تھے، اے سانپوں کی نسل، کس نے تمہیں آنے والے غضب سے بھاگنے کی تنبیہ کی ہے؟ \n8۔ یوں توبہ کے لائق پھل نکالو، اور اپنے اندر یہ نہ کہنا شروع کرو کہ ابراہیم ہمارے باپ کے لیے ہے: کیونکہ میں تم سے کہتا ہوں، خدا ان پتھروں سے اولاد ابراہیم کے لیے پیدا کرنے کے قابل ہے۔ {لائق: یا، ملو}\n9۔ اور اب کلہاڑی بھی درختوں کی جڑ میں رکھی جاتی ہے: اس لیے ہر وہ درخت جو اچھا پھل نہیں لاتا، اسے کاٹ کر آگ میں پھینک دیا جاتا ہے۔ \n10۔ اور لوگوں نے اس سے پوچھا، پھر ہم کیا کریں؟ \n11۔ وہ جواب دیتا ہے اور ان سے کہتا ہے، جس کے پاس دو کپڑے ہیں، وہ اس کو دے جس کے پاس کوئی کوٹ نہیں؛ اور جس کے پاس گوشت ہے، وہ بھی ایسا ہی کرے۔ \n12۔ پھر پبلکرز بھی بپتسمہ لینے آئے اور اس سے کہا، مالک، ہم کیا کریں؟ \n13۔ اور اس نے ان سے کہا، جو تمہیں مقرر کیا گیا ہے اس سے زیادہ نہ مانو۔ \n14۔ اور سپاہیوں نے بھی اس سے مطالبہ کیا، کہا، اور ہم کیا کریں؟ اور اس نے ان سے کہا، کسی پر ظلم نہ کرو، نہ جھوٹا الزام لگاؤ؛ اور اپنی اجرت پر مطمئن رہو۔ {تشدد کرو...: یا، کسی کو خوفزدہ نہ کرو} {اجرت: یا الاؤنس}\n15۔ اور جیسے لوگ توقع میں تھے، اور سب لوگ اپنے دلوں میں یوحنا کے بارے میں سوچ رہے تھے کہ آیا وہ مسیح ہے یا نہیں؛ {توقع میں: یا، معلق میں} {غور کیا: یا، استدلال کیا، یا، بحث کی}\n16۔ یوحنا نے جواب دیا، سب سے کہا، میں واقعی تمہیں پانی سے بپتسمہ دیتا ہوں؛ لیکن جو مجھ سے زیادہ طاقتور ہے، جس کے جوتوں کی کنڈی میں کھولنے کے لائق نہیں: وہ تمہیں روح القدس اور آگ سے بپتسمہ دے گا: \n17۔ جس کا پنکھا اس کے ہاتھ میں ہے، اور وہ اپنی زمین کو مکمل طور پر صاف کرے گا، اور گندم کو اپنے مجموعے میں جمع کرے گا؛ لیکن بھوسہ کو وہ آگ سے جلا دے گا جو بجھنے والی ہے۔ \n18۔ اور اپنی نصیحت میں اس نے لوگوں کو بہت سی دوسری باتیں سنائیں۔ \n19۔ لیکن ہیرودیس ٹیٹرارک، جسے اس نے ہیرودیاس اپنے بھائی فلپ کی بیوی اور ہیرودیس کے کیے گئے تمام برائیوں کے لیے سرزنش کی، \n20۔ اس میں سب سے بڑھ کر یہ بھی شامل کیا گیا کہ اس نے جان کو جیل میں بند کر دیا۔ \n21۔ اب جب سب لوگ بپتسمہ لے چکے تھے، تو یہ ہوا کہ یسوع بھی بپتسمہ لے رہے تھے اور دعا کر رہے تھے، تو آسمان کھل گیا، \n22۔ اور روح القدس اس پر کبوتر کی طرح جسمانی شکل میں اترا، اور آسمان سے ایک آواز آئی، جس نے کہا، تو میرے محبوب بیٹے ہو؛ میں تم سے خوش ہوں۔ \n23۔ اور یسوع خود تقریبا تیس سال کا ہوا، جیسا کہ سمجھا جاتا تھا، یوسف کا بیٹا تھا، جو ہیلی کا {بیٹا} تھا، \n24۔ جو متی کا {بیٹا} تھا، جو {لاوی کا بیٹا} تھا، جو {میلکی کا بیٹا} تھا، جو {ینہ کا بیٹا} تھا، جو یوسف کا {بیٹا} تھا، \n25۔ جو متاتھیاس کا {بیٹا} تھا، جو {عاموس کا بیٹا} تھا، جو {ناؤم کا بیٹا} تھا، جو {ایسلی کا بیٹا} تھا، جو {ناگ کا بیٹا} تھا، \n26۔ جو ماعت کا {بیٹا} تھا، جو {متاتھیاس کا بیٹا} تھا، جو {سمیئی کا بیٹا} تھا، جو {یوسف کا بیٹا} تھا، جو {یہودا کا بیٹا} تھا، \n27. جو جوانا کا {بیٹا} تھا، جو ریسا کا {بیٹا} تھا، جو {زوروبابل کا بیٹا} تھا، جو {سلاتھیئل کا بیٹا} تھا، جو {نیری کا بیٹا} تھا، \n28۔ جو میلکی کا {بیٹا} تھا، جو عدی کا {بیٹا} تھا، جو کوسام کا {بیٹا} تھا، جو {ایلمودام کا بیٹا} تھا، جو {ایر کا بیٹا} تھا، \n29. جو یوسف کا {بیٹا} تھا، جو {الیعازر کا بیٹا} تھا، جو {یوریم کا بیٹا} تھا، جو {متاتا کا بیٹا} تھا، جو {لاوی کا بیٹا} تھا، \n30۔ جو شمعون کا {بیٹا} تھا، جو {یہودا کا بیٹا} تھا، جو {یوسف کا بیٹا} تھا، جو {یونان کا بیٹا} تھا، جو {ایلیاکیم کا بیٹا} تھا، \n31۔ جو میلیا کا {بیٹا} تھا، جو مینان کا {بیٹا} تھا، جو متاتھا کا {بیٹا} تھا، جو ناتھن کا {بیٹا} تھا، جو {داؤد کا بیٹا} تھا، \n32. جو یسوع کا {بیٹا} تھا، جو {اوبید کا بیٹا} تھا، جو {بوز کا بیٹا} تھا، جو {سالمون کا بیٹا} تھا، جو ناصون کا {بیٹا} تھا، \n33. جو امیناداب کا {بیٹا} تھا، جو {آرم کا بیٹا} تھا، جو {ایسرم کا بیٹا} تھا، جو {فارس کا بیٹا} تھا، جو {یہودا کا بیٹا} تھا، \n34۔ جو یعقوب کا {بیٹا} تھا، جو اسحاق کا {بیٹا} تھا، جو ابراہیم کا {بیٹا} تھا، جو ثارا کا {بیٹا} تھا، جو ناخور کا {بیٹا} تھا، \n35. جو ساروخ کا {بیٹا} تھا، جو راگاؤ کا {بیٹا} تھا، جو {فیلک کا بیٹا} تھا، جو {ہیبر کا بیٹا} تھا، جو {سالا کا بیٹا} تھا، \n36. جو قینان کا {بیٹا} تھا، جو {ارفکساڈ کا بیٹا} تھا، جو سیم کا {بیٹا} تھا، جو {نوئے کا بیٹا} تھا، جو لامیک کا {بیٹا} تھا، \n37۔ جو متھوسالا کا {بیٹا} تھا، جو {حنوخ کا بیٹا} تھا، جو {یراد کا بیٹا} تھا، جو {مالیلیئل کا بیٹا} تھا، جو {قاینان کا بیٹا} تھا، \n38۔ جو اینوس کا {بیٹا} تھا، جو {سیٹھ کا بیٹا} تھا، جو {آدم کا بیٹا} تھا، جو خدا کا {بیٹا} تھا۔","1۔ اور یسوع، جو روح القدس سے بھرا ہوا تھا، اردن سے واپس آیا، اور روح کی مدد سے بیابان میں لے جایا گیا، \n2۔ چالیس دن شیطان کی آزمائش میں مبتلا ہونا۔ اور ان دنوں اس نے کچھ نہیں کھایا: اور جب وہ ختم ہوئے تو بعد میں بھوکا رہا۔ \n3۔ اور شیطان نے اس سے کہا، اگر تم خدا کے بیٹے ہو، تو اس پتھر کو روٹی بنانے کا حکم دو۔ \n4۔ اور یسوع نے اس کا جواب دیا، کہا، لکھا ہے، کہ انسان صرف روٹی سے نہیں بلکہ خدا کے ہر کلام سے زندہ رہے گا۔ \n5۔ اور شیطان نے اسے ایک بلند پہاڑ پر لے جا کر ایک لمحے میں دنیا کی تمام سلطنتیں دکھا دیں۔ \n6۔ اور شیطان نے اس سے کہا، یہ ساری طاقت میں تمہیں دوں گا، اور ان کی شان بھی، کیونکہ یہ میرے حوالے کر دی گئی ہے؛ اور جسے چاہوں میں اسے دوں گا۔ \n7. اگر تم میری عبادت کرو گے، تو سب کچھ تمہارا ہوگا۔ {میری عبادت کرو: یا میرے سامنے گر جاؤ}\n8۔ اور یسوع نے جواب دیا اور کہا، شیطان، میرے پیچھے چلو، کیونکہ یہ لکھا ہے، تو اپنے خداوند خدا کی عبادت کرو گے، اور صرف اسی کی عبادت کرو گے۔ \n9۔ اور وہ اسے یروشلم لے آیا، ہیکل کی چوٹی پر بٹھا دیا، اور کہا، اگر تم خدا کے بیٹے ہو، تو یہاں سے نیچے اتر آؤ: \n10۔ کیونکہ یہ لکھا ہے، وہ اپنے فرشتوں کو آپ پر حکم دے گا، تاکہ وہ آپ کی حفاظت کریں: \n11۔ اور وہ تمہیں اپنے ہاتھوں میں اٹھائیں گے، کہیں تم پتھر پر پاؤں نہ مارو۔ \n12۔ اور یسوع نے جواب میں اسے کہا، کہا گیا ہے، تو اپنے خدا خداوند کو آزمانا نہیں دینا۔ \n13۔ اور جب شیطان نے تمام آزمائشوں کو ختم کر دیا، تو وہ ایک وقت کے لیے اس سے دور ہو گیا۔ \n14۔ اور یسوع روح کی طاقت میں گلیل میں واپس آئے: اور اس کی شہرت آس پاس کے تمام علاقوں میں پھیل گئی۔ \n15۔ اور انہوں نے ان کے عبادت گاہوں میں تعلیم دی، سب کی شان و شوال کے طور پر۔ \n16۔ اور وہ ناصرت پہنچا، جہاں اسے پالا گیا تھا: اور جیسا کہ اس کی عادت تھی، وہ سبت کے دن عبادت گاہ میں گیا، اور پڑھنے کے لیے کھڑا ہو گیا۔ \n17۔ اور اسے نبی عیسیٰ کی کتاب دی گئی۔ اور جب اس نے کتاب کھولی، تو اسے وہ جگہ ملی جہاں یہ لکھی گئی تھی، \n18۔ خداوند کی روح مجھ پر ہے، کیونکہ اس نے مجھے غریبوں کو خوشخبری سنانے کے لیے مسح کیا ہے؛ اس نے مجھے بھیجا ہے تاکہ ٹوٹے دل کو شفا دوں، قیدیوں کو نجات دوں، اور اندھوں کو بینائی کی بحالی دوں، تاکہ زخموں کو آزاد کروں، \n19۔ خداوند کے قابل قبول سال کی تبلیغ کرنا۔ \n20۔ اور اس نے کتاب بند کی، اور اسے دوبارہ وزیر کو دے دیا، اور بیٹھ گیا۔ اور عبادت گاہ میں موجود تمام لوگوں کی نظریں اس پر جم گئیں۔ \n21۔ اور اس نے انہیں کہنا شروع کیا، آج یہ آیت تمہارے کانوں میں پوری ہو رہی ہے۔ \n22۔ اور سب نے اس کی گواہی دی، اور اس کے منہ سے نکلنے والے مہربان الفاظ پر حیران ہوئے۔ اور انہوں نے کہا، کیا یہ یوسف کا بیٹا نہیں؟ \n23۔ اور اس نے ان سے کہا، تم ضرور مجھ سے یہ کہاوت کہو گے، طبیب، اپنے آپ کو شفا دو: جو کچھ ہم نے کفرناحوم میں سنا ہے، وہ بھی اپنے ملک میں کرو۔ \n24۔ اور اس نے کہا، \"میں واقعی تم سے کہتا ہوں، کوئی نبی اپنے ملک میں قبول نہیں ہوتا۔\" \n25۔ لیکن میں تمہیں ایک سچ بتاتا ہوں، ایلیاس کے زمانے میں اسرائیل میں بہت سی بیوائیں تھیں، جب آسمان تین سال اور چھ مہینے بند تھا، جب پورے ملک میں شدید قحط تھا؛ \n26۔ لیکن ایلیاس کو ان میں سے کسی کے پاس بھیجا نہیں گیا، سوائے سارپتا کے، جو صیدون کا ایک شہر ہے، ایک عورت کے پاس جو بیوہ تھی۔ \n27۔ اور بہت سے کوڑھ اسرائیل میں تھے، جو الیسیئس نبی کے زمانے میں تھے؛ اور ان میں سے کوئی بھی پاک نہیں ہوا، سوائے نعمان شامی کے۔ \n28۔ اور جب انہوں نے یہ باتیں سنی تو عبادت گاہ میں موجود سب غصے سے بھر گئے، \n29۔ اور اٹھ کھڑے ہوئے، اسے شہر سے باہر نکالا، اور اسے اس پہاڑی کے کنارے لے گئے جہاں ان کا شہر تعمیر ہوا تھا، تاکہ وہ اسے سر کے بل نیچے گرا سکیں۔ {ابرو: یا، کنارے}\n30۔ لیکن وہ ان کے درمیان سے گزرتا ہوا اپنی راہ پر چل پڑا، \n31۔ اور گلیل کے شہر کفرناحوم میں آیا اور سبت کے دنوں میں انہیں تعلیم دی۔ \n32۔ اور وہ اس کے عقیدے پر حیران رہ گئے: کیونکہ اس کا کلام طاقت کے ساتھ تھا۔ \n33۔ اور عبادت گاہ میں ایک آدمی تھا، جس کی روح ناپاک شیطان جیسی تھی، اور وہ زور سے پکار رہا تھا، \n34۔ کہتے ہوئے، ہمیں اکیلا چھوڑ دو؛ ہم تمہارے ساتھ کیا لینا دینا چاہتے ہو، ناصری کے یسوع؟ کیا تم ہمیں تباہ کرنے آئے ہو؟ میں تمہیں جانتا ہوں کہ تم کون ہو؛ خدا کا پاک۔ {چلو...: یا، چلے جاؤ}\n35۔ اور یسوع نے اسے ڈانٹا، کہا، خاموش رہو اور اس سے باہر آ جاؤ۔ اور جب شیطان نے اسے بیچ میں پھینک دیا، تو وہ اس سے باہر آ گیا، اور اسے نقصان نہ پہنچا۔ \n36۔ اور وہ سب حیران رہ گئے، اور آپس میں بات کرنے لگے، یہ کیا لفظ ہے! کیونکہ وہ اختیار اور طاقت کے ساتھ ناپاک روحوں کو حکم دیتا ہے، اور وہ باہر آتی ہیں۔ \n37۔ اور اس کی شہرت ملک کے ہر حصے میں پھیل گئی۔ \n38۔ اور وہ عبادت گاہ سے اٹھا اور شمعون کے گھر میں داخل ہوا۔ اور شمعون کی بیوی کی والدہ شدید بخار میں مبتلا ہو گئیں؛ اور انہوں نے اس سے اس کے لیے درخواست کی۔ \n39۔ اور وہ اس کے اوپر کھڑا ہو گیا، اور بخار کو روک دیا؛ اور بخار ختم ہو گیا: اور فورا وہ اٹھ کر ان کی خدمت کرنے لگی۔ \n40۔ اب جب سورج غروب ہو رہا تھا، جو بھی مختلف بیماریوں میں مبتلا تھا وہ سب اسے اس کے پاس لے آیا؛ اور اس نے ہر ایک پر ہاتھ رکھے اور انہیں شفا دی۔ \n41۔ اور شیطان بھی بہت سے لوگوں میں سے نکلے، پکار اٹھے اور کہا، تو خدا کا بیٹا مسیح ہے۔ اور اس نے انہیں ملامت کی اور انہیں بولنے سے روکا: کیونکہ وہ جانتے تھے کہ وہ مسیح ہے۔ {بولنے کے لیے...: یا، یہ کہنے کے لیے کہ وہ اسے مسیح جانتے تھے}\n42۔ اور جب دن ہوا، وہ روانہ ہوا اور ایک ویران جگہ میں چلا گیا: اور لوگ اسے تلاش کرنے لگے، اس کے پاس آئے اور اسے روک دیا تاکہ وہ ان سے دور نہ ہو۔ \n43۔ اور اس نے ان سے کہا، مجھے خدا کی بادشاہی دوسرے شہروں کو بھی تبلیغ کرنی ہے: کیونکہ اسی لیے میں بھیجا گیا ہوں۔ \n44۔ اور وہ گلیل کی عبادت گاہوں میں تبلیغ کرتے تھے۔","1۔ اور ایسا ہوا کہ جب لوگ خدا کا کلام سننے کے لیے اس پر دباؤ ڈالے، تو وہ جنیساریت کی جھیل کے کنارے کھڑا رہا، \n2۔ اور جھیل کے کنارے دو جہاز کھڑے دیکھے: لیکن ماہی گیر ان سے نکل چکے تھے اور اپنے جال دھو رہے تھے۔ \n3۔ اور وہ ایک جہاز میں داخل ہوا، جو شمعون کا تھا، اور دعا کی کہ وہ زمین سے تھوڑا سا باہر نکلے۔ اور وہ بیٹھ گیا، اور لوگوں کو جہاز سے باہر نکالنے کی تعلیم دی۔ \n4۔ اب جب وہ بولنے سے نکلا، تو اس نے شمعون سے کہا، گہرائی میں نکل جاؤ، اور اپنے جال نیچے رکھ دو تاکہ ہوا بھر جائے۔ \n5۔ اور شمعون نے جواب میں کہا، مالک، ہم نے ساری رات محنت کی اور کچھ نہیں لیا؛ پھر بھی آپ کے حکم پر میں جال چھوڑ دوں گا۔ \n6۔ اور جب انہوں نے یہ سب کر لیا، تو انہوں نے بڑی تعداد میں مچھلیوں کو پکڑ لیا: اور ان کا جال ٹوٹ گیا۔ \n7۔ اور انہوں نے اپنے ساتھیوں کو، جو دوسرے جہاز میں تھے، اشارہ کیا کہ وہ آئیں اور ان کی مدد کریں۔ اور وہ آئے، اور دونوں جہازوں کو بھر دیا، یہاں تک کہ وہ ڈوبنے لگے۔ \n8۔ جب شمعون پطرس نے یہ دیکھا، تو وہ یسوع کے گھٹنوں کے پاس گر پڑا اور کہا، مجھ سے دور ہو جاؤ؛ کیونکہ میں گناہ گار آدمی ہوں، اے خداوند۔ \n9۔ کیونکہ وہ اور اس کے ساتھ موجود سب حیران رہ گئے کہ انہوں نے جو مچھلیاں پکڑی تھیں ان کے بہاؤ پر حیران رہ گئے: \n10۔ اسی طرح یعقوب اور یوحنا بھی، زبدی کے بیٹے، جو شمعون کے شریک تھے۔ اور یسوع نے شمعون سے کہا، ڈر مت؛ اب سے تم لوگوں کو پکڑو گے۔ \n11۔ اور جب وہ اپنے جہاز زمین پر لے آئے تو سب کچھ چھوڑ کر اس کے پیچھے چل پڑے۔ \n12۔ اور جب وہ ایک شہر میں تھا، تو ایک کوڑھ میں مبتلا آدمی کو دیکھا، جس نے یسوع کو اپنے چہرے پر گرا اور اس سے دعا کی، کہا، اے خداوند، اگر تم چاہو تو مجھے پاک کر سکتا ہے۔ \n13۔ اور اس نے اپنا ہاتھ آگے بڑھایا اور اسے چھوا، کہا، میں چاہوں گا: تم پاک ہو جاؤ۔ اور فورا کوڑھ اس کے جسم سے دور ہو گیا۔ \n14۔ اور اس نے اسے حکم دیا کہ کسی کو نہ بتائے: بلکہ جاؤ، اور خود کو پادری کے سامنے دکھاؤ، اور اپنی صفائی کے لیے پیش کرو، جیسا کہ موسیٰ نے حکم دیا تھا، ان کے سامنے گواہی کے لیے۔ \n15۔ لیکن اتنی ہی زیادہ اس کی شہرت پھیلتی گئی: اور بڑی تعداد جمع ہوئی تاکہ وہ سنیں اور ان کی کمزوریوں سے شفا پائیں۔ \n16۔ اور وہ بیابان میں چلا گیا، اور دعا کی۔ \n17۔ اور ایک دن ایسا ہوا جب وہ تعلیم دے رہا تھا، کہ فریسی اور شریعت کے ماہرین بیٹھے تھے، جو گلیل، یہودیہ اور یروشلم کے ہر شہر سے نکلے تھے: اور خداوند کی طاقت انہیں شفا دینے کے لیے موجود تھی۔ \n18۔ اور دیکھو، آدمیوں نے ایک ایسے آدمی کو بستر میں لایا جو فالج میں مبتلا تھا، اور انہوں نے اسے لانے اور اس کے سامنے رکھنے کے لیے [وسائل} تلاش کیے۔ \n19۔ اور جب وہ یہ نہ جان سکے کہ وہ اسے کس طرح لے جا سکتے ہیں، کیونکہ ہجوم بہت زیادہ تھا، تو وہ گھر کی چھت پر چڑھ گئے، اور اسے ٹائلنگ کے پار {اس کے} صوفے کے ساتھ یسوع کے سامنے بیچ میں اتارا۔ \n20۔ اور جب اس نے ان کا ایمان دیکھا تو اس سے کہا، انسان، تیرے گناہ معاف ہو گئے ہیں۔ \n21۔ اور کاتبوں اور فریسیوں نے استدلال شروع کیا، کہنے لگے، یہ کون ہے جو کفر کہتا ہے؟ کون گناہوں کو معاف کر سکتا ہے، سوائے صرف خدا کے؟ \n22. لیکن جب یسوع نے ان کے خیالات دیکھے، تو انہوں نے جواب دیا، تم اپنے دلوں میں کیا وجہ رکھتے ہو؟ \n23. کیا یہ کہنا آسان ہے کہ تمہارے گناہ معاف ہوں؛ یا یہ کہنا کہ اٹھو اور چلو؟ \n24۔ لیکن تاکہ تم جان لو کہ انسان کا بیٹا زمین پر گناہوں کو معاف کرنے کی طاقت رکھتا ہے، (اس نے پاگل بیمار سے کہا)، میں تم سے کہتا ہوں، اٹھو، اپنا صوفہ سنبھالو، اور اپنے گھر میں چلا جاؤ۔ \n25۔ اور فورا وہ ان کے سامنے کھڑا ہوا، اور جس پر وہ لیٹا تھا اسے اٹھا کر اپنے گھر چلا گیا، خدا کی جلال کرتے ہوئے۔ \n26۔ اور وہ سب حیران رہ گئے، خدا کی تمجید کی، اور خوف سے بھر گئے، کہنے لگے، آج ہم نے عجیب چیزیں دیکھی ہیں۔ \n27۔ اور ان سب باتوں کے بعد وہ باہر گیا، اور ایک پبلکن، جس کا نام لیوی تھا، کو کسٹم کی رسید پر بیٹھا دیکھا، اور اس نے اس سے کہا، میرے پیچھے آؤ۔ \n28۔ اور وہ سب کو چھوڑ گیا، اٹھا اور اس کے پیچھے گیا۔ \n29۔ اور لاوی نے اس کے اپنے گھر میں اس کے لیے ایک بڑی دعوت رکھی: اور وہاں ایک بڑی جماعت کے مالکان اور دیگر لوگ ان کے ساتھ بیٹھ گئے۔ \n30۔ لیکن ان کے کاتب اور فریسیوں نے اس کے شاگردوں کے خلاف سرگوشی کی، کہنے لگے، تم مالکان اور گناہ گاروں کے ساتھ کیوں کھاتے اور پیتے ہو؟ \n31۔ اور یسوع نے جواب میں ان سے کہا، جو صحت مند ہیں انہیں طبیب کی ضرورت نہیں؛ بلکہ جو بیمار ہیں۔ \n32. میں راستبازوں کو نہیں بلکہ گناہ گاروں کو توبہ کے لیے بلانا نہیں آیا۔ \n33۔ اور انہوں نے اس سے کہا، یوحنا کے شاگرد اکثر روزہ کیوں رکھتے ہیں، دعا کرتے ہیں، اور فریسیوں کے شاگردوں کے بھی؛ لیکن تم کھاتے اور پیتے ہو؟ \n34۔ اور اس نے ان سے کہا، کیا آپ دلہن کے بچوں کو روزہ رکھ سکتے ہیں، جب دولہا ان کے ساتھ ہے؟ \n35۔ لیکن وہ دن آئیں گے جب دولہا ان سے جدا ہو جائے گا، اور پھر وہ ان دنوں روزہ رکھیں گے۔ \n36۔ اور اس نے ان کے لیے ایک تمثیل بھی سنائی؛ کوئی شخص نئے لباس کا ٹکڑا پرانے پر نہیں پہنتا؛ اگر ایسا نہ ہو، تو نیا کپڑا دگڑتا ہے، اور جو ٹکڑا نئے سے لیا گیا ہے وہ پرانے سے متفق نہیں۔ \n37۔ اور کوئی انسان نئی شراب پرانی بوتلوں میں نہیں ڈالتا؛ ورنہ نئی شراب بوتلیں پھٹ جائے گی، گر جائے گی، اور بوتلیں ختم ہو جائیں گی۔ \n38۔ لیکن نئی شراب کو نئی بوتلوں میں ڈالنا ضروری ہے؛ اور دونوں کو محفوظ کیا جاتا ہے۔ \n39۔ کوئی انسان جو پرانی شراب پی چکا ہے، فورا نئی کی خواہش نہیں کرتا: کیونکہ وہ کہتا ہے، پرانا بہتر ہے۔","1۔ اور پہلے سبت کے بعد دوسرے سبت کو وہ مکئی کے کھیتوں سے گزرے؛ اور اس کے شاگردوں نے مکئی کے کانوں کو توڑ کر کھایا، اور انہیں اپنے ہاتھوں میں رگڑتے رہے۔\n2۔ اور کچھ فریسیوں نے ان سے کہا، تم وہ کام کیوں کرتے ہو جو سبت کے دن جائز نہیں؟\n3۔ اور یسوع نے ان کا جواب دیا، \"کیا تم نے یہ نہیں پڑھا، جو داؤد نے کیا، جب وہ خود بھوکا تھا، اور جو اس کے ساتھ تھے؛\n4۔ وہ خدا کے گھر میں گیا، اور روٹی لی اور کھائی، اور ان لوگوں کو بھی دیا جو اس کے ساتھ تھے؛ جو کھانا جائز نہیں بلکہ صرف پادریوں کے لیے ہے؟\n5۔ اور اس نے ان سے کہا، کہ انسان کا بیٹا بھی سبت کا رب ہے۔\n6۔ اور ایک اور سبت کو بھی وہ عبادت گاہ میں داخل ہوا اور تعلیم دی: اور ایک آدمی تھا جس کا دایاں ہاتھ خشک ہو چکا تھا۔\n7۔ اور کاتب اور فریسیوں نے اسے دیکھا، کہ کیا وہ سبت کے دن شفا دے گا؛ تاکہ وہ اس کے خلاف کوئی الزام تلاش کر سکیں۔\n8۔ لیکن وہ ان کے خیالات جانتا تھا، اور اس آدمی سے کہا جس کا ہاتھ مرجھا ہوا تھا، اٹھو اور درمیان میں کھڑا ہو جاؤ۔ اور وہ اٹھا اور کھڑا ہو گیا۔\n9۔ پھر یسوع نے ان سے کہا، میں تم سے ایک بات پوچھوں گا؛ کیا ہفتہ کے دن اچھا کرنا جائز ہے، یا برائی کرنا؟ زندگی بچانے کے لیے، یا اسے تباہ کرنے کے لیے؟\n10۔ اور سب کو دیکھتے ہوئے، اس نے اس آدمی سے کہا، اپنا ہاتھ بڑھاؤ۔ اور اس نے ایسا ہی کیا: اور اس کا ہاتھ دوسرے کی طرح مکمل طور پر بحال ہو گیا۔\n11۔ اور وہ پاگل پن سے بھر گئے؛ اور ایک دوسرے سے بات چیت کرتے کہ وہ یسوع کے ساتھ کیا کر سکتے ہیں۔\n12۔ اور ان دنوں ایسا ہوا کہ وہ ایک پہاڑ میں دعا کرنے گیا، اور ساری رات خدا سے دعا کرتا رہا۔\n13۔ اور جب دن ہوا، اس نے اپنے شاگردوں کو بلایا: اور ان میں سے بارہ چنے، جنہیں بھی رسول مقرر کیا؛\n14۔ شمعون (جسے اس نے پیٹر بھی نام دیا)، اور اس کا بھائی اینڈریو، جیمز اور جان، فلپ اور بارتھولومیو،\n15۔ متی اور تھامس، جیمز الفیوس کا {بیٹا}، اور شمعون کو زیلوٹس کہا جاتا ہے،\n16۔ اور یعقوب کا بھائی یھودا، اور یھودا اسخریوطی، جو خود بھی غدار تھا۔\n17۔ اور وہ ان کے ساتھ نیچے آیا، میدان میں کھڑا ہوا، اپنے شاگردوں کے ساتھ، اور یہودیہ اور یروشلم کے تمام لوگوں، اور صور اور صیدا کے سمندری ساحل سے، جو اس کی بات سننے آئے تھے اور اپنی بیماریوں سے شفا پانے آئے تھے؛\n18۔ اور وہ جو ناپاک روحوں سے پریشان تھے: اور وہ شفا پائے۔\n19۔ اور پوری ہجوم نے اسے چھونے کی کوشش کی: کیونکہ اس سے نیکی نکل گئی، اور سب کو شفا دی۔\n20۔ اور اس نے اپنے شاگردوں کی طرف آنکھیں اٹھائیں اور کہا، مبارک ہو [غریب]، کیونکہ خدا کی بادشاہی تمہاری ہے۔\n21. اب وہ بھوک مبارک ہو: کیونکہ تم بھر جاؤ گے۔ مبارک ہو وہ لوگ جو اب روتے ہیں: کیونکہ تم ہنسو گے۔\n22۔ مبارک ہو تم جب لوگ تم سے نفرت کریں گے، اور جب وہ تمہیں اپنی جماعت سے جدا کریں گے، تمہیں ملامت کریں گے، اور تمہارا نام برا کہہ کر نکالیں گے، انسان کے بیٹے کی خاطر۔\n23۔ اس دن پر خوشی مناؤ، اور خوشی سے چھلانگ لگاؤ: کیونکہ دیکھو، تمہارا اجر آسمان میں عظیم ہے: کیونکہ ان کے آباؤ اجداد نے بھی انبیاء کے ساتھ اسی طرح کیا۔\n24. لیکن تم امیر پر افسوس ہے! کیونکہ تمہیں تسلی مل گئی ہے۔\n25۔ تم پر جو بھرے ہوئے ہو افسوس! کیونکہ تم بھوکے رہو گے۔ اب تم پر اس ہنسی پر افسوس ہے! کیونکہ تم سوگ مناؤ گے اور روؤ گے۔\n26۔ تم پر افسوس، جب سب لوگ تمہارے بارے میں اچھا کہیں گے! کیونکہ ان کے آباؤ اجداد نے جھوٹے نبیوں کے لیے بھی ایسا ہی کیا۔\n27۔ لیکن میں تم سے کہتا ہوں جو سنتے ہیں، اپنے دشمنوں سے محبت کرو، ان لوگوں کے ساتھ اچھا سلوک کرو جو تم سے نفرت کرتے ہیں،\n28۔ ان لوگوں کو برکت دو جو تمہیں لعنت دیتے ہیں، اور ان کے لیے دعا کرو جو تمہیں بے رحمی سے استعمال کرتے ہیں۔\n29۔ اور جس نے تمہیں ایک گال پر مارا، اسے دوسرا بھی پیش کرو؛ اور جو تمہاری چادر لے جائے وہ تمہارا کوٹ بھی نہ اتارے۔\n30۔ ہر اس شخص کو دے جو تم سے مانگے؛ اور جو تمہاری چیزیں چھینتا ہے، اس سے دوبارہ نہ مانگو۔\n31۔ اور جیسا تم چاہتے ہو کہ لوگ تمہارے ساتھ کریں، تم بھی ان کے ساتھ ویسا ہی کرو۔\n32. اگر تم ان سے محبت کرتے ہو جو تم سے محبت کرتے ہیں، تو تم نے کیا شکر ادا کیا؟ کیونکہ گناہ گار بھی ان لوگوں سے محبت کرتے ہیں جو ان سے محبت کرتے ہیں۔\n33۔ اور اگر تم ان لوگوں کے ساتھ بھلائی کرو جو تمہارے ساتھ نیکی کرتے ہیں، تو تم نے کیا شکر ادا کیا؟ کیونکہ گناہ گار بھی ایسا ہی کرتے ہیں۔\n34۔ اور اگر آپ ان لوگوں کو قرض دیتے ہیں جنہیں آپ حاصل کرنا چاہتے ہیں، تو آپ کا کیا شکر ادا کرنا ہے؟ کیونکہ گناہ گار گناہ گاروں کو بھی قرض دیتے ہیں، تاکہ وہ دوبارہ اتنا ہی حاصل کریں۔\n35. لیکن اپنے دشمنوں سے محبت کرو، نیکی کرو، اور قرض دو، بغیر کسی امید کے؛ اور تمہارا اجر بڑا ہوگا، اور تم سب سے اعلیٰ کے بچے بنو گے: کیونکہ وہ ناشکرے اور برے لوگوں کے ساتھ مہربان ہے۔\n36. لہٰذا رحم دل بنو، جیسے تمہارا باپ بھی رحم کرنے والا ہے۔\n37۔ فیصلہ نہ کرو، اور تم پر فیصلہ نہیں کیا جائے گا: نہ مذمت کرو، اور نہ ہی تمہیں سزا دی جائے گی: معاف کرو، اور تم معاف ہو جاؤ گے:\n38۔ دیں، اور یہ آپ کو دی جائے گی؛ اچھی پیمائش، دبائے ہوئے، ہلکے ہوئے، اور دوڑتے ہوئے، لوگ تمہارے سینے میں جھک جائیں گے۔ کیونکہ جس پیمانے سے تم پورا کرو گے، اسی سے یہ تمہیں دوبارہ ناپا جائے گا۔\n39۔ اور اس نے ان سے ایک تمثیل سنائی، کیا اندھا اندھے کی رہنمائی کر سکتا ہے؟ کیا وہ دونوں کھائی میں نہیں گریں گے؟\n40۔ شاگرد اپنے استاد سے بالاتر نہیں: بلکہ جو بھی کامل ہے، وہ اس کا مالک ہوگا۔ {کہ...: یا، اس کے مالک کے طور پر مکمل کیا جائے گا}\n41۔ اور تم اپنے بھائی کی آنکھ میں جو روشنی ہے اسے کیوں دیکھتے ہو، لیکن اپنی آنکھ میں موجود روشنی کو نہیں دیکھتے؟\n42. یا پھر تم اپنے بھائی سے کیسے کہہ سکتے ہو، بھائی، مجھے تمہاری آنکھ میں موجود ذرہ نکالنے دو، جب تم خود اپنی آنکھ میں وہ شعاع نہیں دیکھ سکتے؟ اے منافق، پہلے اپنی آنکھ سے شعاع نکالو، اور پھر صاف دیکھو کہ اپنے بھائی کی آنکھ میں موجود ذرہ نکالو۔\n43۔ کیونکہ اچھا درخت خراب پھل نہیں دیتا؛ نہ ہی کوئی خراب درخت اچھا پھل دیتا ہے۔\n44۔ ہر درخت اپنے پھل سے پہچانا جاتا ہے۔ کیونکہ کانٹوں سے لوگ انجیر نہیں اگاتے، اور کانٹے دار جھاڑی سے انگور نہیں اگاتے۔ {انگور: گری۔ ایک انگور}\n45۔ ایک اچھا آدمی اپنے دل کے نیک خزانے سے نیکی پیدا کرتا ہے؛ اور ایک برا آدمی اپنے دل کے برے خزانے سے برائی پیدا کرتا ہے: کیونکہ دل کی فراوانی کے بارے میں اس کا منہ بولتا ہے۔\n46. اور تم مجھے کیوں پکارتے ہو، اے خداوند، خداوند، اور جو کچھ میں کہتا ہوں وہ کیوں نہیں کرتے؟\n47۔ جو بھی میرے پاس آئے، میری باتیں سنے، اور عمل کرے، میں تمہیں دکھاؤں گا کہ وہ کس کی طرح ہے:\n48۔ وہ ایسے آدمی کی طرح ہے جس نے گھر بنایا، گہرا کھودا اور چٹان پر بنیاد رکھی: اور جب سیلاب آیا، تو ندی اس گھر پر زور سے ٹکرائی، اور اسے ہلا نہ سکا، کیونکہ وہ ایک چٹان پر قائم تھا۔\n49۔ لیکن جو سنتا ہے اور نہیں کرتا، وہ ایسے انسان کی طرح ہے جس نے بغیر بنیاد کے زمین پر گھر بنایا؛ جس کے خلاف ندی زور زور سے بہہ رہی تھی، اور فورا گر گئی؛ اور اس گھر کی بربادی بہت اچھی تھی۔","1۔ اب جب اس نے عوام کے سامنے اپنی تمام باتیں ختم کیں، تو وہ کفرناؤم میں داخل ہوا۔\n2۔ اور ایک سینچورین کا خادم، جو اس کے لیے عزیز تھا، بیمار تھا اور مرنے کو تیار تھا۔\n3۔ اور جب اس نے یسوع کے بارے میں سنا تو اس نے یہودیوں کے بزرگوں کو اس کے پاس بھیجا اور اس سے التجا کی کہ وہ آئے اور اپنے خادم کو شفا دے۔\n4۔ اور جب وہ یسوع کے پاس آئے، تو فورا اس سے درخواست کی، کہ وہ اس کے لائق ہے جس کے لیے وہ یہ کرے:\n5۔ کیونکہ وہ ہماری قوم سے محبت کرتا ہے، اور اس نے ہمارے لیے ایک عبادت گاہ تعمیر کی ہے۔\n6۔ پھر یسوع ان کے ساتھ چلے گئے۔ اور جب وہ اب گھر سے زیادہ دور نہیں تھا، تو سینچورین نے اس کے دوست بھیجے اور کہا، اے خداوند، خود کو پریشان نہ کرو، کیونکہ میں اس قابل نہیں ہوں کہ تم میرے گھر کے نیچے آؤ:\n7۔ اسی لیے میں نے خود کو تمہارے پاس آنے کے لائق نہیں سمجھا، بس ایک لفظ میں کہو، اور میرا خادم شفا پا جائے گا۔\n8۔ کیونکہ میں بھی ایک ایسا آدمی ہوں جسے اختیار دیا گیا ہے، میرے سپاہی ہیں، اور میں ایک سے کہتا ہوں، جاؤ، اور وہ جائے گا؛ اور دوسرے کے پاس، آؤ، اور وہ آتا ہے؛ اور میرے خادم کو، یہ کرو، اور وہ کرے گا۔ {ایک: گری. یہ آدمی}\n9۔ جب یسوع نے یہ باتیں سنی، تو وہ اس پر حیران ہوا، اسے گھما دیا، اور اپنے پیروکاروں سے کہا، میں تم سے کہتا ہوں، میں نے اتنا بڑا ایمان نہیں پایا، نہیں، اسرائیل میں نہیں۔\n10۔ اور جو بھیجے گئے، گھر واپس آئے، انہوں نے نوکر کو بیمار حالت میں پایا۔\n11۔ اور اگلے دن ہوا کہ وہ ایک شہر نائین میں داخل ہوا؛ اور اس کے بہت سے شاگرد اس کے ساتھ گئے، اور بہت سے لوگ۔\n12۔ جب وہ شہر کے دروازے کے قریب پہنچا، تو وہاں ایک مردہ آدمی کو لے جایا گیا، جو اس کی ماں کا اکلوتا بیٹا تھا، اور وہ بیوہ تھی: اور شہر کے بہت سے لوگ اس کے ساتھ تھے۔\n13۔ اور جب خداوند نے اسے دیکھا، تو اس پر رحم ہوا، اور اس سے کہا، رو مت۔\n14۔ اور وہ آیا اور تابوت کو چھوا: اور جو لوگ اس کے برتن تھے وہ ساکت کھڑے رہے۔ اور اس نے کہا، نوجوان، میں تم سے کہتا ہوں، اٹھو۔ {بیئر: یا، تابوت}\n15۔ اور جو مردہ تھا وہ بیٹھ گیا اور بولنا شروع کیا۔ اور اس نے اسے اپنی ماں کے حوالے کیا۔\n16۔ اور سب پر خوف طاری ہو گیا: اور انہوں نے خدا کی تمجید کی، کہا کہ ہمارے درمیان ایک عظیم نبی جی اٹھا ہے؛ اور، خدا نے اپنے لوگوں سے ملاقات کی ہے۔\n17۔ اور اس کی یہ افواہ پورے یہودیہ اور آس پاس کے علاقے میں پھیل گئی۔\n18۔ اور یوحنا کے شاگردوں نے اسے یہ سب چیزیں دکھائی۔\n19۔ اور یوحنا نے اپنے دو شاگردوں کو یسوع کے پاس بھیجا، اور کہا، کیا تم آنا چاہتے ہو؟ یا ہم کسی اور کی تلاش میں ہیں؟\n20۔ جب مرد اس کے پاس آئے تو انہوں نے کہا، جان بپٹسٹ نے ہمیں تمہارے پاس بھیجا ہے، اور کہا، کیا تم وہ ہو جو آنا ہے؟ یا ہم کسی اور کی تلاش میں ہیں؟\n21۔ اور اسی وقت اس نے ان کی بہت سی بیماریوں، آفتوں، اور برے روحوں کو شفا دی؛ اور بہت سے اندھے لوگوں کو اس نے بینائی دی۔\n22۔ پھر یسوع نے جواب میں ان سے کہا، اپنا راستہ جاؤ، اور یوحنا کو بتاؤ کہ تم نے کیا دیکھا اور سنا؛ کہ اندھے دیکھتے ہیں، لنگڑے چلتے ہیں، کوڑھی پاک ہوتے ہیں، بہرے سنتے ہیں، مردہ زندہ ہوتے ہیں، غریبوں کے لیے خوشخبری سنائی جاتی ہے۔\n23. اور مبارک ہے {وہ}، جو مجھ میں ناراض نہ ہو۔\n24۔ اور جب یوحنا کے پیغامبر روانہ ہوئے، تو اس نے لوگوں سے جان کے بارے میں بات کرنا شروع کی، تم صحرا میں کیا دیکھنے گئے تھے؟ ہوا میں ہلتا ہوا سرکنڈے کی طرح؟\n25۔ لیکن تم دیکھنے کیوں گئے تھے؟ نرم لباس میں ملبوس آدمی؟ دیکھو، جو خوبصورت لباس پہنے ہوئے ہیں اور نرمی سے رہتے ہیں، وہ بادشاہوں کے درباروں میں ہیں۔\n26۔ لیکن تم دیکھنے کیوں گئے تھے؟ ایک نبی؟ ہاں، میں آپ سے کہتا ہوں، اور ایک نبی سے کہیں زیادہ۔\n27۔ یہ وہی ہے، جس کے بارے میں لکھا ہے، دیکھو، میں اپنا پیغام رساں تمہارے سامنے بھیجتا ہوں، جو تمہارے سامنے راستہ تیار کرے گا۔\n28۔ کیونکہ میں تم سے کہتا ہوں، جو عورتوں سے پیدا ہوئے ان میں یوحنا بپتسمہ دینے والے سے بڑا نبی نہیں، لیکن جو خدا کی بادشاہی میں سب سے کم ہے وہ اس سے بڑا ہے۔\n29۔ اور تمام لوگ جنہوں نے سنا، اور پبلکرز نے خدا کو جائز قرار دیا، اور یوحنا کے بپتسمہ سے بپتسمہ لیا۔\n30۔ لیکن فریسیوں اور وکیلوں نے اپنے خلاف خدا کی نصیحت کو مسترد کر دیا، کیونکہ انہوں نے خدا کا بپتسمہ نہیں لیا۔ {مسترد: یا، مایوس} {خلاف...: یا، اپنے اندر سے}\n31۔ اور خداوند نے فرمایا، تو پھر میں اس نسل کے لوگوں کو کس طرح تشبیہ دوں؟ اور وہ کیسے ہیں؟\n32۔ وہ ایسے ہیں جیسے بچے بازار میں بیٹھے ایک دوسرے کو پکارتے ہیں اور کہتے ہیں، ہم نے تم سے آواز نکالی ہے اور تم نے رقص نہیں کیا؛ ہم نے تمہارے لیے سوگ منایا ہے، اور تم نے نہیں رویا۔\n33۔ کیونکہ یوحنا بپتسمہ دینے والا نہ روٹی کھایا اور نہ شراب پیا؛ اور تم کہتے ہو، اس کے پاس شیطان ہے۔\n34۔ انسان کا بیٹا آیا ہے، کھاتا اور پیتا ہے؛ اور تم کہتے ہو، دیکھو ایک لالچی آدمی، اور ایک شراب پینے والا، جو پبلکرز اور گناہگاروں کا دوست ہے!\n35۔ لیکن حکمت اس کے تمام بچوں کے لیے جائز ہے۔\n36۔ اور فریسیوں میں سے ایک نے اسے چاہا کہ وہ اس کے ساتھ کھائے۔ اور وہ فریسی کے گھر گیا، اور کھانے کے لیے بیٹھ گیا۔\n37۔ اور دیکھو، شہر میں ایک عورت، جو گناہ گار تھی، جب اسے معلوم ہوا کہ {یسوع} فریسی کے گھر میں گوشت کھا رہا ہے، تو اس نے مرہم کا ایک الباسٹر ڈبہ لایا،\n38۔ اور اس کے پیچھے اس کے قدموں کے پاس کھڑی ہو کر روتی رہی، اور اس کے پاؤں آنسوؤں سے دھونے لگی، اور اپنے سر کے بالوں سے صاف کی، اس کے پاؤں کو چوما، اور مرہم سے ان پر مسح کیا۔\n39۔ اب جب وہ فریسی جس نے اسے حکم دیا تھا، نے دیکھا {یہ}، تو اس نے اپنے دل میں کہا، 'اگر یہ آدمی نبی ہوتا تو جانتا کہ کون سی اور کس قسم کی عورت ہے {یہ} اسے چھوتی ہے: کیونکہ وہ گناہ گار ہے۔\n40۔ اور یسوع نے جواب میں کہا، سائمن، مجھے تم سے کچھ کہنا ہے۔ اور وہ کہتا ہے، ماسٹر، آگے کہو۔\n41۔ ایک مخصوص قرض دہندہ تھا جس کے دو مقروض تھے: ایک پر پانچ سو پینس واجب الادا تھا، اور دوسرا پچاس۔\n42۔ اور جب ان کے پاس کچھ ادا کرنے کو نہیں تھا، تو اس نے صاف صاف دونوں کو معاف کر دیا۔ تو مجھے بتاؤ، ان میں سے کون اسے سب سے زیادہ محبت کرے گا؟\n43۔ سائمن نے جواب دیا اور کہا، میرا خیال ہے کہ {وہ}، جسے اس نے سب سے زیادہ معاف کیا۔ اور اس نے اسے کہا، تو نے صحیح فیصلہ کیا ہے۔\n44۔ اور اس نے عورت کی طرف رخ کیا اور شمعون سے کہا، کیا تم اس عورت کو دیکھ رہے ہو؟ میں تمہارے گھر میں داخل ہوا، تم نے میرے پیروں کے لیے پانی نہیں دیا، لیکن اس نے میرے پاؤں آنسوؤں سے دھوئے، اور اپنے سر کے بالوں سے صاف کر دیا۔\n45۔ تم نے مجھے کوئی بوسہ نہیں دیا: لیکن جب سے میں آیا ہوں، اس عورت نے میرے پاؤں کو چومنا بند نہیں کیا۔\n46۔ میرے سر کو تم نے تیل سے مسح نہیں کیا: لیکن اس عورت نے میرے پاؤں مرہم سے مسح کیے ہیں۔\n47۔ اسی لیے میں تم سے کہتا ہوں، اس کے بہت سے گناہ معاف کیے گئے ہیں؛ کیونکہ وہ بہت محبت کرتی تھی: لیکن جسے بہت کم معاف کیا جاتا ہے، {وہی} کم محبت کرتی ہے۔\n48۔ اور اس نے اس سے کہا، تیری غلطیاں معاف ہو گئی ہیں۔\n49۔ اور جو لوگ اس کے ساتھ گوشت پر بیٹھے تھے، انہوں نے دل ہی دل میں کہنا شروع کیا، یہ کون ہے جو گناہوں کو معاف کرتا ہے؟\n50۔ اور اس نے عورت سے کہا، تیری ایمان نے تمہیں بچایا ہے؛ امن سے جاؤ۔","1۔ اور بعد میں ایسا ہوا کہ وہ ہر شہر اور گاؤں میں گیا، خدا کی بادشاہی کی خوشخبری سنایا اور خوشخبری دی: اور بارہ اس کے ساتھ تھے،\n2۔ اور کچھ عورتیں، جو برے روحوں اور کمزوریوں سے شفا پا چکی تھیں، مریم نے مگدلین کو بلایا، جن میں سے سات شیطان نکلے،\n3۔ اور جوآنا، جو چوزا ہیرودیس کے سرپرست کی بیوی تھی، اور سوسانا، اور بہت سے دیگر، جنہوں نے اس کی خدمت کی۔\n4۔ اور جب بہت سے لوگ جمع ہوئے اور ہر شہر سے اس کے پاس آئے، تو اس نے ایک تمثیل سے کہا:\n5۔ ایک بیج بونے والا اپنا بیج بونے گیا: اور جب وہ بوتا تو کچھ راستے کے کنارے گر گئے؛ اور اسے روند دیا گیا، اور ہوا کے پرندوں نے اسے نگل لیا۔\n6۔ اور کچھ چٹان پر گر گئے؛ اور جیسے ہی یہ نکلا، وہ مرجھا گیا کیونکہ اس میں نمی نہیں تھی۔\n7۔ اور کچھ کانٹوں میں گر گئے؛ اور کانٹے اس کے ساتھ اٹھ گئے، اور اسے دبا دیا۔\n8۔ اور دوسرے اچھی زمین پر گر گئے، اور پھل سو گنا نکلے۔ اور جب اس نے یہ باتیں کہیں، تو اس نے پکارا، جو سننے کے لیے کان رکھتا ہے، اسے سننے دو۔\n9۔ اور اس کے شاگردوں نے اس سے پوچھا، کہا، یہ تمثیل کیا ہو سکتی ہے؟\n10۔ اور اس نے کہا، تمہیں خدا کی بادشاہی کے رازوں کو جاننا دیا گیا ہے: لیکن دوسروں کو تمثیلوں میں؛ کہ دیکھنا شاید وہ نہ دیکھ سکیں، اور سننا شاید وہ سمجھ نہ سکیں۔\n11. اب تمثیل یہ ہے: بیج خدا کا کلام ہے۔\n12۔ جو راستے کے کنارے ہیں وہ سنتے ہیں؛ پھر شیطان آتا ہے، اور ان کے دلوں سے کلام چھین لیتا ہے، ورنہ وہ ایمان لائیں گے اور نجات پائیں گے۔\n13۔ وہ چٹان پر ہیں {کیا وہ}، جو جب سنتے ہیں تو خوشی سے کلام قبول کرتے ہیں؛ اور ان کی کوئی جڑ نہیں، جو کچھ عرصے کے لیے ایمان رکھتی ہے، اور آزمائش کے وقت ختم ہو جاتی ہے۔\n14۔ اور جو کانٹوں کے درمیان گرے وہ ہیں، جو جب سنتے ہیں تو باہر نکلتے ہیں، اور زندگی کی فکروں، دولت اور خوشیوں میں مبتلا ہو جاتے ہیں، اور کمال تک کوئی پھل نہیں لاتے۔\n15۔ بلکہ وہ نیک زمین پر ہیں، جو ایماندار اور نیک دل میں، کلام سن کر، اسے سنبھالتے ہیں اور صبر سے پھل دیتے ہیں۔\n16. کوئی انسان جب موم بتی جلائے گا، اسے برتن سے ڈھانپتا ہے، یا بستر کے نیچے نہیں رکھتا؛ بلکہ اسے ایک شمعدان پر رکھ دیا جائے تاکہ جو لوگ اندر داخل ہوں وہ روشنی دیکھ سکیں۔\n17۔ کیونکہ کوئی راز نہیں جو ظاہر نہ ہو؛ نہ ہی {کوئی چیز} چھپی ہوئی، جو معلوم نہ ہو اور بیرون نہ آئے۔\n18۔ اس لیے دھیان سے سنو، کیونکہ جس کے پاس ہے، اسے دیا جائے گا؛ اور جس کے پاس نہیں ہے، وہ اس سے وہ سب لے جائے گا جو اس کے پاس نظر آتا ہے۔ {ظاہر ہوتا ہے...: یا، سوچتا ہے کہ اس نے کیا ہے}\n19۔ پھر اس کی ماں اور اس کے بھائیوں کے پاس آئے، اور پریس کے لیے ان پر حملہ نہ کر سکے۔\n20. اور اسے {یقینا} بتایا گیا کہ تمہاری ماں اور تمہارے بھائی باہر کھڑے ہیں، تمہیں دیکھنے کی خواہش میں۔\n21۔ اور اس نے جواب دیا اور ان سے کہا، میری ماں اور میرے بھائی وہ ہیں جو خدا کا کلام سنتے ہیں اور کرتے ہیں۔\n22۔ ایک دن ایسا ہوا کہ وہ اپنے شاگردوں کے ساتھ ایک جہاز میں گیا، اور اس نے ان سے کہا، آؤ جھیل کے دوسری طرف چلیں۔ اور وہ روانہ ہو گئے۔\n23۔ لیکن جب وہ روانہ ہوئے تو وہ سو گیا: اور جھیل پر ہوا کا طوفان آیا؛ اور وہ {پانی سے} بھر گئے اور خطرے میں تھے۔\n24۔ اور وہ اس کے پاس آئے اور اسے جگایا، کہا، آقا، آقا، ہم فنا ہو جائیں گے۔ پھر وہ اٹھا، اور ہوا اور پانی کے شور کو جواب دیا: اور وہ رک گئے، اور ایک سکون چھا گیا۔\n25۔ اور اس نے ان سے کہا، تمہارا ایمان کہاں ہے؟ اور وہ ڈر کر ایک دوسرے سے پوچھنے لگے، یہ کیسا انسان ہے! کیونکہ وہ ہواؤں اور پانی کو بھی حکم دیتا ہے، اور وہ اس کی اطاعت کرتے ہیں۔\n26۔ اور وہ گدارنیس کے ملک پہنچے، جو گلیل کے خلاف ہے۔\n27۔ اور جب وہ زمین پر نکلا، تو شہر سے باہر ایک آدمی ملا، جس کے پاس شیطان تھے، اور وہ کپڑے نہیں پہنتا تھا، نہ ہی کسی گھر میں رہتا تھا سوائے قبروں میں۔\n28۔ جب اس نے یسوع کو دیکھا، تو وہ پکارا اور اس کے سامنے گر پڑا، اور بلند آواز میں کہا، 'میرا تجھ سے کیا لینا دینا ہے، یسوع، {تو} خدا کے سب سے بلند بیٹے؟ میں تم سے التجا کرتا ہوں، مجھے اذیت نہ دو۔\n29۔ (کیونکہ اس نے ناپاک روح کو اس آدمی سے باہر آنے کا حکم دیا تھا۔ کیونکہ اکثر یہ اسے پکڑ لیتا تھا: اور اسے زنجیروں اور زنجیروں میں جکڑ دیا جاتا تھا؛ اور اس نے پٹیاں توڑ دیں، اور شیطان کو جنگل میں دھکیل دیا گیا۔)\n30۔ اور یسوع نے اس سے پوچھا، کہا کہ تیرا نام کیا ہے؟ اور اس نے کہا، لشکر: کیونکہ اس میں بہت سے شیطان داخل ہوئے۔\n31۔ اور انہوں نے اس سے التجا کی کہ وہ انہیں گہرائی میں جانے کا حکم نہ دے۔\n32۔ اور پہاڑ پر کئی سوروں کا ایک ریوڑ تھا جو کھا رہا تھا، اور انہوں نے اس سے درخواست کی کہ وہ انہیں ان میں داخل ہونے دے۔ اور وہ ان سب کو برداشت کرتا تھا۔\n33۔ پھر شیطان اس آدمی سے باہر نکل کر سور میں چلے گئے، اور ریوڑ زور سے جھیل میں ایک ڈھلوان جگہ سے نیچے دوڑا، اور انہیں گلا گھونٹنے لگا۔\n34۔ جب انہوں نے دیکھا کہ کیا ہوا، تو وہ بھاگ گئے اور شہر اور دیہات میں جا کر بتایا۔\n35۔ پھر وہ باہر گئے کہ دیکھیں کیا ہوتا ہے؛ اور یسوع کے پاس آیا، اور اس آدمی کو پایا، جس سے شیطان جدا ہو چکے تھے، یسوع کے قدموں میں بیٹھا تھا، کپڑوں میں اور ہوش میں تھا: اور وہ خوفزدہ تھے۔\n36۔ جنہوں نے دیکھا وہ بھی انہیں بتایا کہ جو شیطان کے قبضے میں تھا اسے کس طریقے سے شفا ملی۔\n37۔ پھر گدارینیز کے ارد گرد کے پورے ہجوم نے اس سے درخواست کی کہ وہ ان سے نکل جائے؛ کیونکہ وہ شدید خوف کے ساتھ گرفتار ہوئے: اور وہ جہاز میں چلا گیا، اور واپس لوٹ آیا۔\n38۔ اب وہ آدمی جس سے شیطان نکلے گئے تھے، اس نے اس سے درخواست کی کہ وہ اس کے ساتھ ہو سکے، لیکن یسوع نے اسے بھیج دیا اور کہا،\n39۔ اپنے گھر واپس جاؤ، اور دکھاؤ کہ خدا نے تمہارے ساتھ کتنے عظیم کام کیے ہیں۔ اور وہ اپنی راہ پر چلا گیا، اور پورے شہر میں پھیلایا کہ یسوع نے اس کے ساتھ کتنے عظیم کام کیے ہیں۔\n40۔ اور ایسا ہوا کہ جب یسوع واپس آیا تو لوگوں نے اسے خوش دلی سے قبول کیا: کیونکہ وہ سب اس کا انتظار کر رہے تھے۔\n41۔ اور دیکھو، ایک شخص آیا، یائرس نامی کنیسہ کا حکمران تھا، اور وہ یسوع کے قدموں میں گر پڑا اور اس سے التجا کی کہ وہ اس کے گھر میں آئے:\n42۔ کیونکہ اس کی ایک اکلوتی بیٹی تھی، تقریبا بارہ سال کی، اور وہ مرنے والی تھی۔ لیکن جیسے ہی وہ جا رہا تھا، لوگ اس کے ہجوم میں جمع ہو گئے۔\n43۔ اور ایک عورت جس کا بارہ سال کا خون تھا، جو اپنی ساری زندگی طبیبوں پر گزار چکا تھا، وہ کسی سے بھی شفا نہیں پا سکتی تھی،\n44۔ اس کے پیچھے آئی اور اس کے لباس کے کنارے کو چھوا: اور فورا اس کے خون کا بہاؤ رک گیا۔\n45۔ اور یسوع نے کہا، کس نے مجھے چھوا؟ جب سب نے انکار کیا، پیٹر اور اس کے ساتھ جو لوگ تھے انہوں نے کہا، استاد، ہجوم آپ پر جمع ہو کر آپ پر دباؤ ڈالتا ہے، اور آپ کہتے ہیں، کس نے مجھے چھوا؟\n46۔ اور یسوع نے کہا، کسی نے مجھے چھوا ہے: کیونکہ میں دیکھتا ہوں کہ میری نیکی ختم ہو گئی ہے۔\n47۔ اور جب عورت نے دیکھا کہ وہ چھپی نہیں ہے، تو وہ کانپتی ہوئی آئی، اور اس کے سامنے گر گئی، اس نے سب کے سامنے بتایا کہ اس نے اسے کس مقصد کے لیے چھوا ہے، اور وہ فورا شفا پا گئی۔\n48۔ اور اس نے اس سے کہا، بیٹی، آرام دہ رہو: تمہارا ایمان تمہیں مکمل بنا چکا ہے؛ امن سے جاؤ۔\n49۔ جب وہ بول رہا تھا، عبادت گاہ کے حکمران کی طرف سے ایک آیا، جو کہتا ہے، تیری بیٹی مر چکی ہے؛ مسئلہ ماسٹر کو نہیں۔\n50۔ لیکن جب یسوع نے سنا، تو اس نے جواب دیا، کہا، خوف نہ کرو: صرف ایمان لاؤ، اور وہ مکمل ہو جائے گی۔\n51۔ اور جب وہ گھر میں آیا، تو اس نے کسی کو اندر جانے کی اجازت نہیں دی، سوائے پطرس، جیمز، اور یوحنا، اور کنواری کے والد اور والدہ کے۔\n52۔ اور سب روئے، اور اس پر افسوس کرنے لگے: لیکن اس نے کہا، رونا مت؛ وہ مری نہیں، بلکہ سو رہی ہے۔\n53۔ اور وہ اس پر ہنس کر طنز کرتے تھے، جانتے ہوئے کہ وہ مر چکی ہے۔\n54۔ اور اس نے سب کو بجھا دیا، اس کا ہاتھ پکڑا اور پکارا، لڑکی، اٹھو۔\n55۔ اور اس کی روح دوبارہ آئی، اور وہ فورا اٹھ کھڑی ہوئی: اور اس نے حکم دیا کہ اسے گوشت دے۔\n56۔ اور اس کے والدین حیران رہ گئے: لیکن اس نے انہیں حکم دیا کہ وہ کسی کو نہ بتائیں کہ کیا ہوا۔","1۔ پھر اس نے اپنے بارہ شاگردوں کو اکٹھا کیا، اور انہیں تمام شیطانوں پر طاقت اور اختیار دیا، اور بیماریوں کا علاج کیا۔\n2۔ اور اس نے انہیں خدا کی بادشاہی کی تبلیغ کرنے اور بیماروں کو شفا دینے کے لیے بھیجا۔\n3۔ اور اس نے ان سے کہا، اپنے سفر کے لیے کچھ نہ لو، نہ لکڑی، نہ روٹی، نہ پیسہ؛ دونوں کے پاس دو دو کوٹ نہیں ہیں۔\n4۔ اور جس بھی گھر میں تم داخل ہو، وہاں رہتا ہے اور وہاں سے روانہ ہو جاتا ہے۔\n5۔ اور جو تمہیں قبول نہیں کرتا، جب تم اس شہر سے باہر جاؤ گے، تو اپنے پیروں کی گرد جھاڑ دے تاکہ ان کے خلاف گواہی دے۔\n6۔ اور وہ روانہ ہوئے، اور شہروں میں گئے، انجیل کی تبلیغ کی، اور ہر جگہ شفا دی۔\n7۔ اب ہیرودیس ٹیٹرارک نے اپنے کیے گئے تمام کاموں کے بارے میں سنا: اور وہ حیران ہوا، کیونکہ کچھ لوگوں کے بارے میں کہا جاتا ہے کہ یوحنا مردوں میں سے زندہ ہوا؛\n8۔ اور کچھ میں، ایلیاس ظاہر ہوا تھا؛ اور کچھ کے بارے میں، کہ پرانے نبیوں میں سے ایک دوبارہ زندہ ہوا۔\n9۔ اور ہیرودیس نے کہا، یوحنا نے سر قلم کر دیا ہے، لیکن یہ کون ہے جس کے بارے میں میں ایسی باتیں سن رہا ہوں؟ اور وہ اسے دیکھنا چاہتا تھا۔\n10۔ اور جب رسولوں کو واپس کیا گیا تو انہوں نے اسے سب کچھ بتایا جو انہوں نے کیا تھا۔ اور اس نے انہیں لیا، اور چپکے سے ایک صحرائی جگہ میں چلا گیا جو شہر بیت صیدا کہلاتا تھا۔\n11۔ اور لوگ، جب انہیں معلوم ہوا، تو اس کے پیچھے گئے: اور اس نے انہیں قبول کیا، اور خدا کی بادشاہی کے بارے میں ان سے بات کی، اور ان کو شفا دی جنہیں شفا کی ضرورت تھی۔\n12۔ اور جب دن ختم ہونے لگا، تو بارہ آئے اور اس سے کہا، ہجوم کو بھیج دو، تاکہ وہ آس پاس کے شہروں اور دیہات میں جا کر قیام کریں اور خوراک حاصل کریں: کیونکہ ہم یہاں ایک صحرا میں ہیں۔\n13۔ لیکن اس نے ان سے کہا، انہیں کھانے کے لیے دو۔ اور انہوں نے کہا، ہمارے پاس صرف پانچ روٹیاں اور دو مچھلیاں ہیں؛ سوائے اس کے کہ ہمیں ان سب لوگوں کے لیے گوشت خریدنا چاہیے۔\n14۔ کیونکہ وہ تقریبا پانچ ہزار آدمی تھے۔ اور اس نے اپنے شاگردوں سے کہا، انہیں پچاس کی دہائی تک ایک کمپنی میں بٹھا دو۔\n15۔ اور انہوں نے ایسا ہی کیا، اور سب کو بٹھا دیا۔\n16۔ پھر اس نے پانچ روٹیاں اور دو مچھلیاں اٹھائیں، آسمان کی طرف دیکھتے ہوئے انہیں برکت دی، بریک کیا، اور شاگردوں کو ہجوم کے سامنے رکھ دیا۔\n17۔ اور انہوں نے کھایا، اور سب بھر گئے: اور ان کے پاس بارہ ٹوکریاں باقی رہ گئیں، ٹکڑوں میں سے اٹھا لیا گیا۔\n18۔ اور ایسا ہوا، جب وہ اکیلا دعا کر رہا تھا، اس کے شاگرد اس کے ساتھ تھے: اور اس نے ان سے پوچھا، پوچھا، وہ لوگ کون کہتے ہیں کہ میں کون ہوں؟\n19۔ انہوں نے جواب دیا، یوحنا بپتسمہ دینے والا؛ لیکن کچھ {کہتے ہیں}، ایلیاس؛ اور دوسرے {کہتے ہیں} کہ پرانے نبیوں میں سے ایک دوبارہ زندہ ہو گیا ہے۔\n20۔ اس نے ان سے کہا، لیکن تم کون کہتے ہو کہ میں کون ہوں؟ پیٹر نے جواب دیا، خدا کا مسیح۔\n21۔ اور اس نے سختی سے ان پر حملہ کیا، اور حکم دیا کہ وہ کسی کو یہ بات نہ بتائیں؛\n22۔ کہتے ہوئے، انسان کے بیٹے کو بہت سی چیزیں برداشت کرنی ہوں گی، بزرگوں، سردار کاہنوں اور کاتبوں سے انکار کیا جائے گا، قتل کیا جائے گا، اور تیسرے دن زندہ ہوگا۔\n23۔ اور اس نے سب سے کہا، اگر کوئی {انسان} میرے پیچھے آئے گا، تو وہ خود کو انکار کرے، روزانہ اپنی صلیب اٹھا لے، اور میری پیروی کرے۔\n24۔ جو اپنی جان بچائے گا وہ اسے کھو دے گا: لیکن جو میری خاطر اپنی جان دے گا، وہ اسے بچا لے گا۔\n25۔ کیونکہ انسان کو کیا فائدہ ہے اگر وہ پوری دنیا حاصل کر لے، خود کو کھو دے، یا پھینک دیا جائے؟\n26۔ جو بھی مجھ سے اور میرے الفاظ سے شرمندہ ہوگا، اس سے انسان کا بیٹا شرمندہ ہوگا، جب وہ اپنی شان میں، اپنے باپ کے ساتھ، اور مقدس فرشتوں کے ساتھ آئے گا۔\n27۔ لیکن میں آپ کو ایک سچ بتاتا ہوں، یہاں کچھ لوگ کھڑے ہیں جو موت کا ذائقہ نہیں چکھیں گے، جب تک کہ وہ خدا کی بادشاہی نہ دیکھیں۔\n28۔ اور ان اقوال کے تقریبا آٹھ دن بعد، اس نے پیٹر، یوحنا اور یعقوب کو لے کر پہاڑ پر چڑھ کر دعا کی۔ {اقوال: یا، چیزیں}\n29۔ اور جب وہ دعا کر رہا تھا، اس کے چہرے کا انداز بدل گیا، اور اس کا لباس سفید اور چمک رہا تھا۔\n30۔ اور دیکھو، اس سے دو آدمی بات کر رہے تھے، جو موسیٰ اور ایلیاس تھے:\n31۔ جو جلال کے ساتھ ظاہر ہوا، اور اپنی موت کے بارے میں بات کی جو اسے یروشلم میں مکمل کرنا تھا۔\n32۔ لیکن پیٹر اور جو اس کے ساتھ تھے وہ نیند میں بھاری تھے: اور جب وہ جاگے تو انہوں نے اس کی شان دیکھی، اور وہ دو آدمی جو اس کے ساتھ کھڑے تھے۔\n33۔ اور جب وہ اس سے رخصت ہوئے، پطرس نے یسوع سے کہا، استاد، ہمارے لیے یہاں ہونا اچھا ہے: اور ہم تین خیمہ بنائیں؛ ایک تمہارے لیے، ایک موسیٰ کے لیے، اور ایک ایلیاس کے لیے: یہ نہ جانتے ہوئے کہ اس نے کیا کہا۔\n34۔ جب وہ ایسا بول رہا تھا، ایک بادل آیا اور ان پر سایہ ڈال گیا: اور وہ بادل میں داخل ہوتے ہوئے خوفزدہ ہو گئے۔\n35۔ اور بادل سے ایک آواز آئی، کہنے لگی، یہ میرا پیارا بیٹا ہے: اسے سنو۔\n36۔ اور جب آواز ختم ہو گئی، یسوع اکیلا پایا گیا۔ اور انہوں نے اسے اپنے قریب رکھا، اور ان دنوں کسی کو ان باتوں کو نہیں بتایا جو انہوں نے دیکھی تھیں۔\n37۔ اور ایسا ہوا کہ اگلے دن، جب وہ پہاڑی سے نیچے آئے، بہت سے لوگ اس سے ملے۔\n38۔ اور دیکھو، جماعت کے ایک آدمی نے پکارا، آقا، میں تم سے التجا کرتا ہوں، میرے بیٹے کو دیکھو، کیونکہ وہ میرا اکلوتا بچہ ہے۔\n39۔ اور دیکھو، ایک روح اسے لے لیتی ہے، اور وہ اچانک پکار اٹھتا ہے؛ اور یہ اسے چیر دیتا ہے کہ وہ دوبارہ جھاگ نکالتا ہے، اور زخم اس کے جسم سے بمشکل دور ہوتے ہیں۔\n40۔ اور میں نے تمہارے شاگردوں سے درخواست کی کہ اسے نکال دیں؛ اور وہ نہیں کر سکتے تھے۔\n41۔ اور یسوع نے جواب دیا، اے بے ایمان اور گمراہ نسل، میں کب تک تمہارے ساتھ رہوں گا اور تمہیں برداشت کروں گا؟ اپنے بیٹے کو یہاں لے آؤ۔\n42۔ اور جب وہ ابھی آ رہا تھا، شیطان نے اسے گرا دیا، اور اسے گرا دیا۔ اور یسوع نے ناپاک روح کو ملامت کی، بچے کو شفا دی اور اسے دوبارہ اپنے باپ کے حوالے کیا۔\n43۔ اور وہ سب خدا کی عظیم طاقت پر حیران رہ گئے۔ لیکن جب وہ ہر چیز پر حیران تھے جو یسوع نے کیا، اس نے اپنے شاگردوں سے کہا،\n44۔ یہ باتیں آپ کے کانوں میں اتر جائیں: کیونکہ انسان کا بیٹا انسانوں کے ہاتھوں میں دیا جائے گا۔\n45۔ لیکن وہ اس قول کو نہیں سمجھ سکے، اور یہ ان سے چھپا دیا گیا کہ وہ اسے نہ سمجھ سکیں: اور وہ اس قول کے بارے میں پوچھنے سے ڈرتے تھے۔\n46۔ پھر ان میں ایک منطق پیدا ہوئی کہ ان میں سے کون سب سے بڑا ہونا چاہیے۔\n47۔ اور یسوع نے ان کے دل کے خیال کو دیکھ کر ایک بچے کو لیا اور اسے اس کے ساتھ پیدا کیا،\n48۔ اور میں نے ان سے کہا، جو بھی میرے نام پر اس بچے کو قبول کرے گا، وہ مجھے قبول کرے گا؛ اور جو مجھے قبول کرے گا وہ مجھے بھیجنے والا قبول کرے گا: کیونکہ جو تم سب میں سب سے چھوٹا ہے، وہی عظیم ہوگا۔\n49۔ اور یوحنا نے جواب دیا اور کہا، استاد، ہم نے ایک کو تمہارے نام پر شیطانوں کو نکالتے دیکھا؛ اور ہم اسے منع کرتے ہیں، کیونکہ وہ ہمارے ساتھ نہیں چلتا۔\n50۔ اور یسوع نے اسے کہا، اسے منع نہ کرو، کیونکہ جو ہمارے خلاف نہیں ہے وہ ہمارے لیے ہے۔\n51۔ اور جب وقت آیا کہ اسے اٹھایا جائے، تو اس نے ثابت قدمی سے یروشلم جانے کے لیے اپنا چہرہ رکھا،\n52۔ اور اس کے سامنے پیغامبر بھیجے، اور وہ سامریوں کے ایک گاؤں میں داخل ہوئے تاکہ اس کے لیے تیاری کریں۔\n53۔ اور انہوں نے اسے قبول نہیں کیا، کیونکہ اس کا چہرہ ایسا تھا جیسے وہ یروشلم جا رہا ہو۔\n54۔ اور جب اس کے شاگردوں یعقوب اور یوحنا نے یہ دیکھا، تو انہوں نے کہا، اے خداوند، کیا تو کیا تو حکم دے گا کہ آگ آسمان سے اترے، اور انہیں بھی، جیسے ایلیاس نے کیا تھا؟\n55۔ لیکن اس نے پلٹ کر انہیں ڈانٹا اور کہا، تم نہیں جانتے کہ تم کس روح کے ہو۔\n56۔ کیونکہ انسان کا بیٹا انسانوں کی زندگیوں کو تباہ کرنے نہیں آیا بلکہ انہیں بچانے آیا ہے۔ اور وہ دوسرے گاؤں چلے گئے۔\n57۔ اور ایسا ہوا کہ جب وہ راستے میں جا رہے تھے، ایک شخص نے اس سے کہا، خداوند، میں جہاں بھی تم جاؤ گے تمہارے پیچھے چلوں گا۔\n58۔ اور یسوع نے اس سے کہا، لومڑیوں کے سوراخ ہوتے ہیں، اور ہوا کے پرندوں کے گھونسلے ہوتے ہیں؛ لیکن انسان کے بیٹے کے پاس اپنا سر رکھنے کی جگہ نہیں ہے۔\n59۔ اور اس نے دوسرے سے کہا، میرے پیچھے آؤ۔ لیکن اس نے کہا، اے خداوند، مجھے پہلے اجازت دے کہ میں جا کر اپنے والد کو دفن کروں۔\n60۔ یسوع نے اس سے کہا، مردوں کو اپنے مردوں کو دفن کرنے دو، لیکن تو جا کر خدا کی بادشاہی کی تبلیغ کرو۔\n61۔ اور ایک اور نے یہ بھی کہا، خداوند، میں تیری پیروی کروں گا؛ لیکن پہلے میں انہیں الوداع کہنے چلوں، جو میرے گھر پر ہیں۔\n62۔ اور یسوع نے اس سے کہا، کوئی انسان، ہل پر ہاتھ ڈال کر اور پیچھے مڑ کر دیکھے، خدا کی بادشاہی کے لائق نہیں ہے۔","1۔ ان باتوں کے بعد خداوند نے دیگر ستر کو بھی مقرر کیا، اور انہیں اپنے سامنے ہر شہر اور جگہ بھیجا، جہاں وہ خود آئے گا۔\n2۔ لہٰذا اس نے ان سے کہا، فصل واقعی عظیم ہے، لیکن مزدور کم ہیں: لہٰذا فصل کے رب سے دعا کرو کہ وہ اپنی فصل میں مزدور بھیجے۔\n3۔ اپنے راستے جاؤ: دیکھو، میں تمہیں بھیڑیوں کے درمیان بھیڑ کی طرح بھیجتا ہوں۔\n4. نہ پرس، نہ کاغذ، نہ جوتے: اور ویسے کسی کو سلام نہ کرنا۔\n5۔ اور جس بھی گھر میں داخل ہو، پہلے اس گھر میں سلام فرما۔\n6۔ اور اگر امن کا بیٹا وہاں ہو، تو تمہارا امن اسی پر ہوگا؛ اگر نہیں، تو وہ دوبارہ تمہاری طرف لوٹے گا۔\n7۔ اور ایک ہی گھر میں رہو، وہ چیزیں کھاؤ اور پیو جو وہ دیتے ہیں: کیونکہ مزدور اپنی اجرت کے لائق ہے۔ گھر گھر نہ جاؤ۔\n8۔ اور جس بھی شہر میں تم داخل ہو، اور وہ تمہیں قبول کریں، وہ چیزیں کھاؤ جو تمہارے سامنے رکھی گئی ہوں:\n9۔ اور ان بیماروں کو شفا دو جو وہاں ہیں، اور ان سے کہو، خدا کی بادشاہی تمہارے قریب آ گئی ہے۔\n10۔ لیکن جس بھی شہر میں تم داخل ہو، اور وہ تمہیں قبول نہ کریں، تو اپنے راستے اسی شہر کی گلیوں میں چلے جاؤ اور کہو،\n11۔ حتیٰ کہ تمہارے شہر کی مٹی بھی، جو ہم پر جڑی ہوئی ہے، ہم تم پر صاف کرتے ہیں: اگرچہ تم اس بات پر یقین رکھو کہ خدا کی بادشاہی تمہارے قریب آ چکی ہے۔\n12۔ لیکن میں تم سے کہتا ہوں کہ اس دن سدوم کے لیے اس شہر سے زیادہ برداشت کرنا ہوگا۔\n13۔ تم پر افسوس، چورازن! تم پر افسوس ہے، بیت سعیدا! کیونکہ اگر وہ عظیم کام صور اور صیدا میں کیے جاتے، جو تم میں کیے گئے، تو وہ کافی عرصہ پہلے توبہ کر چکے تھے، تھیلے اور راکھ میں بیٹھے ہوئے۔\n14۔ لیکن یہ صور اور صیدا کے لیے فیصلے پر تمہارے مقابلے میں زیادہ قابل برداشت ہوگا۔\n15. اور تم، کفرناحوم، جو آسمان کی طرف بلند ہو، جہنم میں پھینک دیا جائے گا۔\n16۔ جو تمہیں سنتا ہے وہ مجھے سنتا ہے؛ اور جو تم سے نفرت کرتا ہے وہ مجھ سے نفرت کرتا ہے؛ اور جو مجھے حقیر سمجھتا ہے، وہ اس سے نفرت کرتا ہے جس نے مجھے بھیجا۔\n17۔ اور ستر خوشی سے واپس آئے اور کہا، اے خداوند، یہاں تک کہ شیطان بھی تیرے نام کے ذریعے ہمارے تابع ہیں۔\n18۔ اور اس نے ان سے کہا، میں نے شیطان کو آسمان سے بجلی کی طرح دیکھا۔\n19۔ دیکھو، میں تمہیں سانپوں اور بچھوؤں پر چلنے کی طاقت دیتا ہوں، اور دشمن کی تمام طاقت پر بھی تمہیں کوئی نقصان نہیں پہنچا سکتا۔\n20۔ اس میں خوش نہ ہو کہ روحیں تمہارے تابع ہیں؛ بلکہ خوش رہو، کیونکہ تمہارے نام جنت میں لکھے گئے ہیں۔\n21۔ اسی وقت یسوع نے روح میں خوشی منائی اور کہا، اے باپ، آسمان و زمین کے رب، میں تیرا شکر ادا کرتا ہوں کہ تو نے یہ باتیں داناؤں اور سمجھداروں سے چھپائیں اور بچوں پر ظاہر کیں: اسی طرح، اے باپ؛ کیونکہ یہ تمہاری نظر میں اچھا لگا۔\n22۔ میرے باپ کی طرف سے سب کچھ مجھے دیا گیا ہے: اور کوئی نہیں جانتا کہ بیٹا کون ہے، سوائے باپ کے؛ اور باپ کون ہے، سوائے بیٹے، اور {وہ} جسے بیٹا ظاہر کرے گا۔ {بہت سی قدیم نقول یہ الفاظ نظم کے آغاز میں شامل کرتی ہیں، اور اپنے شاگردوں کی طرف مڑ کر انہوں نے کہا}\n23۔ اور اس نے اسے اپنے شاگردوں کے پاس بلایا اور دل ہی دل میں کہا، مبارک ہو وہ آنکھیں جو وہ چیزیں دیکھتی ہیں جو تم دیکھتے ہو:\n24۔ کیونکہ میں تمہیں بتاتا ہوں، کہ بہت سے نبی اور بادشاہ وہ چیزیں دیکھنے کی خواہش رکھتے تھے جو تم دیکھتے ہو، لیکن انہوں نے نہیں دیکھا؛ اور ان باتوں کو سننا جو تم نے سنا اور نہیں سنا۔\n25۔ اور دیکھو، ایک وکیل کھڑا ہوا اور اسے آزمایا اور کہا، مالک، میں ابدی زندگی کے لیے کیا کروں؟\n26۔ اس نے اس سے کہا، قانون میں کیا لکھا ہے؟ آپ کیسے پڑھتے ہیں؟\n27۔ اور اس نے جواب دیا، \"تو اپنے خداوند خدا سے اپنے تمام دل، اپنی پوری جان، اپنی پوری طاقت اور پورے ذہن سے محبت کرے؛ اور اپنے پڑوسی کو اپنی ذات کے طور پر۔\n28۔ اور اس نے اسے کہا، تو نے صحیح جواب دیا ہے: ایسا کرو، اور تم زندہ رہو گے۔\n29۔ لیکن وہ، اپنے آپ کو توجیہ دینے کے لیے تیار ہو کر، یسوع سے کہا، اور میرا پڑوسی کون ہے؟\n30۔ اور یسوع نے جواب دیا، \"ایک {آدمی} یروشلم سے یریحو نیچے آیا، چوروں کے درمیان گر گیا، جنہوں نے اس کا لباس اتار دیا، زخمی کر دیا، اور وہ آدھا مردہ چھوڑ گیا۔\n31۔ اور اتفاقا ایک پادری اس طرف نیچے آیا، اور جب اس نے اسے دیکھا تو وہ دوسری طرف سے گزرا۔\n32. اسی طرح ایک لاوی جب وہاں تھا تو آیا اور اسے دیکھا، اور دوسری طرف سے گزرا۔\n33۔ لیکن ایک سامری، جب وہ سفر کر رہا تھا، وہاں پہنچا جہاں وہ تھا: اور جب اس نے اسے دیکھا تو اس پر رحم ہوا،\n34۔ اور اس کے پاس گیا، اس کے زخموں کو باندھا، تیل اور شراب ڈالی، اسے اس کے اپنے جانور پر بٹھایا، ایک سرائے میں لے گیا اور اس کا خیال رکھا۔\n35۔ اور کل جب وہ روانہ ہوا، تو اس نے دو پینس نکالے اور لشکر کو دے دیے، اور اس سے کہا، اس کا خیال رکھنا؛ اور جو کچھ بھی تم مزید خرچ کرو گے، جب میں دوبارہ آؤں گا، میں تمہیں واپس دوں گا۔\n36۔ کیا تم سمجھتے ہو کہ ان تینوں میں سے کون اس کا پڑوسی تھا جو چوروں میں گرا؟\n37۔ اور اس نے کہا، 'وہ جس نے اس پر رحم کیا۔ پھر یسوع نے اس سے کہا، جاؤ، اور تم بھی ایسا ہی کرو۔\n38۔ اب جب وہ جا رہے تھے، ایسا ہوا کہ وہ ایک خاص گاؤں میں داخل ہوا: اور ایک عورت مارٹھا نے اسے اپنے گھر میں قبول کیا۔\n39۔ اور اس کی ایک بہن تھی جس کا نام مریم تھا، جو یسوع کے قدموں میں بیٹھی اور اس کا کلام سنتی تھی۔\n40۔ لیکن مارٹھا بہت سی خدمت میں مصروف تھی، اور اس کے پاس آئی اور کہا، خداوند، کیا تمہیں پرواہ نہیں کہ میری بہن نے مجھے اکیلا خدمت کے لیے چھوڑ دیا ہے؟ اس لیے میں نے اسے کہا کہ وہ میری مدد کرے۔\n41۔ اور یسوع نے جواب دیا اور اس سے کہا، مارٹھا، مارٹھا، تم بہت سی باتوں میں محتاط اور پریشان ہو:\n42۔ لیکن ایک چیز ضروری ہے: اور مریم نے وہ اچھا حصہ چنا ہے جو اس سے چھینا نہیں جائے گا۔","1۔ اور ایسا ہوا کہ جب وہ ایک جگہ پر دعا کر رہا تھا، جب وہ رک گیا، اس کے ایک شاگرد نے اسے کہا، اے خداوند، ہمیں دعا کرنا سکھاؤ، جیسے جان نے اپنے شاگردوں کو بھی سکھایا۔\n2۔ اور اس نے ان سے کہا، جب تم دعا کرتے ہو، تو کہو، اے ہمارے باپ جو آسمانوں میں ہے، تیرا نام پاک ہو۔ تیری بادشاہی آ جائے۔ تیری مرضی پوری ہو، جیسے آسمان میں، زمین میں بھی۔\n3. ہمیں روزانہ کی روٹی دو۔ {دن بہ دن: یا، دن کے لیے}\n4۔ اور ہمارے گناہوں کو معاف کر دے؛ کیونکہ ہم ہر اس شخص کو معاف کرتے ہیں جو ہمارا مقروض ہے۔ اور ہمیں آزمائش میں نہ ڈالیں؛ لیکن ہمیں برائی سے بچا۔\n5۔ اور اس نے ان سے کہا، تم میں سے کون دوست ہوگا، اور آدھی رات کو اس کے پاس جائے گا اور اسے کہے گا، دوست، مجھے تین روٹیاں دے دو؛\n6. کیونکہ میرے ایک دوست کے سفر میں وہ میرے پاس آیا ہے، اور میرے پاس اس کے سامنے رکھنے کے لیے کچھ نہیں؟ {اندر...: یا، اس کے راستے سے ہٹ جاؤ}\n7۔ اور وہ اندر سے جواب دے گا اور کہے گا: مجھے پریشان نہ کرو: دروازہ اب بند ہے، اور میرے بچے میرے ساتھ بستر پر ہیں؛ میں اٹھ کر تمہیں نہیں دے سکتا۔\n8۔ میں تم سے کہتا ہوں، اگرچہ وہ اٹھ کر اسے نہیں دے گا، کیونکہ وہ اس کا دوست ہے، لیکن اپنی ضد کی وجہ سے وہ اٹھے گا اور اسے جتنے چاہے دے گا۔\n9۔ اور میں تم سے کہتا ہوں، مانگو، اور یہ تمہیں دیا جائے گا؛ تلاش کرو، اور تم پاؤ گے؛ دستک دو، اور یہ تمہارے لیے کھول دیا جائے گا۔\n10۔ ہر اس شخص کے لیے جو مانگتا ہے، وہ وصول کرتا ہے؛ اور جو تلاش کرتا ہے وہ پاتا ہے؛ اور جو اسے دستک دے گا اسے کھول دیا جائے گا۔\n11۔ اگر بیٹا تم میں سے کسی باپ سے روٹی مانگے تو کیا وہ اسے پتھر دے گا؟ یا اگر وہ مچھلی مانگے، تو کیا وہ مچھلی کے بدلے اسے سانپ دے گا؟\n12۔ یا اگر وہ انڈہ مانگے، تو کیا وہ اسے بچھو پیش کرے گا؟ {پیشکش: Gr. دیں}\n13۔ اگر تم برے ہو کر اپنے بچوں کو اچھے تحفے دینا جانتے ہو: تو تمہارا آسمانی باپ روح القدس ان لوگوں کو کتنا اور دے گا جو اس سے مانگتے ہیں؟\n14۔ اور وہ ایک شیطان کو نکال رہا تھا، اور یہ بے وقوفی تھی۔ اور ایسا ہوا، جب شیطان ختم ہو گیا، بے وقوف نے کہا؛ اور لوگ حیران رہ گئے۔\n15۔ لیکن ان میں سے کچھ نے کہا، وہ شیطانوں کو بلزبب کے ذریعے نکال دیتا ہے، جو شیطانوں کا سردار ہے۔ {بیلزبب: گری. بیلزبول}\n16۔ اور دوسرے، جو اسے آزمانے کی کوشش کر رہے تھے، اس سے آسمان سے کوئی نشانی مانگے۔\n17۔ لیکن اس نے، ان کے خیالات کو جانتے ہوئے، ان سے کہا، ہر بادشاہت جو اپنے خلاف تقسیم ہو، ویران ہو جاتی ہے؛ اور ایک گھر {تقسیم} ایک گھر کے مقابلے میں گرتا ہے۔\n18۔ اگر شیطان بھی اپنے خلاف تقسیم ہو تو اس کی بادشاہی کیسی ہوگی؟ کیونکہ تم کہتے ہو کہ میں بیلزبوب کے ذریعے شیطانوں کو نکال دیتا ہوں۔\n19۔ اور اگر میں بیلزبوب کے ذریعے شیطانوں کو نکالوں، تو تمہارے بیٹے کس کے ذریعے انہیں نکالیں گے؟ اسی لیے وہ تمہارے منصف ہوں گے۔\n20۔ لیکن اگر میں خدا کی انگلی سے شیطانوں کو نکال دوں، تو یقینا خدا کی بادشاہی تم پر آ چکی ہے۔\n21. جب کوئی طاقتور آدمی مسلح ہو اور اپنے محل کی حفاظت کرے، تو اس کا مال امن میں ہوتا ہے:\n22۔ لیکن جب اس سے زیادہ طاقتور اس پر آتا ہے اور اسے شکست دیتا ہے، تو وہ اس سے اپنی ساری زرہ چھین لیتا ہے جس پر اس نے بھروسہ کیا تھا، اور اپنی مال غنیمت تقسیم کر دیتا ہے۔\n23. جو میرے ساتھ نہیں ہے وہ میرے خلاف ہے: اور جو میرے ساتھ جمع نہیں ہوتا وہ بکھر جاتا ہے۔\n24۔ جب ناپاک روح انسان سے نکل جائے، تو وہ خشک جگہوں سے گزرتا ہے، آرام کی تلاش میں؛ اور جب کوئی نہ ملے، تو وہ کہتا ہے، میں اپنے گھر واپس جاؤں گا جہاں سے باہر آیا ہوں۔\n25۔ اور جب وہ آتا ہے، تو اسے صاف اور سجایا ہوا پاتا ہے۔\n26۔ پھر وہ جاتا ہے، اور سات اور روحیں لے جاتا ہے جو اس سے زیادہ بدکار ہیں؛ اور وہ اندر داخل ہوتے ہیں، اور وہاں رہتے ہیں: اور اس انسان کی آخری حالت پہلی سے بھی بدتر ہے۔\n27۔ اور جب اس نے یہ باتیں کیں، تو جماعت کی ایک خاتون نے اپنی آواز بلند کی اور اس سے کہا، مبارک ہے وہ رحم جو تمہیں جنم دیتا ہے، اور وہ باپ جو تم نے چوسا ہے۔\n28۔ لیکن اس نے کہا، ہاں، مبارک ہیں وہ جو خدا کا کلام سنتے ہیں اور اس پر عمل کرتے ہیں۔\n29۔ اور جب لوگ اکٹھے جمع ہوئے، تو اس نے کہنا شروع کیا، یہ ایک بری نسل ہے: وہ کوئی نشانی تلاش کر رہے ہیں؛ اور اسے کوئی نشان نہیں دیا جائے گا، سوائے یوناس نبی کی نشانی کے۔\n30۔ کیونکہ جس طرح یونس نینیویوں کے لیے ایک نشان تھا، ویسے ہی اس نسل کے لیے انسان کا بیٹا بھی ہوگا۔\n31۔ جنوب کی ملکہ اس نسل کے لوگوں کے ساتھ فیصلے میں اٹھے گی اور انہیں سزا دے گی: کیونکہ وہ زمین کے دور سے سلیمان کی حکمت سننے آئی ہے؛ اور، دیکھو، یہاں سلیمان سے بڑا {ہے}۔\n32۔ نینوا کے لوگ اس نسل کے ساتھ فیصلے میں اٹھیں گے، اور اسے مذمت کریں گے: کیونکہ انہوں نے یونس کی تبلیغ پر توبہ کی؛ اور دیکھو، یہاں یوناس سے بھی بڑا ہے۔\n33۔ کوئی انسان، جب موم بتی جلائے گا، تو اسے خفیہ جگہ پر نہیں رکھتا، نہ تو بوشل کے نیچے، بلکہ شمعدان پر، تاکہ آنے والے روشنی دیکھ سکیں۔\n34۔ جسم کی روشنی آنکھ ہے: اس لیے جب تمہاری آنکھ اکیلی ہو تو تمہارا پورا جسم بھی روشنی سے بھرا ہوتا ہے؛ لیکن جب {تمہاری آنکھ} برائی ہو، تو تمہارا جسم بھی تاریکی سے بھرا ہوتا ہے۔\n35۔ اس لیے خبردار رہو کہ جو روشنی تمہارے اندر ہے وہ تاریکی نہ ہو۔\n36۔ اگر تمہارا پورا جسم روشنی سے بھرا ہو، جس کا کوئی حصہ تاریک نہ ہو، تو پورا جسم روشنی سے بھر جائے گا، جیسے موم بتی کی روشن روشنی تمہیں دیتی ہے۔ {روشن...: Gr. ایک موم بتی اپنی روشن روشنی سے}\n37۔ اور جب وہ بول رہا تھا، ایک فریسی نے اسے اپنے ساتھ کھانے کی درخواست کی، اور وہ اندر گیا اور کھانے کے لیے بیٹھ گیا۔\n38۔ اور جب فریسی نے یہ دیکھا، تو وہ حیران ہوا کہ اس نے رات کے کھانے سے پہلے پہلے نہایا نہیں تھا۔\n39۔ اور خداوند نے اس سے کہا، اب اے فریسیو پیالے اور پلیٹ کے باہر کی صفائی کرو؛ لیکن تمہارا اندرونی حصہ بھوک اور برائی سے بھرا ہوا ہے۔\n40۔ {تم بے وقوفوں}، کیا وہ نہیں جنہوں نے جو چیز بغیر ہے وہ بھی جو اندر ہے؟\n41۔ بلکہ جو کچھ آپ کے پاس ہے اس سے صدقہ کرو؛ اور دیکھو، تمہارے لیے سب کچھ صاف ہے۔ {of...: یا، جیسا کہ آپ کر سکتے ہیں}\n42. لیکن تم پر افسوس، فریسیوں! کیونکہ تم پودینہ، رو اور ہر قسم کی جڑی بوٹیاں دیتے ہو، اور فیصلے اور خدا کی محبت کو نظر انداز کرتے ہو: یہ سب تمہیں کرنا چاہیے تھا، اور دوسروں کو بے اثر نہیں چھوڑنا چاہیے تھا۔\n43۔ تم پر افسوس، فریسیوں! کیونکہ آپ کو عبادت گاہوں کی سب سے اونچی نشستیں پسند ہیں، اور بازاروں میں سلام۔\n44۔ تم پر افسوس، کاتبوں اور فریسیوں، منافقو! کیونکہ تم قبروں کی طرح ہو جو نظر نہیں آتیں، اور جو لوگ ان پر چلتے ہیں وہ ان سے واقف نہیں ہیں۔\n45۔ پھر ایک وکیل نے جواب دیا اور کہا، آقا، اور کہا کہ آپ ہمیں بھی ملامت کرتے ہیں۔\n46۔ اور اس نے کہا، تم پر بھی افسوس، اے وکیلوں! کیونکہ تم لوگوں کو بھاری بوجھ اٹھاتے ہو، اور تم خود ان بوجھ کو اپنی انگلیوں سے نہیں چھوتے۔\n47۔ تم پر افسوس! کیونکہ تم نے انبیاء کی قبریں تعمیر کیں، اور تمہارے آباؤ اجداد نے انہیں قتل کیا۔\n48۔ واقعی تم گواہی دیتے ہو کہ تم اپنے باپ اجداد کے اعمال کی اجازت دیتے ہو: کیونکہ انہوں نے واقعی انہیں مار دیا، اور تم ان کے قبریں بناتے ہو۔\n49۔ لہٰذا خدا کی حکمت نے بھی کہا، میں انہیں نبی اور رسول بھیجوں گا، اور {کچھ} کو وہ قتل کریں گے اور ظلم کریں گے:\n50. تاکہ تمام نبیوں کا خون، جو دنیا کی بنیاد سے بہا گیا، اس نسل سے طلب کیا جائے؛\n51۔ ہابیل کے خون سے زکریا کے خون تک، جو قربان گاہ اور مندر کے درمیان مر گیا: یقینا میں تم سے کہتا ہوں، یہ اس نسل سے لازمی ہوگا۔\n52۔ تم پر افسوس، وکیلوں! کیونکہ تم نے علم کی چابی چھین لی ہے: تم نے اپنے اندر داخل نہیں ہوئے، اور جو اندر جا رہے تھے انہیں تم نے روکا۔ {رکاوٹ: یا، برا ہے}\n53۔ اور جب اس نے یہ باتیں ان سے کہیں، کاتبوں اور فریسیوں نے {اسے} پر زور دینا شروع کر دیا، اور اسے بہت سی باتیں کرنے پر اکسانے لگے:\n54۔ اس کا انتظار کرنا، اور اس کے منہ سے کچھ پکڑنا چاہتا تھا تاکہ وہ اس پر الزام لگا سکیں۔","1۔ اسی دوران، جب بے شمار لوگ جمع ہوئے، یہاں تک کہ وہ ایک دوسرے پر قدم رکھتے تھے، تو اس نے سب سے پہلے اپنے شاگردوں سے کہنا شروع کیا: فریسیوں کے خمیر سے ہوشیار رہو، جو منافقت ہے۔\n2۔ کیونکہ کچھ بھی پوشیدہ نہیں ہے جو ظاہر نہ ہو؛ دونوں نے چھپائی نہیں، یہ معلوم نہیں ہوگا۔\n3۔ لہٰذا جو کچھ تم نے اندھیرے میں کہا ہے وہ روشنی میں سنا جائے گا؛ اور جو کچھ تم نے الماریوں میں کان میں کہا ہے وہ گھروں کی چھتوں پر اعلان کیا جائے گا۔\n4۔ اور میں تم سے کہتا ہوں میرے دوستو، ان سے مت ڈرو جو جسم کو مارتے ہیں، اور اس کے بعد ان کے پاس کچھ اور کرنے کو نہیں۔\n5۔ لیکن میں تمہیں پہلے سے خبردار کروں گا جس سے تم ڈرو گے: اس سے ڈرو، جو قتل کے بعد جہنم میں پھینکنے کی طاقت رکھتا ہے؛ ہاں، میں تم سے کہتا ہوں، اس سے ڈرو۔\n6۔ کیا پانچ چڑیاں دو فارتھنگ میں فروخت نہیں ہوتیں، اور ان میں سے کوئی بھی خدا کے سامنے بھلایا نہیں جاتا؟\n7۔ لیکن آپ کے سر کے بالوں کو بھی گنے ہوئے ہیں۔ لہٰذا خوف نہ کرو: تم بہت سی چڑیوں سے زیادہ قیمتی ہو۔\n8۔ اور میں تم سے کہتا ہوں، جو بھی لوگوں کے سامنے مجھے اقرار کرے گا، وہ بھی خدا کے فرشتوں کے سامنے اعتراف کرے گا:\n9. لیکن جو مجھے انسانوں کے سامنے انکار کرے گا، وہ خدا کے فرشتوں کے سامنے انکار کیا جائے گا۔\n10۔ اور جو بھی انسان کے بیٹے کے خلاف ایک لفظ کہے گا، اسے معاف کر دیا جائے گا، لیکن جو روح القدس کی گستاخی کرے گا اسے معاف نہیں کیا جائے گا۔\n11۔ اور جب وہ تمہیں عبادت گاہوں، مجسٹریٹوں اور طاقتوں کے پاس لے جاتے ہیں، تو یہ نہ سوچنا کہ تم کیسے یا کیا جواب دو گے، یا کیا کہو گے:\n12۔ کیونکہ روح القدس تمہیں اسی وقت سکھائے گا کہ تمہیں کیا کہنا چاہیے۔\n13۔ اور جماعت میں سے ایک نے اس سے کہا، آقا، میرے بھائی سے بات کرو کہ وہ وراثت میرے ساتھ تقسیم کرے۔\n14۔ اور اس نے اس سے کہا، آدمی، کس نے مجھے تمہارے اوپر جج یا تقسیم کرنے والا بنایا؟\n15۔ اور اس نے ان سے کہا، ہوشیار رہو، اور لالچ سے ہوشیار رہو، کیونکہ انسان کی زندگی اس چیزوں کی فراوانی میں نہیں ہوتی جو اس کے پاس ہے۔\n16۔ اور اس نے ان کے سامنے ایک تمثیل سنائی، کہا، ایک امیر آدمی کی زمین نے وافر مقدار میں جنم لیا:\n17۔ اور اس نے دل ہی دل میں سوچا، کہا، میں کیا کروں، کیونکہ میرے پاس اپنے پھل دینے کی جگہ نہیں؟\n18۔ اور اس نے کہا، میں یہ کروں گا: میں اپنے کھیت گرا دوں گا، اور اس سے بڑا تعمیر کروں گا؛ اور وہاں میں اپنے تمام پھل اور مال دوں گا۔\n19۔ اور میں اپنی روح سے کہوں گا، جان، کہ تم نے کئی سالوں سے بہت سا سامان رکھا ہے؛ آرام کرو، کھاؤ، پیو، {اور} خوش رہو۔\n20۔ لیکن خدا نے اس سے کہا، {تو} بیوقوف، آج رات تمہاری روح تم سے طلب کی جائے گی: پھر وہ چیزیں کس کی ہوں گی جو تم نے دی ہیں؟ {تمہارے...: Gr. کیا وہ تمہاری روح چاہتے ہیں}\n21. اسی طرح وہ شخص ہے جو اپنے لیے خزانہ جمع کرتا ہے، اور خدا کے لیے امیر نہیں ہوتا۔\n22۔ اور اس نے اپنے شاگردوں سے کہا، لہٰذا میں تم سے کہتا ہوں، اپنی جان کے بارے میں مت سوچو، تم کیا کھاؤ گے؛ نہ ہی جسم کے لیے، جو تم پہنو گے۔\n23. زندگی گوشت سے بڑھ کر ہے، اور جسم لباس سے زیادہ ہے۔\n24۔ کوے دیکھیں: کیونکہ وہ نہ بوتے ہیں نہ کاٹتے ہیں؛ جن میں نہ تو گودام ہے اور نہ ہی بارن؛ اور خدا انہیں کھلاتا ہے: تم پرندوں سے کتنے بہتر ہو؟\n25۔ اور تم میں سے کون سوچ کر اس کے قد میں ایک کیوبٹ اضافہ کر سکتا ہے؟\n26۔ اگر تم وہ سب سے کم کام کرنے کے قابل نہیں ہو جو سب سے کم ہو، تو پھر باقی کے بارے میں کیوں سوچتے ہو؟\n27. دیکھیں کہ کنول کیسے اگتے ہیں: وہ محنت نہیں کرتے، نہیں کاتتے؛ اور پھر بھی میں تم سے کہتا ہوں، کہ سلیمان اپنی پوری شان میں ان میں سے ایک کی طرح نہیں تھا۔\n28۔ اگر خدا اس گھاس کو کپڑے دے جو آج کھیت میں ہے، اور کل تندور میں ڈال دی جائے؛ وہ تمہیں اور کتنا کپڑے پہنائے گا، اے کم ایمان والے؟\n29۔ اور جو کھاؤ گے یا پیو گے اس کی تلاش نہ کرو، نہ شک میں ہو۔ {نہ تو...: یا، محتاط انتظار میں نہ رہو}\n30۔ ان سب چیزوں کے لیے دنیا کی قومیں تلاش کرتی ہیں: اور تمہارا باپ جانتا ہے کہ تمہیں ان چیزوں کی ضرورت ہے۔\n31۔ بلکہ خدا کی بادشاہی کی تلاش کرو؛ اور یہ سب چیزیں تمہیں شامل کر دی جائیں گی۔\n32۔ خوف نہ کرو، چھوٹے ریوڑ؛ کیونکہ یہ تمہارے والد کی خوشی ہے کہ وہ تمہیں بادشاہی دے رہا ہے۔\n33۔ جو تمہارے پاس ہے اسے بیچو، اور صدقہ دو؛ اپنے لیے ایسے تھیلے فراہم کرو جو پرانے نہ ہوں، آسمانوں میں خزانہ جو کمزور نہ ہو، جہاں نہ کوئی چور آئے، نہ پتنگا فساد کرے۔\n34۔ جہاں تمہارا خزانہ ہے، وہاں تمہارا دل بھی ہوگا۔\n35۔ اپنے جسم کو لپیٹ کر لپیٹ دو، اور [تمہارا] روشنی جلتا رہے؛\n36۔ اور تم خود ان لوگوں کی طرح ہو جو اپنے رب کا انتظار کرتے ہیں، جب وہ شادی سے واپس آئے گا؛ تاکہ جب وہ آئے اور دستک دے، تو وہ فورا اس کے لیے کھل جائیں۔\n37۔ مبارک ہیں وہ خادم، جنہیں خداوند جب آئے گا تو وہ دیکھ رہے پائے گا: یقینا میں تم سے کہتا ہوں کہ وہ خود کو تیار کرے گا، انہیں کھانے کے لیے بٹھائے گا، اور باہر آئے گا اور ان کی خدمت کرے گا۔\n38۔ اور اگر وہ دوسری پہر میں آئے، یا تیسری گھڑی میں، اور انہیں پائے، تو مبارک ہیں وہ خادم۔\n39۔ اور یہ جانتا ہے کہ اگر گھر کے نیک آدمی کو معلوم ہوتا کہ چور کس وقت آئے گا، تو وہ دیکھتا رہتا، اور اپنے گھر کو توڑنے کی اجازت نہ دیتا۔\n40۔ لہٰذا تم بھی تیار رہو: کیونکہ انسان کا بیٹا اس وقت آتا ہے جب تم سوچتے نہیں۔\n41۔ پھر پطرس نے اس سے کہا، اے خداوند، کیا تو یہ تمثیل ہم سے سناتے ہو، یا سب سے بھی؟\n42۔ اور خداوند نے فرمایا، تو وہ وفادار اور دانا منتظم کون ہے، جسے [اس کا} رب اپنے گھرانے کا حکمران بنائے گا، تاکہ انہیں وقت پر گوشت کا حصہ دے؟\n43۔ مبارک ہے وہ خادم، جسے اس کا رب جب آئے گا تو ایسا کرتے ہوئے پائے گا۔\n44۔ ایک سچائی جو میں تم سے کہتا ہوں، کہ وہ اسے اپنی تمام چیزوں پر حکمران بنائے گا۔\n45۔ لیکن اگر وہ خادم دل سے کہتا ہے، میرا رب اس کی آمد میں تاخیر کرتا ہے؛ اور نوکروں اور لڑکیوں کو مارنا شروع کرے گا، کھانا پینا اور نشے میں ہونا شروع کرے گا؛\n46۔ اس خادم کا سردار اس دن آئے گا جب وہ اس کی تلاش میں نہ ہو، اور ایک ایسے وقت میں جب وہ بے خبر ہو، اسے چیر پھاڑ دے گا، اور اسے کافروں کے ساتھ اپنا حصہ دے گا۔ {کٹ...: یا، اسے کاٹ دو}\n47۔ اور وہ خادم، جو اپنے رب کی مرضی جانتا تھا، اور نہ خود تیار تھا، نہ ہی اس کی مرضی کے مطابق کیا، اسے کئی پٹیوں سے مارا جائے گا۔\n48۔ لیکن جو نہیں جانتا اور ایسے کام کرتا ہے جو دھاریوں کے قابل ہوتے ہیں، اسے چند دھاریوں سے مارا جائے گا۔ کیونکہ جس کو بہت کچھ دیا جائے، اس کی بہت مانگ کی جائے گی: اور جس سے لوگوں نے بہت کچھ کیا ہے، وہ اس سے زیادہ مانگیں گے۔\n49۔ میں زمین پر آگ بھیجنے آیا ہوں؛ اور میں کیا کروں گا، اگر یہ پہلے ہی جل چکا ہو؟\n50۔ لیکن میرے پاس بپتسمہ لینے کے لیے ایک بپتسمہ ہے؛ اور میں کتنی پریشان ہوں جب تک یہ مکمل نہ ہو جائے! {سخت: یا، درد}\n51. کیا تم فرض کرتے ہو کہ میں زمین پر امن دینے آیا ہوں؟ میں تمہیں بتاتا ہوں، نے؛ بلکہ تقسیم:\n52۔ کیونکہ اب سے ایک گھر میں پانچ ہوں گے جو تقسیم ہوں گے، تین دو کے مقابلے میں، اور دو تین کے مقابلے میں۔\n53۔ باپ بیٹے کے خلاف تقسیم ہوگا، اور بیٹا باپ کے خلاف؛ ماں بیٹی کے خلاف، اور بیٹی ماں کے خلاف؛ ساس اپنی بہو کے خلاف، اور بہو اپنی ساس کے خلاف۔\n54۔ اور اس نے لوگوں سے یہ بھی کہا، جب تم مغرب سے بادل اٹھتے دیکھو، تو فورا کہو، بارش آتی ہے؛ اور ایسا ہی ہے۔\n55۔ اور جب {تم دیکھو} جنوبی ہوا چلتی ہے، تو تم کہتے ہو، گرمی ہوگی؛ اور یہ ہو جاتا ہے۔\n56۔ {تم منافقو}، تم آسمان اور زمین کا چہرہ پہچان سکتے ہو؛ لیکن اس بار تم کیسے نہیں سمجھتے؟\n57۔ ہاں، اور تم خود بھی کیوں نہیں فیصلہ کرتے کہ کیا صحیح ہے؟\n58۔ جب تم اپنے مخالف کے ساتھ مجسٹریٹ کے پاس جاؤ، {جیسا کہ تم راستے میں ہو}، تو محنت کرو تاکہ تم اس سے بچ سکو؛ کہیں وہ تمہیں جج کے حوالے نہ کر دے، اور جج تمہیں افسر کے حوالے کر دے، اور افسر تمہیں قید میں نہ ڈال دے۔\n59۔ میں تمہیں کہتا ہوں، تم وہاں سے نہیں جاؤ گے جب تک تم آخری پیسے ادا نہ کر لو۔","1۔ اس موسم میں کچھ لوگ موجود تھے جنہوں نے اسے گلیلیائیوں کے بارے میں بتایا، جن کا خون پیلاطس نے ان کی قربانیوں کے ساتھ ملا دیا تھا۔\n2۔ اور یسوع نے جواب میں ان سے کہا، فرض کرو کہ یہ گلیلیائی سب گلیلیائی سب سے زیادہ گناہ گار تھے، کیونکہ انہوں نے ایسی تکلیفیں برداشت کیں؟\n3۔ میں تمہیں بتاتا ہوں، نہیں: لیکن جب تک تم توبہ نہ کرو، تم سب بھی فنا ہو جاؤ گے۔\n4۔ یا وہ اٹھارہ جن پر سیلوام کا مینار گرا اور انہیں مار ڈالا، کیا تم سمجھتے ہو کہ وہ یروشلم میں رہنے والے تمام انسانوں سے زیادہ گناہ گار تھے؟ {گناہگار: یا، مقروض}\n5۔ میں تم سے کہتا ہوں، نہیں: لیکن اگر تم توبہ نہ کرو تو تم سب بھی اسی طرح فنا ہو جاؤ گے۔\n6۔ اس نے یہ تمثیل بھی بیان کی؛ ایک {آدمی} نے اپنے انگور کے باغ میں انجیر کا درخت لگایا تھا؛ اور وہ آیا اور وہاں سے پھل تلاش کیا، لیکن کچھ نہ ملا۔\n7۔ پھر اس نے اپنے انگور کے باغ کے الماری سے کہا، دیکھو، میں تین سال اس انجیر کے درخت پر پھل تلاش کرنے آیا ہوں، اور کچھ نہیں ملا: اسے کاٹ دو؛ زمین پر کیوں دباؤ ڈالا جائے؟\n8۔ اور اس نے جواب میں کہا، اے خداوند، اس سال بھی اسے چھوڑ دو، جب تک میں اس میں کھود کر گوبر نہ کھودوں:\n9۔ اور اگر وہ پھل دے تو {اچھا}؛ اور اگر نہیں، {تو} اس کے بعد اسے کاٹ دو۔\n10۔ اور وہ سبت کے دن ایک عبادت گاہ میں تعلیم دے رہے تھے۔\n11۔ اور دیکھو، ایک عورت تھی جس کی روح اٹھارہ سال کی کمزور تھی، اور وہ جھکی ہوئی تھی، اور خود کو اٹھا نہیں سکتی تھی۔\n12۔ اور جب یسوع نے اسے دیکھا، تو اس نے {اسے اپنے پاس} بلایا اور کہا، اے عورت، تم اپنی کمزوری سے آزاد ہو گئی ہو۔\n13۔ اور اس نے اس پر ہاتھ رکھے: اور فورا وہ سیدھی ہو گئی، اور خدا کی جلال میں آ گئی۔\n14۔ اور عبادت گاہ کے حکمران نے غصے سے جواب دیا، کیونکہ یسوع نے سبت کے دن شفا دی تھی، اور لوگوں سے کہا، چھ دن ایسے ہیں جن میں انسانوں کو کام کرنا چاہیے: لہٰذا ان میں آؤ اور شفا پاؤ، نہ کہ سبت کے دن۔\n15۔ پھر خداوند نے اس کا جواب دیا اور کہا، {تو} منافق، کیا تم میں سے ہر ایک ہفتہ کے دن اپنا بیل یا گدھا اصطبل سے نہیں چھوڑ کر اسے پانی دینے کے لیے لے جاتا ہے؟\n16۔ اور کیا یہ عورت، جو ابراہیم کی بیٹی ہے، جسے شیطان نے ان اٹھارہ سالوں سے باندھا ہے، کیا یہ ہفتہ کے دن اس بندھن سے آزاد نہیں ہونا چاہیے؟\n17۔ اور جب اس نے یہ باتیں کہیں، تو اس کے تمام مخالفین شرمندہ ہوئے: اور تمام لوگ ان تمام شاندار کاموں پر خوش ہوئے جو اس نے کیں۔\n18۔ پھر اس نے کہا، خدا کی بادشاہی کیسی ہے؟ اور میں اس سے کہاں مشابہت رکھوں؟\n19۔ یہ سرسوں کے دانے کی طرح ہے، جسے ایک آدمی نے لے کر اپنے باغ میں ڈال دیا؛ اور وہ بڑھا، اور ایک عظیم درخت بن گیا؛ اور ہوا کے پرندے اس کی شاخوں میں پھنسے ہوئے تھے۔\n20۔ اور پھر اس نے کہا، خدا کی بادشاہی کو کہاں سے تشبیہ دوں؟\n21۔ یہ خمیر کی طرح ہے، جسے ایک عورت نے تین پیمائش کھانے میں چھپا دیا، یہاں تک کہ پورا کھانا خمیر ہو گیا۔\n22۔ اور وہ شہروں اور دیہاتوں میں گیا، تعلیم دیتا اور یروشلم کی طرف روانہ ہوا۔\n23۔ پھر ایک نے اس سے کہا، اے خداوند، کیا نجات پانے والے چند ہی ہیں؟ اور اس نے ان سے کہا،\n24۔ اسٹریٹ گیٹ سے اندر جانے کی کوشش کرو: کیونکہ بہت سے، میں تم سے کہتا ہوں، اندر جانے کی کوشش کریں گے، اور وہ نہیں کر سکیں گے۔\n25۔ جب ایک بار گھر کا مالک اٹھتا ہے، دروازہ بند کر دیتا ہے، اور تم باہر کھڑے ہو کر دروازہ کھٹکھٹانے لگتے ہو، اور کہتے ہو، خداوند، خداوند، ہمارے لیے دروازہ کھولے؛ اور وہ جواب دے گا اور کہے گا، میں نہیں جانتا کہ تم کہاں سے آئے ہو:\n26۔ پھر تم کہنا شروع کرو گے، ہم نے تمہاری موجودگی میں کھایا اور پیا، اور تم نے ہماری گلیوں میں تعلیم دی۔\n27. لیکن وہ کہے گا، میں تمہیں بتاتا ہوں، میں نہیں جانتا کہ تم کہاں سے ہو؛ مجھ سے دور ہو جاؤ، اے تمام بدکار مزدورو۔\n28. جب تم ابراہیم، اسحاق، یعقوب اور تمام نبیوں کو خدا کی بادشاہی میں دیکھو گے تو رونا اور دانت پیسنا ہوگا۔\n29۔ اور وہ مشرق سے، مغرب سے، شمال سے، جنوب سے آئیں گے، اور خدا کی بادشاہی میں بیٹھیں گے۔\n30۔ اور دیکھو، وہ آخری ہیں جو پہلے ہوں گے، اور پہلے جو آخری ہوں گے۔\n31۔ اسی دن فریسیوں میں سے کچھ آئے اور اس سے کہا، نکل جاؤ اور یہاں سے نکل جاؤ، کیونکہ ہیرودیس تمہیں مار ڈالے گا۔\n32۔ اور اس نے ان سے کہا، جاؤ، اور اس لومڑی کو بتاؤ، دیکھو، میں شیطانوں کو نکال دیتا ہوں، اور میں دن اور کل شفا دیتا ہوں، اور تیسرے دن میں مکمل ہو جاؤں گا۔\n33۔ پھر بھی مجھے دن تک چلنا ہوگا، اور کل تک، اور {اگلے دن} تک: کیونکہ یہ ممکن نہیں کہ کوئی نبی یروشلم سے نکل جائے۔\n34۔ اے یروشلم، یروشلم، جو انبیاء کو قتل کرتی ہے اور جو تمہارے پاس بھیجے گئے ہیں انہیں سنگسار کرتی ہے؛ کتنی بار میں تمہارے بچوں کو اکٹھا کرتا، جیسے مرغی اپنے بچوں کو اپنے پروں کے نیچے جمع کرتی ہے، اور تم نہیں کرتے!\n35۔ دیکھو، تمہارا گھر تمہارے لیے ویران چھوڑ دیا گیا ہے: اور میں تم سے کہتا ہوں، تم مجھے نہیں دیکھو گے، جب تک وہ وقت نہ آئے جب تم کہیں، مبارک ہے وہ جو خداوند کے نام پر آتا ہے۔","1۔ اور جب وہ ہفتہ کے دن ایک سردار فریسی کے گھر میں روٹی کھانے گیا، تو وہ اس کی نگرانی کرنے لگے۔\n2۔ اور دیکھو، اس کے سامنے ایک خاص آدمی تھا جسے ڈراپسی تھی۔\n3۔ اور یسوع نے جواب میں وکلاء اور فریسیوں سے کہا، کیا سبت کے دن شفا دینا جائز ہے؟\n4۔ اور وہ خاموش رہے۔ اور اس نے {اسے} کو لیا، اسے شفا دی، اور چھوڑ دیا؛\n5۔ اور اس نے جواب دیا، تم میں سے کون گدھا یا بیل گڑھے میں گرا دے گا، اور سبت کے دن اسے فورا باہر نہیں نکالے گا؟\n6۔ اور وہ دوبارہ ان باتوں کا جواب نہیں دے سکے۔\n7۔ اور اس نے ان لوگوں کے لیے ایک تمثیل سنائی جو حکم دیے گئے، جب اس نے بتایا کہ انہوں نے اہم کمرے کیسے منتخب کیے؛ ان سے کہا،\n8۔ جب تمہیں کسی {آدمی} کو شادی کے لیے بلایا جائے، تو سب سے اونچے کمرے میں مت بیٹھنا؛ کہیں تم سے زیادہ معزز آدمی کو اس سے حکم نہ دیا جائے؛\n9۔ اور جس نے تمہیں اور اس سے کہا کہ آؤ اور تم سے کہے، اس آدمی کو جگہ دو؛ اور تم شرمندگی کے ساتھ شروع کرتے ہو کہ سب سے نچلا کمرہ لے لو۔\n10۔ لیکن جب تمہیں حکم دیا جائے تو سب سے نچلے کمرے میں جا کر بیٹھ جانا؛ تاکہ جب وہ تمہیں آنے کو کہہ سکے، دوست، اوپر چڑھو: پھر تم ان لوگوں کے سامنے عبادت کرو گے جو تمہارے ساتھ کھانے پر بیٹھے ہیں۔\n11۔ جو خود کو بلند کرے گا اسے ذلیل کیا جائے گا؛ اور جو خود کو عاجز کرے گا وہ بلند ہوگا۔\n12۔ پھر اس نے اس سے بھی کہا جس نے اسے حکم دیا، جب تم کھانا یا کھانا تیار کرو تو اپنے دوستوں، بھائیوں، رشتہ داروں اور امیر پڑوسیوں کو نہ بلاؤ؛ کہیں وہ تمہیں دوبارہ نہ کہہ دیں، اور تمہیں بدلہ نہ ملے۔\n13. لیکن جب تم دعوت مناؤ، غریبوں، معذوروں، لنگڑوں، اندھوں کو بلاؤ:\n14۔ اور تم برکت پاؤ گے؛ کیونکہ وہ تمہیں بدلہ نہیں دے سکتے: کیونکہ تمہیں انصاف والوں کے دوبارہ زندہ ہونے پر سزا ملے گی۔\n15۔ اور جب ان میں سے کوئی جو اس کے ساتھ گوشت پر بیٹھا تھا یہ باتیں سن کر اس نے کہا، مبارک ہے وہ جو خدا کی بادشاہی میں روٹی کھائے گا۔\n16۔ پھر اس نے اس سے کہا، ایک آدمی نے بڑا کھانا بنایا اور بہت سے لوگوں سے کہا:\n17۔ اور اپنے خادم کو رات کے کھانے کے وقت بھیجا کہ وہ ان لوگوں سے کہے جنہیں حکم دیا گیا تھا، آؤ؛ کیونکہ اب سب کچھ تیار ہے۔\n18۔ اور سب نے ایک {رضامندی} کے ساتھ بہانے بنانا شروع کر دیے۔ پہلے نے اسے کہا، میں نے زمین کا ٹکڑا خریدا ہے، اور مجھے اسے دیکھنا ہے: میں دعا کرتا ہوں کہ مجھے معاف کر دے۔\n19۔ اور ایک اور نے کہا، میں نے پانچ بیل کے جوتے خریدے ہیں، اور میں انہیں ثابت کرنے جا رہا ہوں: میں دعا کرتا ہوں کہ مجھے معاف کر دو۔\n20۔ اور ایک اور نے کہا، میں نے بیوی سے شادی کر لی ہے، اس لیے میں نہیں آ سکتا۔\n21. تو وہ خادم آیا اور اپنے آقا کو یہ سب کچھ دکھایا۔ پھر گھر کے مالک نے غصے میں اپنے خادم سے کہا، جلدی سے شہر کی گلیوں اور گلیوں میں جاؤ، اور غریبوں، معذوروں، رکنے والوں اور اندھوں کو یہاں لے آؤ۔\n22۔ اور خادم نے کہا، اے خداوند، جیسا تو نے حکم دیا ویسا ہی کیا گیا، پھر بھی جگہ ہے۔\n23۔ اور خداوند نے خادم سے کہا، سڑکوں اور جھاڑیوں میں جاؤ، اور انہیں مجبور کرو کہ وہ اندر آئیں، تاکہ میرا گھر بھر جائے۔\n24۔ کیونکہ میں تم سے کہتا ہوں، کہ جن مردوں کو کہا گیا ہے وہ میرے کھانے کا ذائقہ نہیں چکھیں گے۔\n25۔ اور اس کے ساتھ بڑی تعداد میں لوگ گئے، اور اس نے پلٹ کر ان سے کہا،\n26۔ اگر کوئی {آدمی} میرے پاس آئے اور اپنے باپ، ماں، بیوی، بچوں، بھائیوں اور بہنوں سے نفرت نہ کرے، ہاں، اور اپنی جان سے بھی، تو وہ میرا شاگرد نہیں بن سکتا۔\n27۔ اور جو اپنی صلیب نہیں اٹھائے اور میرے پیچھے آئے، وہ میرا شاگرد نہیں بن سکتا۔\n28۔ تم میں سے کون ہے، جو مینار بنانے کا ارادہ رکھتا ہے، پہلے نہیں بیٹھتا، اور خرچ نہیں گنتا، کہ کیا اس کے پاس {اتنی} ہے کہ وہ {اسے} مکمل کر سکے؟\n29۔ تاکہ جب وہ بنیاد رکھ دے اور مکمل نہ کر سکے، تو جو بھی دیکھتا ہے وہ اس کا مذاق اڑانا شروع کر دے،\n30۔ کہتے ہوئے، اس آدمی نے تعمیر شروع کی، اور مکمل نہیں کر سکا۔\n31۔ یا کون سا بادشاہ، جو دوسرے بادشاہ کے خلاف جنگ کرنے جا رہا ہے، پہلے بیٹھ کر مشورہ نہیں کرے گا کہ کیا وہ دس ہزار کے ساتھ بیس ہزار کے ساتھ اس کا مقابلہ کر سکتا ہے؟\n32۔ ورنہ، جب دوسرا ابھی بہت دور ہے، وہ ایک سفیر بھیجتا ہے، اور امن کی شرائط چاہتا ہے۔\n33۔ اسی طرح، جو بھی آپ میں سے ہے اور اپنی تمام چیزیں نہیں چھوڑتا، وہ میرا شاگرد نہیں بن سکتا۔\n34۔ نمک {ہے} اچھا ہے: لیکن اگر نمک کا ذائقہ ختم ہو جائے تو اسے کس چیز سے مصالحہ کیا جائے؟\n35۔ یہ نہ زمین کے لیے موزوں ہے، نہ ابھی تک گوبر کے ڈھیر کے لیے؛ {لیکن} مرد اسے باہر نکال دیتے ہیں۔ جس کے پاس سننے کے لیے کان ہیں، اسے سننے دو۔","1۔ پھر اس کے پاس تمام پاب مالوں اور گناہ گاروں کو اس کی بات سننے کے لیے بلایا۔\n2۔ اور فریسیوں اور کاتبوں نے سرگوشی کی، کہہ رہے تھے، یہ آدمی گناہ گاروں کو قبول کرتا ہے اور ان کے ساتھ کھاتا ہے۔\n3۔ اور اس نے ان سے یہ تمثیل سنائی، کہا،\n4۔ تم میں سے کون سا آدمی، جس کے پاس سو بھیڑیں ہیں، اگر وہ ان میں سے ایک کھو دے، تو وہ نوے اور نو کو جنگل میں چھوڑ کر کھوئی ہوئی چیز کے پیچھے نہیں جائے گا، جب تک کہ وہ اسے نہ پا لے؟\n5۔ اور جب وہ اسے پاتا ہے، تو وہ اسے اپنے کندھوں پر رکھ دیتا ہے، خوشی مناتے ہوئے۔\n6۔ اور جب وہ گھر آتا ہے، تو اپنے دوستوں اور پڑوسیوں کو اکٹھا کرتا ہے، ان سے کہتا ہے، میرے ساتھ خوش رہو؛ کیونکہ میں نے اپنی بھیڑ ڈھونڈ لی ہے جو کھو گئی تھی۔\n7۔ میں تم سے کہتا ہوں کہ اسی طرح جنت میں خوشی ایک گناہ گار پر ہوگی جو توبہ کرے، نوے نو سے زیادہ نیک افراد سے زیادہ، جنہیں توبہ کی ضرورت نہیں۔\n8۔ یا کون سی عورت جس کے پاس دس چاندی کے سکے ہیں، اگر اس کا ایک ٹکڑا گم ہو جائے، تو وہ موم بتی نہیں جلاتی ہے، گھر کو جھاڑو نہیں دیتی اور محنت سے تلاش کرتی ہے جب تک کہ وہ اسے نہ پا لے؟ {ٹکڑے...: دراخما، یہاں چاندی کا ٹکڑا ترجمہ کیا جاتا ہے، ایک اونس کا آٹھواں حصہ ہے، جو سات پینس آدھا پینی بنتا ہے، اور رومن پینی کے برابر ہے}\n9۔ اور جب وہ اسے پا لیتی ہے، تو وہ اپنے دوستوں اور پڑوسیوں کو اکٹھا بلاتی ہے، کہتی ہے، میرے ساتھ خوش رہو؛ کیونکہ میں نے وہ ٹکڑا ڈھونڈ لیا ہے جو میں نے کھو دیا تھا۔\n10۔ اسی طرح، میں آپ سے کہتا ہوں، خدا کے فرشتوں کی موجودگی میں خوشی ہے اس گناہ گار پر جو توبہ کرتا ہے۔\n11۔ اور اس نے کہا، ایک شخص کے دو بیٹے تھے:\n12۔ اور ان میں سے چھوٹے نے {اپنے} والد سے کہا، ابا، مجھے وہ حصہ دو جو مال میرے پاس آتا ہے۔ اور اس نے اپنی زندگی ان پر تقسیم کر دی۔\n13۔ اور کچھ ہی دن بعد چھوٹے بیٹے نے سب اکٹھے ہو کر ایک دور دراز ملک کا سفر کیا، اور وہاں اپنی دولت کو ہنگامہ خیز زندگی میں ضائع کر دیا۔\n14۔ اور جب اس نے سب کچھ خرچ کر دیا، تو اس سرزمین میں شدید قحط آ گیا؛ اور وہ محتاج ہونے لگا۔\n15۔ اور وہ گیا اور اس ملک کے ایک شہری سے مل گیا؛ اور اس نے اسے اپنے کھیتوں میں سوروں کو کھلانے کے لیے بھیج دیا۔\n16۔ اور وہ چاہتا تھا کہ اس کا پیٹ ان خولوں سے بھر دیتا جو سور نے کھائے: اور کسی نے اسے نہیں دیا۔\n17۔ اور جب وہ ہوش میں آیا تو کہا، میرے والد کے کتنے کرائے کے نوکروں کے پاس اتنا روٹی ہے کہ وہ بچا رہے ہوں، اور میں بھوک سے مر جاتا ہوں!\n18۔ میں اٹھوں گا اور اپنے باپ کے پاس جاؤں گا، اور اسے کہوں گا، اے باپ، میں نے آسمان کے خلاف اور تیرے سامنے گناہ کیا ہے،\n19۔ اور میں اب تمہارا بیٹا کہلانے کے لائق نہیں ہوں: مجھے اپنے کرائے کے خادموں میں شامل کر دے۔\n20۔ اور وہ اٹھا، اور اپنے والد کے پاس آیا۔ لیکن جب وہ ابھی بہت دور تھا، اس کے والد نے اسے دیکھا، رحم کیا، دوڑا، اس کی گردن پر گر گیا، اور اسے چوم لیا۔\n21۔ اور بیٹے نے اس سے کہا، اے باپ، میں نے آسمان کے خلاف اور تیری نظر میں گناہ کیا ہے، اور اب میں تمہارا بیٹا کہلانے کے لائق نہیں ہوں۔\n22۔ لیکن باپ نے اپنے خادموں سے کہا، بہترین لباس نکالو اور اسے پہناؤ؛ اور اس کے ہاتھ میں انگوٹھی اور جوتے اس کے پیروں میں پہنائے:\n23۔ اور موٹے بچھڑے کو یہاں لے آؤ، اور اسے مار دو؛ اور آؤ کھانا کھائیں، اور خوش رہیں:\n24۔ اس کے لیے میرا بیٹا مر گیا، اور دوبارہ زندہ ہے؛ وہ گم ہو گیا تھا، اور مل گیا۔ اور وہ خوش ہونے لگے۔\n25۔ اب اس کا بڑا بیٹا کھیت میں تھا: اور جب وہ گھر کے قریب پہنچا تو اس نے موسیقی اور رقص کی آواز سنی۔\n26۔ اور اس نے ایک نوکر کو بلایا اور پوچھا کہ یہ باتیں کیا معنی رکھتی ہیں۔\n27۔ اور اس نے اسے کہا، تمہارا بھائی آ گیا ہے؛ اور تمہارے والد نے موٹے بچھڑے کو مار دیا ہے، کیونکہ اس نے اسے سلامت اور سلامت قبول کیا ہے۔\n28۔ اور وہ غصے میں آ گیا، اندر جانے کو تیار نہ تھا، اس لیے اس کا باپ باہر آیا اور اس سے التجا کی۔\n29۔ اور اس نے جواب میں اپنے باپ سے کہا، دیکھو، میں اتنے سالوں سے تیری خدمت کرتا ہوں، کبھی تمہارے حکم کی خلاف ورزی نہیں کی؛ اور پھر بھی تم نے مجھے کبھی بچہ نہیں دیا تاکہ میں اپنے دوستوں کے ساتھ خوش ہو سکوں:\n30۔ لیکن جیسے ہی یہ تمہارا بیٹا آیا، جس نے تمہاری زندگی کو طوائفوں کے ساتھ کھا گیا، تم نے اس کے لیے موٹا بچھڑا مار دیا۔\n31۔ اور اس نے اس سے کہا، بیٹا، تو ہمیشہ میرے ساتھ ہو، اور جو کچھ میرے پاس ہے وہ سب تمہارا ہے۔\n32۔ یہ طے ہوا کہ ہم خوش ہوں اور خوش ہوں: کیونکہ یہ تمہارا بھائی مر چکا ہے، اور دوبارہ زندہ ہے؛ اور گم ہو گیا، اور مل گیا۔","1۔ اور اس نے اپنے شاگردوں سے بھی کہا، ایک امیر آدمی تھا جس کا ایک منتظم تھا؛ اور اسی پر الزام لگایا گیا کہ اس نے اپنی چیزیں ضائع کیں۔\n2۔ اور اس نے اسے بلایا اور کہا، میں نے یہ کیسے سنا؟ اپنی سرپرستی کا حساب دیں؛ کیونکہ تم شاید اب سرپرست نہ رہو۔\n3۔ پھر منتظم نے اپنے اندر کہا، میں کیا کروں؟ کیونکہ میرا رب مجھ سے سرپرستی چھین لیتا ہے: میں کھدائی نہیں کر سکتا؛ منت کرنے میں مجھے شرمندگی ہے۔\n4۔ میں پرعزم ہوں کہ کیا کروں، تاکہ جب مجھے نگرانی سے نکالا جائے تو وہ مجھے اپنے گھروں میں قبول کر سکیں۔\n5۔ تو اس نے اپنے آقا کے ہر مقروض کو بلایا اور پہلے سے کہا، تم میرے رب کے کتنے مقروض ہو؟\n6۔ اور اس نے کہا، سو پیمائش تیل۔ اور اس نے اس سے کہا، اپنا بل لے لو، جلدی بیٹھو اور پچاس لکھو۔ {پیمائشیں: اصل میں لفظ Batus میں نو گیلن تین کوارٹ ہے}\n7۔ پھر اس نے دوسرے سے کہا، اور تم کتنے مقروض ہو؟ اور اس نے کہا، سو پیمائش گندم۔ اور اس نے اس سے کہا، اپنا بل لے لو، اور چار سو لکھو۔ {پیمائشیں: یہاں اصل میں ایک پیمائش کی تشریح کی گئی ہے جس میں تقریبا چودہ بشل اور دو کوارٹ شامل ہیں}\n8۔ اور خداوند نے ظالم سرپرست کی تعریف کی، کیونکہ اس نے حکمت سے کام کیا: کیونکہ اس دنیا کے بچے اپنی نسل میں روشنی کے بچوں سے زیادہ دانا ہیں۔\n9۔ اور میں آپ سے کہتا ہوں، اپنے آپ کو ناانصافی کے دیو کے دوست بنائیں؛ تاکہ جب تم ناکام ہو جاؤ، تو وہ تمہیں دائمی رہائش گاہوں میں قبول کر سکیں۔ {مامون: یا، دولت}\n10۔ جو کم سے کم میں وفادار ہے وہ بہت سے میں بھی وفادار ہے: اور جو کم میں ناانصافی کرتا ہے وہ بہت سے معاملات میں بھی ناانصافی کرتا ہے۔\n11۔ اگر تم ناجائز مامون پر وفادار نہیں رہے، تو کون تمہارے امانت میں سچی دولت کا سپرد کرے گا؟ {مامون: یا، دولت}\n12۔ اور اگر تم کسی اور کی چیز میں وفادار نہیں رہے، تو کون تمہیں تمہارا اپنا دے گا؟\n13۔ کوئی خادم دو مالکان کی خدمت نہیں کر سکتا: کیونکہ یا تو وہ ایک سے نفرت کرے گا اور دوسرے سے محبت کرے گا؛ ورنہ وہ ایک کو تھامے رہتا ہے اور دوسرے سے نفرت کرتا ہے۔ تم خدا اور مامون کی خدمت نہیں کر سکتے۔\n14۔ اور فریسی بھی، جو لالچی تھے، نے یہ سب باتیں سنیں: اور انہوں نے اس کا مذاق اڑایا۔\n15۔ اور اس نے ان سے کہا، تم وہ ہو جو انسانوں کے سامنے خود کو راستباز بناتے ہو؛ لیکن خدا تمہارے دلوں کو جانتا ہے: کیونکہ جو چیز انسانوں میں بہت معزز ہے وہ خدا کی نظر میں مکروہ ہے۔\n16۔ شریعت اور نبی {تھے} یہاں تک کہ یوحنا تک: اس وقت سے خدا کی بادشاہی کی تبلیغ کی جاتی ہے، اور ہر انسان اس میں شامل ہوتا ہے۔\n17. اور آسمان و زمین کے لیے پاس ہونا آسان ہے، بجائے اس کے کہ قانون کا ایک عنوان ناکام ہو جائے۔\n18۔ جو اپنی بیوی کو چھوڑ کر کسی اور سے شادی کرے گا، وہ کرے گا: اور جو اس عورت سے شادی کرے جو اس کے شوہر سے الگ ہو گئی ہے وہ کرے گا۔\n19۔ ایک امیر آدمی تھا، جو جامنی اور عمدہ کپڑوں میں ملبوس تھا، اور ہر روز شاہانہ کام کرتا تھا:\n20۔ اور ایک بھکاری تھا جس کا نام لازر تھا، جو اس کے دروازے پر پڑا تھا، زخموں سے بھرا ہوا،\n21. اور امیر آدمی کی میز سے گرنے والے ٹکڑوں سے کھلانے کی خواہش میں: مزید کتے آئے اور اس کے زخموں کو چاٹنے لگے۔\n22۔ اور ایسا ہوا کہ بھکاری مر گیا، اور فرشتوں نے اسے ابراہیم کی گود میں لے جایا: امیر آدمی بھی مر گیا، اور دفن کر دیا گیا؛\n23. اور جہنم میں وہ اپنی آنکھیں اٹھاتا ہے، عذاب میں ہوتا ہے، اور ابراہیم کو دور سے اور لازر کو اپنے سینے میں غصہ دلاتا ہے۔\n24۔ اور اس نے پکارا اور کہا، باپ ابراہیم، مجھ پر رحم کرو اور لازرس کو بھیج دو، تاکہ وہ اپنی انگلی کی نوک پانی میں ڈبو دے اور میری زبان کو ٹھنڈا کر دے؛ کیونکہ میں اس شعلے میں عذاب میں ہوں۔\n25۔ لیکن ابراہیم نے کہا، بیٹا، یاد رکھو کہ تم نے اپنی زندگی میں اپنی اچھی چیزیں حاصل کیں، اور اسی طرح لازر نے بھی برے کام حاصل کیے، لیکن اب وہ تسلی پا رہا ہے، اور تم عذاب میں ہو۔\n26۔ اور اس سب کے علاوہ، ہمارے اور تمہارے درمیان ایک بڑی خلیج ہے: تاکہ وہ لوگ جو یہاں سے تم تک پہنچنا چاہتے ہیں، وہ نہ آ سکیں؛ اور نہ ہی وہ ہمیں منتقل ہو سکتے ہیں، جو {وہاں سے آئے گا}۔\n27۔ پھر اس نے کہا، اس لیے میں تم سے دعا کرتا ہوں، اے باپ، کہ تم اسے میرے والد کے گھر بھیجو:\n28۔ کیونکہ میرے پانچ بھائی ہیں؛ تاکہ وہ ان کے سامنے گواہی دے سکے، ورنہ وہ بھی اس اذیت کی جگہ میں آ جائیں گے۔\n29۔ ابراہیم نے اسے کہا، ان کے پاس موسیٰ اور نبی ہیں؛ انہیں سننے دیں۔\n30۔ اور اس نے کہا، نہیں، باپ ابراہیم: لیکن اگر کوئی مردوں میں سے ان کے پاس جائے تو وہ توبہ کرے گا۔\n31۔ اور اس نے اس سے کہا، اگر وہ موسیٰ اور انبیاء کی بات نہ سنیں تو وہ قائل بھی نہیں ہوں گے، چاہے کوئی مردوں میں سے زندہ ہو جائے۔","1۔ پھر اس نے شاگردوں سے کہا، یہ ناممکن ہے سوائے اس کے کہ گناہ آئیں گے، لیکن افسوس کہ وہ کس کے ذریعے آتے ہیں!\n2. اس کے لیے بہتر تھا کہ اس کی گردن میں ایک چکی کا پتھر لٹکایا جائے اور وہ سمندر میں پھینک دے، بجائے اس کے کہ وہ ان چھوٹے بچوں میں سے کسی کو ناراض کرے۔\n3۔ ہوشیار رہو: اگر تمہارا بھائی تمہارے خلاف گناہ کرے تو اسے ڈانٹو؛ اور اگر وہ توبہ کرے تو اسے معاف کر دینا۔\n4۔ اور اگر وہ دن میں سات بار اور دن میں سات بار تمہارے خلاف غلطی کرے تو پھر تمہاری طرف رجوع کرے اور کہے، میں توبہ کرتا ہوں؛ تم اسے معاف کر دو۔\n5۔ اور رسولوں نے خداوند سے کہا، ہمارا ایمان بڑھاؤ۔\n6۔ اور خداوند نے فرمایا، اگر تم سرسوں کے دانے کی طرح ایمان رکھتے تو اس چنار کے درخت سے کہتے، جڑ سے توڑ دینا، اور سمندر میں بویا جانا؛ اور اسے آپ کی اطاعت کرنی چاہیے۔\n7۔ لیکن تم میں سے کون ہو، جب کوئی نوکر مویشیوں کو جوت چلا رہا ہو یا کھلا رہا ہو، تو وہ اسے کہے گا، جب وہ کھیت سے آئے گا، جا کر بیٹھ کر گوشت کھا لو؟\n8۔ اور میں اسے یہ نہیں کہوں گا، تیار کرو کہ میں کیا کھا سکتا ہوں، خود کو تیار کرو، اور میری خدمت کرو، جب تک میں کھا کر پی نہ لوں؛ اور اس کے بعد تم کھاؤ گے اور پیو گے؟\n9۔ کیا وہ اس خادم کا شکریہ ادا کرتا ہے کیونکہ اس نے وہ کام کیے جو اسے حکم دیا گیا تھا؟ میں نہیں سمجھتا۔\n10۔ اسی طرح، جب آپ نے وہ سب کچھ کیا جو آپ کو حکم دیا گیا ہے، تو کہیں، ہم بے فائدہ خادم ہیں: ہم نے وہ کیا جو ہمارا فرض تھا۔\n11۔ اور جب وہ یروشلم پہنچا تو سامریہ اور گلیل کے درمیان سے گزرا۔\n12۔ اور جب وہ ایک خاص گاؤں میں داخل ہوا، تو وہاں دس مرد ملے جو کوڑھی تھے، جو دور کھڑے تھے:\n13۔ اور انہوں نے اپنی آوازیں بلند کیں اور کہا، یسوع، آقا، ہم پر رحم فرما۔\n14۔ اور جب اس نے انہیں دیکھا، تو اس نے کہا، جاؤ اور پادریوں کو دکھاؤ۔ اور ایسا ہوا کہ جیسے جیسے وہ گئے، وہ پاک ہو گئے۔\n15۔ اور ان میں سے ایک نے جب دیکھا کہ وہ شفا پا گیا ہے، تو پلٹا اور بلند آواز میں خدا کی تمجید کی،\n16۔ اور اس کے قدموں میں اپنے چہرے پر گر پڑا، اس کا شکر ادا کیا: اور وہ سامری تھا۔\n17۔ اور یسوع نے جواب دیا، کیا دس پاک نہیں ہوئے؟ لیکن نو کہاں ہیں؟\n18. ایسے لوگ نہیں ملتے جو خدا کی شان کے لیے واپس آئے، سوائے اس اجنبی کے۔\n19۔ اور اس نے اس سے کہا، اٹھو، اپنا راستہ جاؤ: تمہارا ایمان تمہیں مکمل کر چکا ہے۔\n20۔ اور جب اسے فریسیوں سے پوچھا گیا، جب خدا کی بادشاہی آئے گی، تو اس نے جواب دیا اور کہا، خدا کی بادشاہی مشاہدے سے نہیں آتی: {ساتھ...: یا ظاہری طور پر ظاہر ہو}\n21. نہ ہی وہ کہیں گے، لو یہاں! یا، دیکھو وہاں! کیونکہ دیکھو، خدا کی بادشاہی تمہارے اندر ہے۔ {تمہارے اندر: یا، تمہارے درمیان}\n22۔ اور اس نے شاگردوں سے کہا، وہ دن آئیں گے جب تم انسان کے بیٹے کے دنوں میں سے کسی ایک کو دیکھنا چاہو گے، اور تم اسے نہیں دیکھو گے۔\n23۔ اور وہ آپ سے کہیں گے، یہاں دیکھیں؛ یا، وہاں دیکھیں: {ان} کے پیچھے نہ جاؤ، نہ {ان} کی پیروی کرو۔\n24۔ جیسے بجلی جو آسمان کے نیچے ایک {حصہ} سے روشن ہوتی ہے، دوسرے {حصہ} کو آسمان کے نیچے چمکتی ہے؛ اسی طرح انسان کا بیٹا بھی اپنے زمانے میں ہوگا۔\n25. لیکن سب سے پہلے اسے بہت سی چیزیں برداشت کرنی ہوں گی، اور اس نسل سے مسترد ہونا ہوگا۔\n26۔ اور جیسے نوئے کے زمانے میں تھا، ویسے ہی بیٹے کے زمانے میں بھی ہوگا۔\n27۔ انہوں نے کھایا، پیا، بیویاں کیں، شادی کی گئی، انہیں شادی کے طور پر دیا گیا، یہاں تک کہ وہ دن جب نوئے کشتی میں داخل ہوا، اور سیلاب آیا اور سب کو تباہ کر دیا۔\n28۔ اسی طرح جیسے لوط کے زمانے میں تھا؛ وہ کھاتے، پیتے، خریدتے، بیچتے، پودے لگاتے، تعمیر کرتے؛\n29۔ لیکن جس دن لوط سدوم سے باہر نکلا، آسمان سے آگ اور گندھک برسا، اور سب کو تباہ کر دیا۔\n30۔ اسی دن ایسا ہی ہوگا جب انسان کا بیٹا ظاہر ہوگا۔\n31۔ اس دن، جو گھر کی چھت پر ہوگا اور اس کا سامان گھر میں ہوگا، وہ اسے لے جانے کے لیے نیچے نہ آئے۔ اور جو کھیت میں ہے، وہ بھی واپس نہ آئے۔\n32۔ لوط کی بیوی کو یاد رکھو۔\n33۔ جو اپنی جان بچانے کی کوشش کرے گا وہ اسے کھو دے گا؛ اور جو اپنی جان کھوئے گا وہ اسے محفوظ رکھے گا۔\n34۔ میں تمہیں بتاتا ہوں، اس رات ایک بستر میں دو {آدمی} ہوں گے؛ ایک لیا جائے گا، اور دوسرا چھوڑ دیا جائے گا۔\n35۔ دو {عورتیں} ایک ساتھ رگڑیں گی؛ ایک لیا جائے گا، اور دوسرا چھوڑ دیا جائے گا۔\n36۔ دو {آدمی} میدان میں ہوں گے؛ ایک لیا جائے گا، اور دوسرا چھوڑ دیا جائے گا۔ {یہ آیت زیادہ تر یونانی نقول میں نہیں ملتی ہے}\n37۔ اور انہوں نے جواب دیا اور اس سے کہا، اے خداوند؟ اور اس نے ان سے کہا، جہاں بھی لاش {ہو}، وہاں عقاب جمع ہوں گے۔","1۔ اور اس نے ان کے لیے ایک تمثیل سنائی کہ لوگ ہمیشہ دعا کریں، اور بے ہوش نہ ہوں؛\n2۔ کہتا ہے، ایک شہر میں ایک منصف تھا، جو خدا سے نہیں ڈرتا تھا، نہ ہی انسان کو دیکھتا تھا: {ایک شہر میں: انگریزی کسی خاص شہر میں}\n3۔ اور اس شہر میں ایک بیوہ تھی؛ اور وہ اس کے پاس آئی اور کہا، میرے دشمن کا بدلہ لو۔\n4۔ اور وہ کچھ دیر تک ایسا نہیں کرتا: لیکن بعد میں اس نے اپنے دل میں کہا، اگرچہ میں خدا سے نہیں ڈرتا، نہ انسان کو دیکھتا ہوں؛\n5۔ پھر بھی چونکہ یہ بیوہ مجھے پریشان کرتی ہے، میں اس کا بدلہ لوں گا، ورنہ اس کی مسلسل آمد سے وہ مجھے تھکا دے گی۔\n6۔ اور خداوند نے فرمایا، ظالم منصف کی بات سنو۔\n7۔ اور کیا خدا اپنے منتخب لوگوں کا بدلہ نہیں لے گا، جو دن رات اس کے لیے پکار رہے ہیں، چاہے وہ ان کے ساتھ طویل صبر کرے؟\n8. میں تمہیں بتاتا ہوں کہ وہ جلد ہی ان کا بدلہ لے گا۔ پھر بھی جب انسان کا بیٹا آئے گا، کیا وہ زمین پر ایمان پائے گا؟\n9۔ اور اس نے یہ تمثیل ان لوگوں کو سنائی جو اپنے آپ پر بھروسہ کرتے تھے کہ وہ راستباز ہیں، اور دوسروں کو حقیر سمجھتے ہیں: {کہ...: یا، نیک ہونے کے طور پر}\n10۔ دو آدمی عبادت کے لیے مندر میں گئے؛ ایک فریسی تھا، اور دوسرا پبلکن۔\n11۔ فریسی کھڑا ہو کر اپنے آپ سے دعا کرتا رہا، خدا، میں تیرا شکر ادا کرتا ہوں کہ میں دوسرے لوگوں کی طرح نہ ہوں، بھتہ خور، ناانصاف،، یا یہاں تک کہ یہ پبلکن۔\n12۔ میں ہفتے میں دو بار روزہ رکھتا ہوں، اور اپنی تمام چیزوں کا عشر دیتا ہوں۔\n13۔ اور دور کھڑا مالک، اپنی آنکھیں آسمان کی طرف بھی نہیں اٹھا رہا تھا، بلکہ اس نے اپنے سینے پر تھپڑ مارا اور کہا، خدا مجھ پر رحم کرے، ایک گنہگار۔\n14۔ میں تمہیں بتاتا ہوں، یہ آدمی دوسرے سے زیادہ راستباز ہو کر اپنے گھر گیا: کیونکہ جو بھی خود کو بلند کرے گا وہ ذلیل ہوگا؛ اور جو خود کو عاجز کرے گا وہ بلند ہوگا۔\n15۔ اور انہوں نے اس کے پاس بچے بھی لائے تاکہ وہ انہیں چھوئے، لیکن جب {اس کے} شاگردوں نے اسے دیکھا تو انہوں نے انہیں ڈانٹا۔\n16۔ لیکن یسوع نے انہیں اپنے پاس بلایا اور کہا، چھوٹے بچوں کو میرے پاس آنے دو، اور انہیں منع نہ کرو، کیونکہ خدا کی بادشاہی انہی کی ہے۔\n17۔ یقینا میں تم سے کہتا ہوں، جو بھی بچپن کی طرح خدا کی بادشاہی قبول نہیں کرے گا، وہ کبھی بھی اس میں داخل نہیں ہو سکتا۔\n18۔ اور ایک حکمران نے اس سے پوچھا، اچھے مالک، میں ابدی زندگی کے لیے کیا کروں؟\n19۔ اور یسوع نے اس سے کہا، تم مجھے اچھا کیوں کہتے ہو؟ کوئی بھی اچھا نہیں، سوائے ایک کے، یعنی خدا۔\n20۔ تم احکامات جانتے ہو، نہ کرو، قتل نہ کرو، چوری نہ کرو، جھوٹی گواہی نہ دو، اپنے والد اور ماں کی عزت کرو۔\n21۔ اور اس نے کہا، یہ سب میں نے اپنی جوانی سے سنبھال کر رکھا ہے۔\n22۔ اب جب یسوع نے یہ باتیں سنیں، تو اس نے اسے کہا، پھر بھی تمہارے پاس ایک چیز نہیں: جو کچھ تمہارے پاس ہے اسے بیچ دو، اور غریبوں میں تقسیم کر دو، تو تمہارے پاس آسمان میں خزانہ ہوگا: اور آؤ، میرے پیچھے آؤ۔\n23۔ اور جب اس نے یہ سنا تو وہ بہت افسردہ ہوا: کیونکہ وہ بہت امیر تھا۔\n24۔ اور جب یسوع نے دیکھا کہ وہ بہت غمگین ہے، تو اس نے کہا، \"کتنی مشکل سے وہ لوگ جن کے پاس دولت ہے وہ خدا کی بادشاہی میں داخل ہوں گے!\"\n25۔ کیونکہ اونٹ کے لیے سوئی کی آنکھ سے گزرنا آسان ہے، بنسبت امیر آدمی کے خدا کی بادشاہی میں داخل ہونے کے۔\n26۔ اور جنہوں نے یہ سنا، انہوں نے کہا، تو پھر کون بچایا جا سکتا ہے؟\n27۔ اور اس نے کہا، جو چیزیں انسانوں کے ساتھ ناممکن ہیں، وہ خدا کے ساتھ ممکن ہیں۔\n28۔ پھر پطرس نے کہا، دیکھو، ہم سب کو چھوڑ کر تیری پیروی کر رہے ہیں۔\n29۔ اور اس نے ان سے کہا، \"یقینا میں تم سے کہتا ہوں، کوئی مرد نہیں جو خدا کی بادشاہی کے لیے گھر، والدین، بھائی، بیوی یا بچوں کو چھوڑ کر گیا ہو،\n30۔ جو اس موجودہ وقت اور آخرت میں ابدی زندگی میں کئی گنا زیادہ حاصل نہیں کرے گا۔\n31۔ پھر اس نے بارہ کو لے کر ان سے کہا، دیکھو، ہم یروشلم جاتے ہیں، اور وہ سب کچھ جو نبیوں نے بیٹے کے بارے میں لکھا ہے، وہ مکمل ہو جائے گا۔\n32۔ کیونکہ اسے غیر قوموں کے حوالے کیا جائے گا، اور اس کا مذاق اڑایا جائے گا، نفرت سے التجا کی جائے گی، اور اس پر تھوکا جائے گا:\n33۔ اور وہ اسے کوڑے ماریں گے، اور اسے قتل کریں گے، اور تیسرے دن وہ دوبارہ زندہ ہوگا۔\n34۔ اور وہ ان میں سے کوئی بات نہیں سمجھ سکے: اور یہ قول ان سے چھپا دیا گیا، نہ ہی وہ باتیں جانتے تھے جو کہی جا رہی تھیں۔\n35۔ اور ایسا ہوا کہ جب وہ یریحو کے قریب پہنچا تو ایک اندھا آدمی راستے کے کنارے بیٹھا منتیں کر رہا تھا:\n36۔ اور جب اس نے ہجوم کو گزرتے سنا، تو اس نے پوچھا کہ اس کا کیا مطلب ہے۔\n37۔ اور انہوں نے اسے بتایا کہ ناصری کے یسوع گزر گئے ہیں۔\n38۔ اور اس نے پکارا، کہا، یسوع، {تو} داؤد کے بیٹے، مجھ پر رحم فرما۔\n39۔ اور جو لوگ آگے گئے تھے انہوں نے اسے ڈانٹا کہ وہ خاموش رہے: لیکن وہ اتنا زیادہ روتا رہا، {تو} داؤد کے بیٹے، مجھ پر رحم فرما۔\n40۔ اور یسوع کھڑا ہوا اور حکم دیا کہ اسے اس کے پاس لایا جائے، اور جب وہ قریب آیا تو اس سے پوچھا،\n41۔ کہتا ہے، تم کیا کرو گے کہ میں تمہارے ساتھ کیا کروں؟ اور اس نے کہا، اے خداوند، تاکہ میں اپنی بینائی حاصل کر سکوں۔\n42۔ اور یسوع نے اسے کہا، اپنی نظر قبول کرو: تمہارا ایمان تمہیں بچا چکا ہے۔\n43۔ اور فورا اس نے اپنی بینائی حاصل کی، اور اس کے پیچھے چلتا ہوا خدا کی جلال میں آیا: اور جب سب لوگ اسے دیکھتے تو خدا کی حمد کرتے رہے۔","1۔ اور {یسوع} یریحو میں داخل ہوا اور گزرا۔\n2۔ اور دیکھو، {وہاں ایک آدمی تھا جس کا نام زکائی تھا}، جو سب سے بڑا پبلکرز تھا، اور وہ امیر تھا۔\n3۔ اور اس نے یسوع کو وہ دیکھنا چاہا جو وہ تھا؛ اور پریس کے لیے ایسا نہیں ہو سکا، کیونکہ وہ کم قد کا تھا۔\n4۔ اور وہ پہلے دوڑا، اور ایک خوشامد کے درخت پر چڑھ گیا تاکہ اسے دیکھ سکے: کیونکہ وہ اس راستے سے گزرنا تھا۔\n5۔ اور جب یسوع اس جگہ پہنچے، تو انہوں نے اوپر دیکھا، اسے دیکھ کر کہا، زکائی، جلدی کرو اور نیچے آؤ؛ کیونکہ آج مجھے تمہارے گھر میں رہنا ہے۔\n6۔ اور وہ جلدی میں آیا، نیچے آیا اور خوشی سے اس کا استقبال کیا۔\n7۔ اور جب انہوں نے یہ دیکھا تو سب نے سرگوشی کی، کہنے لگے، کہ وہ ایک گناہ گار کے ساتھ مہمان بننے گیا ہے۔\n8۔ اور زکائی کھڑا ہوا اور خداوند سے کہا؛ دیکھو، اے خداوند، میں اپنی آدھی مال غریبوں کو دیتا ہوں؛ اور اگر میں نے کسی انسان سے جھوٹے الزام سے کچھ لیا ہے، تو میں اسے چار گنا واپس دیتا ہوں۔\n9۔ اور یسوع نے اس سے کہا، آج نجات ہے، اس گھر میں آؤ، کیونکہ وہ بھی ابراہیم کا بیٹا ہے۔\n10۔ کیونکہ انسان کا بیٹا آیا ہے تاکہ کھوئی ہوئی چیزوں کو تلاش کرے اور بچائے۔\n11۔ اور جب انہوں نے یہ باتیں سنیں، تو اس نے ایک تمثیل شامل کی اور سنائی، کیونکہ وہ یروشلم کے قریب تھا، اور کیونکہ وہ سمجھتے تھے کہ خدا کی بادشاہی فورا ظاہر ہونی چاہیے۔\n12۔ اس لیے اس نے کہا، ایک اشرافیہ ایک دور دراز ملک گیا تاکہ اپنے لیے بادشاہت حاصل کرے اور واپس آ جائے۔\n13۔ اور اس نے اپنے دس خادموں کو بلایا، انہیں دس پاؤنڈ دیے، اور کہا، جب تک میں نہ آؤں، یہاں رہو۔ {پاؤنڈ: مینا، یہاں ایک پاؤنڈ، بارہ اونس اور آدھا ہے: جو پانچ شلنگ کے مطابق ایک اونس تین پاؤنڈ دو شلنگ اور چھ پنس ہے}\n14۔ لیکن اس کے شہری اس سے نفرت کرنے لگے، اور اس کے بعد پیغام بھیجا کہ ہم اس {انسان} کو اپنے اوپر حکومت کرنے نہیں دیں گے۔\n15۔ اور ایسا ہوا کہ جب وہ واپس آیا، بادشاہی حاصل کر کے، تو اس نے ان خادموں کو حکم دیا کہ وہ اس کے پاس بلائے جائیں، جنہیں اس نے پیسے دیے تھے، تاکہ وہ جان سکے کہ ہر آدمی نے تجارت سے کتنا فائدہ اٹھایا۔ {پیسہ: گریڈ سلور}\n16۔ پھر پہلا آیا، اور کہا، اے خداوند، تیرے پاؤنڈ دس پاؤنڈ بڑھ گئے ہیں۔\n17۔ اور اس نے اس سے کہا، اے اچھے خادم: چونکہ تم بہت کم میں وفادار رہے ہو، اس لیے دس شہروں پر تمہارا اختیار ہے۔\n18۔ اور دوسرا آیا، کہتا ہوا، اے خداوند، تیرے پاؤنڈ نے پانچ پاؤنڈ بڑھ گئے ہیں۔\n19۔ اور اس نے اسی طرح اس سے کہا، تو بھی پانچ شہروں پر رہو۔\n20۔ اور ایک اور آیا، کہنے لگا، اے خداوند، دیکھو، یہ رہا تمہارا پاؤنڈ، جو میں نے نیپکن میں رکھا ہوا ہے:\n21۔ کیونکہ میں تم سے ڈرتا تھا، کیونکہ تم سخت گیر آدمی ہو: تم وہ چیز اٹھاتے ہو جو تم نے نہیں چھوڑا، اور وہ کاٹتا ہے جو تم نے بویا نہیں۔\n22۔ اور وہ اس سے کہتا ہے، میں تمہارے منہ سے تمہیں فیصلہ کروں گا، {تو} ظالم بندہ۔ تم جانتے تھے کہ میں ایک سخت گیر آدمی ہوں، قبول کیا کہ میں نے نہیں چھوڑا، اور وہ کاٹا جو میں نے نہیں بویا:\n23۔ تو پھر تم نے میرا پیسہ بینک میں کیوں نہیں دیا، تاکہ میرے آنے پر میں اپنا سود طلب کر سکوں؟ {پیسہ: گریڈ سلور}\n24۔ اور اس نے جو کھڑے تھے ان سے کہا، اس سے پاؤنڈ لے لو، اور دس پاؤنڈ والے کو دے دو۔\n25۔ (اور انہوں نے اس سے کہا، اے خداوند، اس کے پاس دس پاؤنڈ ہیں۔)\n26۔ کیونکہ میں تم سے کہتا ہوں، کہ ہر اس کو دیا جائے گا؛ اور جس کے پاس نہیں ہے، وہ بھی اس سے چھین لیا جائے گا۔\n27. لیکن وہ میرے دشمن، جو نہیں چاہتے کہ میں ان پر حکومت کروں، یہاں لے آؤ، اور انہیں میرے سامنے مار ڈالیں۔\n28۔ اور جب اس نے یہ بات کہی، تو وہ پہلے گیا، یروشلم کی طرف چڑھ گیا۔\n29۔ اور ایسا ہوا، جب وہ بیت فاج اور بیتھنی کے قریب پہنچا، اس پہاڑ پر جسے {زیتون کا پہاڑ} کہا جاتا ہے، اس نے اپنے دو شاگرد بھیجے،\n30۔ کہتے ہوئے، تم گاؤں میں جاؤ {تمہارے} کے خلاف؛ جس میں تم داخل ہو کر ایک گھوڑا بندھا ہوا پاؤ گے، جس پر کبھی انسان نہیں بیٹھا: اسے چھوڑ دو، اور یہاں لے آؤ۔\n31۔ اور اگر کوئی تم سے پوچھے، تم اسے کیوں کھو دیتے ہو؟ یوں تم اسے کہو گے، کیونکہ خداوند کو اس کی ضرورت ہے۔\n32۔ اور جو بھیجے گئے وہ اپنے راستے گئے، اور پایا جیسے اس نے ان سے کہا تھا۔\n33۔ اور جب وہ کولٹ کو کھو رہے تھے، اس کے مالکان نے ان سے کہا، تم نے کولٹ کیوں کھویا؟\n34۔ اور انہوں نے کہا، خداوند کو اس کی ضرورت ہے۔\n35۔ اور وہ اسے یسوع کے پاس لے گئے، اور اپنے کپڑے گھوڑے پر ڈالے، اور یسوع کو اس پر بٹھا دیا۔\n36۔ اور جب وہ جا رہا تھا، تو وہ اپنے کپڑے راستے میں پھیلا رہے تھے۔\n37۔ اور جب وہ قریب پہنچا، اب بھی زیتون کے پہاڑ کے اترنے پر، تو تمام شاگردوں نے خوشی منانا شروع کر دی اور خدا کی بلند آواز میں ان تمام عظیم کاموں کی تعریف کرنے لگے جو انہوں نے دیکھے تھے؛\n38۔ کہتے ہوئے، مبارک ہو وہ بادشاہ جو خداوند کے نام پر آتا ہے: آسمان میں امن، اور سب سے بلند میں جلال۔\n39۔ اور ہجوم میں سے کچھ فریسیوں نے اسے کہا، استاد، اپنے شاگردوں کو ڈانٹو۔\n40۔ اور اس نے جواب دیا اور ان سے کہا، میں تم سے کہتا ہوں کہ اگر یہ خاموش رہیں تو پتھر فورا چیخ اٹھیں گے۔\n41۔ اور جب وہ قریب آیا، اس نے شہر کو دیکھا اور اس پر رو پڑا،\n42. کہتے ہوئے، اگر تم جانتے تو کم از کم آج تمہارے دن میں، وہ چیزیں جو تمہارے امن کی ملکیت ہیں! لیکن اب وہ تمہاری آنکھوں سے چھپے ہوئے ہیں۔\n43۔ کیونکہ تم پر دن آئیں گے، جب تمہارے دشمن تمہارے گرد خندق ڈالیں گے، تمہیں گھیر لیں گے، اور تمہیں ہر طرف سے بند کریں گے،\n44۔ اور تمہیں زمین کے برابر رکھوں گا، اور تمہارے بچوں کو تمہارے اندر رکھوں گا؛ اور وہ تم میں ایک پتھر دوسرے پتھر کو نہیں چھوڑیں گے؛ کیونکہ تمہیں اپنی آمد کا وقت معلوم نہیں تھا۔\n45۔ اور وہ مندر میں گیا، اور وہاں بیچنے والوں اور خریدنے والوں کو نکالنے لگا؛\n46۔ انہیں کہتے ہوئے، لکھا ہے، میرا گھر نماز کا گھر ہے: لیکن تم نے اسے چوروں کا ٹھکانہ بنا لیا ہے۔\n47۔ اور وہ روزانہ مندر میں تعلیم دیتا تھا۔ لیکن سردار کاہن، کاتب اور قوم کے سردار نے اسے تباہ کرنے کی کوشش کی،\n48۔ اور وہ نہیں جان سکا کہ وہ کیا کر سکتے ہیں: کیونکہ سب لوگ اس کی بات سننے کے لیے بہت توجہ دے رہے تھے۔ {تھے...: یا، اس پر پھانسی دی گئی}","1۔ اور ایسا ہوا، {کہ} ایک دن، جب اس نے ہیکل میں لوگوں کو تعلیم دی اور انجیل کی تبلیغ کی، سردار پادری اور کاتب بزرگوں کے ساتھ اس کے پاس آئے،\n2۔ اور اس سے کہا، بتاؤ، یہ سب کس اختیار سے کرتے ہو؟ یا وہ کون ہے جس نے تمہیں یہ اختیار دیا؟\n3۔ اور اس نے جواب دیا اور ان سے کہا، میں بھی تم سے ایک بات پوچھوں گا؛ اور مجھے جواب دیں:\n4۔ یوحنا کا بپتسمہ، کیا وہ آسمان سے تھا یا انسانوں سے؟\n5۔ اور انہوں نے خود سے دلیل کی، کہا، اگر ہم کہیں، آسمان سے؛ وہ کہے گا، پھر تم نے اس پر کیوں یقین نہیں کیا؟\n6۔ لیکن اگر ہم کہیں، انسانوں کے بارے میں؛ تمام لوگ ہمیں پتھر ماریں گے: کیونکہ وہ قائل ہوں گے کہ یوحنا نبی تھا۔\n7۔ اور انہوں نے جواب دیا کہ وہ نہیں بتا سکتے کہ یہ کہاں سے ہے۔\n8۔ اور یسوع نے ان سے کہا، میں تمہیں نہیں بتاتا کہ میں یہ سب کس اختیار سے کرتا ہوں۔\n9۔ پھر اس نے لوگوں سے یہ تمثیل سنانا شروع کی؛ ایک شخص نے ایک انگور کا باغ لگایا، اسے کسانوں کو دے دیا، اور طویل عرصے تک دور دراز ملک میں چلا گیا۔\n10۔ اور اس وقت اس نے کسانوں کے پاس ایک خادم بھیجا تاکہ وہ اسے انگور کے پھل میں سے دے دیں، لیکن کسانوں نے اسے مارا اور خالی چھوڑ دیا۔\n11۔ اور پھر اس نے ایک اور خادم بھیجا: اور انہوں نے اسے بھی مارا، شرمندگی سے التجا کی، اور اسے خالی چھوڑ دیا۔\n12۔ اور پھر اس نے تیسرا بھیجا: اور انہوں نے اسے بھی زخمی کیا، اور اسے نکال دیا۔\n13۔ پھر باغ کے مالک نے کہا، میں کیا کروں؟ میں اپنے پیارے بیٹے کو بھیجوں گا: شاید جب وہ اسے دیکھیں گے تو اس کی عزت کریں گے۔\n14۔ لیکن جب کسانوں نے اسے دیکھا، تو انہوں نے آپس میں بحث کی، یہ وارث ہے: آؤ، اسے مار ڈالیں، تاکہ وراثت ہماری ہو۔\n15۔ تو انہوں نے اسے انگور کے باغ سے نکال دیا اور {اسے} قتل کر دیا۔ تو انگور کے باغ کا مالک ان کے ساتھ کیا کرے گا؟\n16۔ وہ آئے گا اور ان کسانوں کو تباہ کرے گا، اور انگور کا باغ دوسروں کو دے گا۔ اور جب انہوں نے سنا تو کہا، خدا نہ کرے۔\n17۔ اور اس نے انہیں دیکھا اور کہا، تو پھر یہ کیا ہے جو لکھا ہے، وہ پتھر جسے معماروں نے رد کیا، وہ کونے کا سر بن گیا؟\n18۔ جو بھی اس پتھر پر گرا گا وہ ٹوٹ جائے گا؛ لیکن جس پر یہ گرے، وہ اسے پاؤدر میں بدل دے گا۔\n19۔ اور اسی وقت سردار پادریوں اور کاتبوں نے اس پر ہاتھ رکھنے کی کوشش کی؛ اور وہ لوگوں سے ڈرتے تھے: کیونکہ انہوں نے محسوس کیا کہ اس نے ان کے خلاف یہ تمثیل سنائی ہے۔\n20۔ اور انہوں نے [اسے} پر نظر رکھی، اور جاسوس بھیجے، جو خود کو انصاف پسند ظاہر کرنے کا ڈرامہ کریں، تاکہ وہ اس کے الفاظ کو سمجھ سکیں، تاکہ وہ اسے گورنر کے اقتدار اور اختیار کے حوالے کر سکیں۔\n21۔ اور انہوں نے اس سے پوچھا، کہا، استاد، ہم جانتے ہیں کہ تم صحیح کہتے اور سکھاتے ہو، نہ تو کسی کے شخص کو قبول کرتے، بلکہ خدا کا راستہ سچائی سے سکھاتے ہو: {سچ میں: یا سچائی کا}\n22. کیا ہمارے لیے قیصر کو خراج دینا جائز ہے یا نہیں؟\n23۔ لیکن اس نے ان کی چالاکی دیکھی اور ان سے کہا، تم مجھے کیوں بہکاتے ہو؟\n24۔ مجھے ایک پیسہ دکھاؤ۔ یہ کس کی تصویر اور اوپر لکھا ہوا ہے؟ انہوں نے جواب دیا اور کہا، سیزر کا۔\n25۔ اور اس نے ان سے کہا، تو قیصر کو وہ چیزیں دو جو قیصر کی ہیں، اور خدا کو وہ چیزیں جو خدا کی ہیں۔\n26۔ اور وہ اس کے الفاظ کو لوگوں کے سامنے نہ سن سکے، اور اس کے جواب پر حیران رہ گئے اور خاموش رہے۔\n27۔ پھر صدوقیوں میں سے کچھ لوگ آئے جو کسی قیامت سے انکار کرتے ہیں؛ اور انہوں نے اس سے پوچھا،\n28۔ آقا، موسیٰ نے ہمیں لکھا، اگر کسی آدمی کا بھائی مر جائے اور اس کی بیوی ہو اور وہ بغیر اولاد کے مر جائے، تو اس کا بھائی اس کی بیوی لے کر اپنے بھائی کے لیے اولاد پیدا کرے۔\n29۔ اس لیے سات بھائی تھے: اور پہلے نے شادی کی اور بغیر اولاد کے فوت ہو گیا۔\n30۔ اور دوسرے نے اسے بیوی بنا لیا، اور وہ بغیر اولاد کے فوت ہو گیا۔\n31۔ اور تیسرے نے اسے لے لیا؛ اور اسی طرح سات بھی: اور انہوں نے کوئی اولاد نہیں چھوڑی اور فوت ہو گئے۔\n32۔ آخر میں، وہ عورت بھی فوت ہو گئی۔\n33۔ لہٰذا قیامت میں وہ ان کی بیوی کس کی ہے؟ کیونکہ سات نے اسے بیوی بنا لیا تھا۔\n34۔ اور یسوع نے جواب میں ان سے کہا، اس دنیا کے بچے شادی کرتے ہیں اور شادی میں دیے جاتے ہیں:\n35. لیکن جو لوگ اس دنیا اور مردوں میں سے دوبارہ زندہ ہونے کے لائق شمار کیے جائیں، وہ نہ شادی کرتے ہیں اور نہ ہی شادی میں دیے جاتے ہیں:\n36۔ اور وہ مزید نہیں مر سکتے: کیونکہ وہ فرشتوں کے برابر ہیں؛ اور وہ خدا کے بچے ہیں، جو قیامت کے بچے ہیں۔\n37۔ اب جب کہ مردہ زندہ ہو چکے ہیں، تو موسیٰ نے بھی جھاڑی میں دکھایا جب وہ خداوند کو ابراہیم کا خدا، اسحاق کے خدا اور یعقوب کے خدا کو پکارتا ہے۔\n38۔ کیونکہ وہ مردوں کا خدا نہیں، بلکہ زندوں کا ہے: کیونکہ سب اس کے لیے زندہ ہیں۔\n39۔ پھر کچھ کاتبوں نے جواب دیا، آقا، آپ نے بہت اچھا کہا۔\n40۔ اور اس کے بعد وہ اس سے کوئی {سوال} پوچھنے کی ہمت نہیں کر سکے۔\n41۔ اور اس نے ان سے کہا، وہ کیسے کہتے ہیں کہ مسیح داؤد کا بیٹا ہے؟\n42۔ اور داؤد خود زبور کی کتاب میں فرماتا ہے، خداوند نے میرے رب سے کہا، تو میرے دائیں ہاتھ پر بیٹھو،\n43۔ جب تک میں تمہارے دشمنوں کو تمہارا پاؤں کا اسٹول نہ بنا دوں۔\n44۔ اس لیے داؤد اسے خداوند کہتا ہے، تو وہ اس کا بیٹا کیسے ہے؟\n45۔ پھر اس نے تمام لوگوں کے سامعین میں اپنے شاگردوں سے کہا،\n46۔ کاتبوں سے ہوشیار رہو، جو لمبے لباس میں چلنا چاہتے ہیں، بازاروں میں سلام دعا کرتے ہیں، اور عبادت گاہوں کی سب سے اونچی نشستوں اور تہواروں کے اہم کمروں میں سلام کرتے ہیں؛\n47۔ جو بیواؤں کے گھروں کو کھا جاتے ہیں اور طویل دعائیں کرتے ہیں: انہی کو زیادہ عذاب ملے گا۔","1۔ اور اس نے اوپر دیکھا، اور دیکھا کہ امیر لوگ اپنے تحفے خزانے میں ڈال رہے ہیں۔\n2۔ اور اس نے ایک غریب بیوہ کو بھی دیکھا جو وہاں دو مائٹس پھینک رہی تھی۔\n3۔ اور اس نے کہا، ایک سچائی کے بارے میں جو میں تم سے کہتا ہوں، کہ اس غریب بیوہ نے سب سے زیادہ کچھ ڈالا ہے:\n4۔ کیونکہ یہ سب اپنی فراوانی سے خدا کی قربانیوں میں ڈال دیے گئے ہیں؛ لیکن اس نے اپنی غربت سے اپنی تمام زندہ چیزوں میں ڈال دی ہے۔\n5۔ اور جب کچھ لوگوں نے مندر کے بارے میں بات کی کہ اسے اچھے پتھروں اور تحفوں سے مزین کیا گیا تھا، اس نے کہا،\n6. {جہاں تک یہ چیزیں ہیں جو تم دیکھتے ہو، وہ دن آئیں گے، جن میں ایک پتھر دوسرے پر نہیں چھوڑا جائے گا، جو نہیں گرایا جائے گا۔\n7۔ اور انہوں نے اس سے پوچھا، آقا، لیکن یہ سب کب ہوں گے؟ اور جب یہ چیزیں واقع ہوں گی تو کون سی نشانی ہوگی؟\n8۔ اور اس نے کہا، خبردار رہو کہ دھوکہ نہ کھانا: کیونکہ بہت سے میرے نام پر آئیں گے اور کہیں گے، میں {مسیح} ہوں؛ اور وقت قریب آ رہا ہے: اس لیے ان کے پیچھے مت جاؤ۔ {اور وقت: یا، اور، وقت}\n9۔ لیکن جب آپ جنگوں اور ہنگامے کی خبر سنیں تو خوفزدہ نہ ہوں، کیونکہ یہ سب سے پہلے ہونا ہی ہے؛ لیکن اختتام {ہے} وقت کے ساتھ نہیں۔\n10۔ پھر اس نے ان سے کہا، قوم قوم کے خلاف اٹھے گی، اور بادشاہی بادشاہت کے خلاف کھڑے ہوگی:\n11۔ اور مختلف جگہوں پر بڑے زلزلے، قحط اور وبائیں آئیں گی؛ اور آسمان سے خوفناک مناظر اور عظیم نشانیاں آئیں گی۔\n12۔ لیکن ان سب سے پہلے، وہ تم پر ہاتھ رکھیں گے، تمہیں ستائیں گے، تمہیں عبادت خانوں اور جیلوں میں لے جائیں گے، بادشاہوں اور حکمرانوں کے سامنے میرے نام کے لیے پیش کیے جائیں گے۔\n13۔ اور یہ آپ سے گواہی کے لیے رجوع کرے گا۔\n14۔ لہٰذا اپنے دلوں میں بٹھا دو، اس سے پہلے غور نہ کرو جو تم جواب دو گے:\n15۔ کیونکہ میں تمہیں ایک زبان اور حکمت دوں گا، جسے تمہارے تمام مخالفین رد یا مزاحمت نہیں کر سکیں گے۔\n16۔ اور تم والدین، بھائیوں، رشتہ داروں اور دوستوں دونوں سے دھوکہ کھا سکتے ہو؛ اور {کچھ} تم میں سے انہیں قتل کروائیں گے۔\n17۔ اور تم سب {مردوں} سے میرے نام کی خاطر نفرت کرو گے۔\n18۔ لیکن تمہارے سر کا ایک بال بھی مرنے والا نہیں۔\n19۔ اپنے صبر میں اپنی روحوں کا مالک بنیں۔\n20۔ اور جب تم یروشلم کو فوجوں سے گھرا ہوا دیکھو گے، تو جان لو کہ اس کی ویرانی قریب ہے۔\n21۔ پھر جو یہودیہ میں ہیں وہ پہاڑوں کی طرف بھاگ جائیں؛ اور جو لوگ اس کے بیچ میں ہیں وہ باہر نکل جائیں؛ اور جو لوگ ممالک میں ہیں انہیں اس میں داخل نہ ہونے دیں۔\n22۔ کیونکہ یہ انتقام کے دن ہیں، تاکہ جو کچھ لکھا گیا ہے وہ پورا ہو سکے۔\n23. لیکن ان پر جو حاملہ ہیں، اور جو دودھ پیتے ہیں، ان دنوں پر افسوس! کیونکہ زمین میں شدید مصیبت اور اس قوم پر غصہ ہوگا۔\n24۔ اور وہ تلوار کے کنارے سے گرے جائیں گے، اور تمام قوموں میں قید کر دیے جائیں گے: اور یروشلم کو غیر یہودیوں کے ہاتھوں روند دیا جائے گا، جب تک کہ غیر قوموں کا زمانہ پورا نہ ہو جائے۔\n25۔ اور سورج، چاند، اور ستاروں میں نشانیاں ہوں گی؛ اور زمین پر قوموں کی مصیبت، الجھن کے ساتھ؛ سمندر اور لہریں گرج رہی تھیں؛\n26۔ انسانوں کے دل خوف اور زمین پر آنے والی چیزوں کی دیکھ بھال سے ناکام ہو جاتے ہیں: کیونکہ آسمان کی طاقتیں ہل جائیں گی۔\n27۔ اور پھر وہ دیکھیں گے کہ انسان کا بیٹا بادل میں طاقت اور عظمت کے ساتھ آ رہا ہے۔\n28۔ اور جب یہ چیزیں ہونے لگیں، تو اوپر دیکھو، اور اپنے سر اٹھاؤ؛ کیونکہ تمہاری نجات قریب ہے۔\n29۔ اور اس نے ان سے ایک تمثیل سنائی؛ دیکھو انجیر کا درخت، اور تمام درخت؛\n30۔ جب وہ اب نکلتے ہیں، تو تم خود دیکھو اور جانتے ہو کہ گرمیوں کا موسم قریب ہے۔\n31. اسی طرح، جب آپ یہ سب ہوتے دیکھیں، تو جان لیں کہ خدا کی بادشاہی قریب ہے۔\n32. یقینا میں تم سے کہتا ہوں، یہ نسل ختم نہیں ہوگی، جب تک سب کچھ مکمل نہ ہو جائے۔\n33۔ آسمان اور زمین ختم ہو جائیں گے، لیکن میرے الفاظ ختم نہیں ہوں گے۔\n34۔ اور اپنے آپ سے ہوشیار رہو، کہیں تمہارے دل کبھی بھی اس زندگی کی فکروں، نشے اور فکر سے بھر نہ جائیں، اور {یوں} وہ دن تم پر اچانک آ جائے۔\n35۔ کیونکہ یہ جال کی طرح زمین کے چہرے پر بسنے والوں پر آئے گا۔\n36۔ لہٰذا دیکھو، اور ہمیشہ دعا کرو کہ تم ان تمام چیزوں سے بچنے کے لائق ہو جو ہونے والی ہیں، اور انسان کے بیٹے کے سامنے کھڑے ہو جاؤ۔\n37۔ اور دن کے وقت وہ مندر میں تعلیم دے رہے تھے؛ اور رات کو وہ باہر نکلا، اور اس پہاڑ میں ٹھہرا جسے {زیتون کا پہاڑ} کہا جاتا ہے۔\n38۔ اور سب لوگ صبح سویرے مندر میں اس کے پاس آئے، تاکہ اسے سن سکیں۔","1۔ اب خمیر سے پاک روٹی کی عید قریب آ رہی ہے، جسے فسح کہا جاتا ہے۔\n2۔ اور سردار پادریوں اور کاتبوں نے تلاش کیا کہ وہ اسے کیسے مار سکتے ہیں؛ کیونکہ وہ لوگوں سے ڈرتے تھے۔\n3۔ پھر شیطان نے یہودا میں شامل کیا جسے اسخریوطی کہا گیا، جو بارہ میں سے تھا۔\n4۔ اور وہ اپنے راستے پر گیا، اور سردار پادریوں اور کپتانوں سے بات چیت کی کہ وہ اسے ان کے سامنے کیسے دھوکہ دے سکتا ہے۔\n5۔ اور وہ خوش ہوئے، اور وعدہ کیا کہ وہ اسے پیسے دیں گے۔\n6۔ اور اس نے وعدہ کیا، اور موقع تلاش کیا کہ وہ ہجوم کی غیر موجودگی میں اسے ان کے حوالے کر دے۔ {میں...: یا، بغیر ہنگامے کے}\n7۔ پھر وہ دن آیا جب خمیر سے پاک روٹی کا دن آیا، جب فسح کو مارنا ضروری تھا۔\n8۔ اور اس نے پطرس اور یوحنا کو بھیجا، کہا، جاؤ اور ہمارے لیے فسح تیار کرو، تاکہ ہم کھا سکیں۔\n9۔ اور انہوں نے اس سے کہا، تم کہاں تیاری کرو گے؟\n10۔ اور اس نے ان سے کہا، دیکھو، جب تم شہر میں داخل ہو جاؤ گے، وہاں ایک آدمی تم سے ملے گا، جو پانی کا جگ لے کر آئے گا؛ اس کے پیچھے اس گھر میں جاؤ جہاں وہ داخل ہوتا ہے۔\n11۔ اور تم گھر کے نیک آدمی سے کہو گے، مالک تم سے کہتا ہے، مہمان خانہ کہاں ہے، جہاں میں اپنے شاگردوں کے ساتھ فسح کھاؤں گا؟\n12۔ اور وہ آپ کو ایک بڑا اوپر والا کمرہ دکھائے گا جو فرنیچر سے بھرا ہوا ہے: وہاں تیار ہو جاؤ۔\n13۔ اور وہ گئے، اور جیسا کہ اس نے کہا تھا اسے پایا: اور انہوں نے فسح کی تیاری کی۔\n14۔ اور جب وقت آیا، وہ بیٹھ گیا، اور بارہ رسول اس کے ساتھ تھے۔\n15۔ اور اس نے ان سے کہا، خواہش کے ساتھ میں چاہتا ہوں کہ یہ فسح تمہارے ساتھ کھاؤں اس سے پہلے کہ میں تکلیف دکھاؤں: {خواہش کے ساتھ...: یا، میں دل سے چاہتا ہوں}\n16۔ کیونکہ میں تم سے کہتا ہوں، میں اس میں سے مزید نہیں کھاؤں گا، جب تک کہ یہ خدا کی بادشاہی میں پورا نہ ہو جائے۔\n17۔ اور اس نے پیالہ لیا، شکر ادا کیا، اور کہا، یہ لو، اور آپس میں تقسیم کرو:\n18۔ کیونکہ میں تم سے کہتا ہوں، میں انگور کے پھل سے نہیں پیوں گا، جب تک خدا کی بادشاہی نہ آ جائے۔\n19۔ اور اس نے روٹی لی، شکر ادا کیا، اور اسے توڑا، اور انہیں دیا، کہا، یہ میرا جسم ہے جو تمہارے لیے دیا گیا ہے: یہ میری یاد میں کرو۔\n20. اسی طرح کھانے کے بعد پیالہ بھی کہتا ہے، یہ پیالہ {ہے} میرے خون میں نیا عہد نامہ ہے، جو تمہارے لیے بہایا گیا ہے۔\n21۔ لیکن دیکھو، جس نے مجھے دھوکہ دیا اس کا ہاتھ میرے ساتھ میز پر ہے۔\n22۔ اور واقعی انسان کا بیٹا جاتا ہے، جیسا کہ طے پایا گیا تھا: لیکن اس انسان پر افسوس جس کے ہاتھوں اسے دھوکہ دیا گیا ہے!\n23۔ اور انہوں نے آپس میں پوچھنا شروع کیا کہ ان میں سے کون یہ کام کرے گا۔\n24۔ اور ان کے درمیان ایک جھگڑا بھی تھا، جن میں سے سب سے بڑا کس کو شمار کیا جانا چاہیے۔\n25۔ اور اس نے ان سے کہا، غیر یہودیوں کے بادشاہ ان پر حکمرانی کرتے ہیں؛ اور جو لوگ ان پر اختیار رکھتے ہیں انہیں محسن کہا جاتا ہے۔\n26. لیکن تم {ایسا نہیں ہو گے}: لیکن جو تم میں سب سے بڑا ہے، وہ چھوٹے جیسا ہو؛ اور جو سردار ہے، جیسا کہ وہ خدمت کرتا ہے۔\n27. کیا وہ گوشت پر بیٹھا ہے یا جو خدمت کرتا ہے؟ {کیا} وہی نہیں جو گوشت کھاتا ہے؟ لیکن میں تمہارے درمیان ہوں جیسا کہ وہ خدمت کرتا ہے۔\n28۔ تم وہ ہو جو میری آزمائشوں میں میرے ساتھ رہے ہو۔\n29۔ اور میں تمہیں ایک بادشاہت مقرر کرتا ہوں، جیسا کہ میرے والد نے مجھے مقرر کیا ہے؛\n30۔ تاکہ تم میرے بادشاہت میں میرے دسترخوان پر کھاؤ اور پیو، اور تختوں پر بیٹھ کر اسرائیل کے بارہ قبائل کا فیصلہ کرو۔\n31۔ اور خداوند نے فرمایا، سائمن، سائمن، دیکھو، شیطان نے تمہیں چاہا ہے تاکہ وہ تمہیں گندم کی طرح چھانٹ سکے:\n32. لیکن میں نے تمہارے لیے دعا کی ہے کہ تمہارا ایمان کمزور نہ ہو: اور جب تم تبدیل ہو جاؤ تو اپنے بھائیوں کو مضبوط کرو۔\n33۔ اور اس نے اس سے کہا، اے خداوند، میں تمہارے ساتھ جانے کے لیے تیار ہوں، قید میں بھی، اور موت کے لیے۔\n34۔ اور اس نے کہا، میں تمہیں بتاتا ہوں، پیٹر، آج مرغ بانگ نہیں کرے گا، اس سے پہلے کہ تم تین بار انکار کرو کہ تم مجھے جانتے ہو۔\n35۔ اور اس نے ان سے کہا، جب میں نے تمہیں بغیر پرس، کاغذ اور جوتے کے بھیجا تھا، کیا تم میں کچھ کمی تھی؟ اور انہوں نے کہا، کچھ نہیں۔\n36۔ پھر اس نے ان سے کہا، لیکن اب، جس کے پاس پرس ہے، وہ اسے لے لے، اور اسی طرح اس کا کاغذ: اور جس کے پاس تلوار نہیں، وہ اپنا لباس بیچ دے اور خرید لے۔\n37۔ کیونکہ میں تم سے کہتا ہوں کہ جو کچھ لکھا ہے وہ مجھ میں ابھی بھی پورا ہونا چاہیے، اور اسے مجرموں میں شمار کیا گیا: کیونکہ میرے بارے میں جو کچھ ہے اس کا انجام ہوتا ہے۔\n38۔ اور انہوں نے کہا، اے خداوند، دیکھو، یہاں دو تلواریں ہیں۔ اور اس نے ان سے کہا، بس بہت ہو گیا۔\n39۔ اور وہ باہر آیا، اور جیسا کہ ہمیشہ ہوتا تھا، زیتون کے پہاڑ پر گیا؛ اور اس کے شاگرد بھی اس کے ساتھ چلے۔\n40۔ اور جب وہ اس جگہ پہنچا تو اس نے ان سے کہا، دعا کرو کہ تم آزمائش میں نہ پڑو۔\n41۔ اور اسے ایک پتھر کے ڈھالے کے بارے میں ان سے الگ کر دیا گیا، اور وہ گھٹنے ٹیک کر دعا کرنے لگا،\n42۔ اور کہا، ابا، اگر تم چاہو تو یہ پیالہ مجھ سے ہٹا دو: پھر بھی میری مرضی نہیں، بلکہ تمہاری مرضی پوری ہو۔ {رضامند، ہٹانا: Gr. ہٹانے کے لیے تیار}\n43۔ اور آسمان سے ایک فرشتہ اس کے لیے نمودار ہوا، اسے مضبوط بنایا۔\n44۔ اور اذیت میں مبتلا ہو کر اس نے زیادہ خلوص سے دعا کی: اور اس کا پسینہ ایسے تھا جیسے خون کے بڑے قطرے زمین پر گر رہے ہوں۔\n45۔ اور جب وہ دعا سے اٹھا اور اپنے شاگردوں کے پاس آیا، تو اس نے انہیں غم میں سوتے ہوئے پایا،\n46۔ اور ان سے کہا، تم کیوں سو رہے ہو؟ اٹھو اور دعا کرو، کہیں آزمائش نہ ہو جائے۔\n47۔ اور جب وہ ابھی بول رہا تھا، دیکھو ایک ہجوم، اور جو یہودا کہلاتا تھا، بارہ میں سے ایک، ان کے سامنے گیا اور یسوع کے قریب آ کر اسے بوسہ دیا۔\n48۔ لیکن یسوع نے اس سے کہا، یہودا، کیا تو انسان کے بیٹے کو ایک بوسے سے دھوکہ دیتا ہے؟\n49۔ جب اس کے ارد گرد موجود لوگوں نے دیکھا کہ آگے کیا ہونے والا ہے، تو انہوں نے اس سے کہا، اے خداوند، کیا ہم تلوار سے ماریں؟\n50۔ اور ان میں سے ایک نے سردار کاہن کے خادم کو مارا اور اس کا دایاں کان کاٹ دیا۔\n51۔ اور یسوع نے جواب دیا اور کہا، اب تک برداشت کرو۔ اور اس نے اس کے کان کو چھوا، اور اسے شفا دی۔\n52۔ پھر یسوع نے سردار کاہنوں، مندر کے کپتانوں، اور بزرگوں سے کہا جو اس کے پاس آئے تھے، کیا تم چور کی طرح تلواروں اور لاٹھیوں کے ساتھ باہر آؤ گے؟\n53۔ جب میں روزانہ مندر میں تمہارے ساتھ ہوتا تھا، تم نے میرے خلاف ہاتھ نہیں بڑھایا: لیکن یہ تمہارا وقت ہے، اور تاریکی کی طاقت۔\n54۔ پھر انہوں نے اسے لے جایا، اسے لے کر بڑے پادری کے گھر لے گئے۔ اور پیٹر دور سے پیچھے چل پڑا۔\n55۔ اور جب انہوں نے ہال کے بیچ میں آگ جلائی اور ایک ساتھ بٹھائے گئے، پطرس ان کے درمیان بیٹھ گیا۔\n56۔ لیکن ایک خاص لڑکی نے اسے آگ کے پاس بیٹھا دیکھا اور سنجیدگی سے اسے دیکھا اور کہا، یہ آدمی بھی اس کے ساتھ ہے۔\n57۔ اور اس نے انکار کیا، کہا، عورت، میں اسے نہیں جانتا۔\n58۔ اور کچھ دیر بعد کسی اور نے اسے دیکھا اور کہا، تم بھی انہی میں سے ہو۔ اور پیٹر نے کہا، یار، میں نہیں ہوں۔\n59۔ اور ایک گھنٹے کے وقفے کے بعد دوسرے نے اعتماد کے ساتھ کہا، ایک سچائی کے بارے میں جو یہ {آدمی} بھی اس کے ساتھ تھا: کیونکہ وہ گلیلی ہے۔\n60۔ اور پطرس نے کہا، یار، میں نہیں جانتا کہ تم کیا کہہ رہے ہو۔ اور فورا، جب وہ بول رہا تھا، مرغ کا عملہ۔\n61۔ اور خداوند نے پلٹ کر پطرس کو دیکھا۔ اور پطرس کو خداوند کا کلام یاد آیا، جس نے اسے کہا تھا، مرغ کے بانگ کے سامنے، تم مجھے تین بار انکار کرو گے۔\n62۔ اور پطرس باہر گیا، اور شدید رویا۔\n63۔ اور وہ لوگ جنہوں نے یسوع کو تھاما، اس کا مذاق اڑایا اور اسے مارا۔\n64۔ اور جب انہوں نے اس کی آنکھوں پر پٹی باندھی، تو اس کے چہرے پر مارا اور پوچھا، نبوت، تمہیں کس نے مارا؟\n65۔ اور بہت سی دوسری باتیں اس کے خلاف کفر کے طور پر کہی گئیں۔\n66۔ اور جیسے ہی دن آیا، قوم کے بزرگ، سردار کاہنوں اور کاتبوں نے اکٹھے ہو کر اسے اپنی کونسل میں لے جایا اور کہا،\n67۔ کیا تم مسیح ہو؟ بتائیں۔ اور اس نے ان سے کہا، اگر میں تمہیں بتاؤں تو تم یقین نہیں کرو گے:\n68۔ اور اگر میں بھی آپ سے پوچھوں، تو آپ مجھے جواب نہیں دیں گے، نہ مجھے جانے دیں گے۔\n69۔ اس کے بعد انسان کا بیٹا خدا کی طاقت کے دائیں ہاتھ پر بیٹھے گا۔\n70۔ پھر سب نے کہا، کیا تو تو تو خدا کا بیٹا ہو؟ اور اس نے ان سے کہا، تم کہتے ہو کہ میں ہوں۔\n71۔ اور انہوں نے کہا، ہمیں مزید گواہ کی کیا ضرورت ہے؟ کیونکہ ہم نے خود اس کے اپنے منہ کے بارے میں سنا ہے۔","1۔ اور سب لوگ اٹھے اور اسے پیلاطس کے پاس لے گئے۔\n2۔ اور انہوں نے اس پر الزام لگانا شروع کر دیا، کہا، ہم نے اس {آدمی} کو قوم کو بگاڑتے ہوئے پایا اور قیصر کو خراج دینے سے منع کیا، یہ کہتے ہوئے کہ وہ خود مسیح بادشاہ ہے۔\n3۔ اور پیلاطس نے اس سے پوچھا، کہا، کیا تم یہودیوں کے بادشاہ ہو؟ اور اس نے جواب دیا اور کہا، تو کہتا ہے۔\n4۔ پھر پیلاطس نے سردار کاہنوں اور لوگوں سے کہا، مجھے اس آدمی میں کوئی خامی نظر نہیں آتی۔\n5۔ اور وہ زیادہ سخت تھے، کہتے ہوئے، وہ لوگوں کو ہلکا سا محسوس کرتا ہے، اور تمام یہودیوں میں تعلیم دیتا ہے، گلیل سے لے کر اس جگہ تک۔\n6۔ جب پیلاطس نے گلیل کے بارے میں سنا تو اس نے پوچھا کہ کیا وہ گلیلی ہے۔\n7۔ اور جیسے ہی اسے معلوم ہوا کہ وہ ہیرودیس کے دائرہ اختیار میں ہے، اس نے اسے ہیرودیس کے پاس بھیج دیا، جو خود بھی اس وقت یروشلم میں تھا۔\n8۔ اور جب ہیرود نے یسوع کو دیکھا، تو وہ بہت خوش ہوا، کیونکہ وہ اسے طویل عرصے تک دیکھنے کا خواہشمند تھا، کیونکہ اس نے اس کے بارے میں بہت کچھ سن رکھا تھا؛ اور وہ امید کرتا تھا کہ اس نے کوئی معجزہ دیکھا ہوگا۔\n9۔ پھر اس نے اس سے کئی الفاظ میں سوال کیا؛ لیکن اس نے کچھ جواب نہیں دیا۔\n10۔ اور سردار پادری اور کاتب کھڑے ہو کر اس پر سخت الزام لگائے۔\n11۔ اور ہیرودیس نے اپنے جنگی سپاہیوں کے ساتھ اسے شکست دی، اس کا مذاق اڑایا، اسے خوبصورت لباس پہنایا اور دوبارہ پیلاطس کے پاس بھیج دیا۔\n12۔ اور اسی دن پیلاطس اور ہیرودیس دوست بن گئے: کیونکہ اس سے پہلے وہ آپس میں دشمنی میں مبتلا تھے۔\n13۔ اور پیلاطس، جب اس نے سردار کاہنوں، حکمرانوں اور لوگوں کو اکٹھا کیا،\n14۔ میں نے ان سے کہا، تم نے اس آدمی کو میرے پاس لایا ہے، جو لوگوں کو گمراہ کرتا ہے: اور دیکھو، میں نے تم سے پہلے اس کا معائنہ کیا ہے اور اس آدمی میں کوئی غلطی نہیں پائی جو تم اس پر الزام لگاتے ہو:\n15۔ نہیں، نہ ہیرود: کیونکہ میں نے تمہیں اس کے پاس بھیجا تھا؛ اور، دیکھو، اس کے ساتھ موت کے لائق کچھ نہیں کیا جاتا۔\n16۔ اس لیے میں اسے سزا دوں گا، اور اسے رہا کروں گا۔\n17۔ (کیونکہ مجبوری کے تحت اسے دعوت میں ان کے لیے چھوڑنا ہوگا۔)\n18۔ اور وہ سب ایک ساتھ پکارے، کہنے لگے، اس {آدمی} کو چھوڑ دو، اور ہمیں باراباس کو آزاد کرو:\n19۔ (جسے شہر میں ایک خاص بغاوت اور قتل کے جرم میں جیل بھیج دیا گیا۔)\n20۔ لہٰذا، پیلاطس، یسوع کو آزاد کرنے کے لیے تیار ہو کر، ان سے دوبارہ بات کی۔\n21۔ لیکن انہوں نے پکارا، کہا، اسے صلیب پر چڑھا دو، اسے صلیب پر چڑھاؤ۔\n22۔ اور اس نے تیسری بار ان سے کہا، کیوں، اس نے کیا برا کیا ہے؟ میں نے اس میں موت کی کوئی وجہ نہیں دیکھی: اس لیے میں اسے سزا دوں گا، اور اسے جانے دوں گا۔\n23۔ اور وہ فورا بلند آوازوں کے ساتھ آ گئے، کہ اسے مصلوب کیا جائے۔ اور ان کی اور سردار پادریوں کی آوازیں غالب آئیں۔\n24۔ اور پیلاطس نے حکم دیا کہ یہ ان کی ضرورت کے مطابق ہونا چاہیے۔ {دیا...: یا، منظور کیا}\n25۔ اور اس نے اسے ان کے حوالے کر دیا جسے بغاوت اور قتل کے جرم میں قید میں ڈال دیا گیا، جسے وہ چاہتے تھے؛ لیکن اس نے یسوع کو ان کی مرضی کے حوالے کر دیا۔\n26۔ اور جب وہ اسے لے جا رہے تھے، تو انہوں نے ایک سائمن، جو ایک سائرینیائی تھا، کو پکڑ لیا، جو دیہات سے نکل رہا تھا، اور اس پر صلیب رکھی تاکہ وہ یسوع کے بعد اسے اٹھا سکے۔\n27۔ اور وہاں اس کے پیچھے لوگوں اور عورتوں کی بڑی جماعت تھی، جو اس پر افسوس اور افسوس بھی کرتی تھیں۔\n28۔ لیکن یسوع نے ان کی طرف رخ کیا اور کہا، یروشلم کی بیٹیو، میرے لیے نہ روؤ، بلکہ اپنے لیے اور اپنے بچوں کے لیے روؤ۔\n29۔ کیونکہ دیکھو، دن آ رہے ہیں، جن میں وہ کہیں گے، بابرکت ہیں بانجھ، اور وہ رحم جو کبھی خالی نہیں ہوتے، اور وہ باپ جو کبھی دودھ نہیں پیتے۔\n30۔ پھر وہ پہاڑوں سے کہنا شروع کریں گے، ہم پر گر جاؤ؛ اور پہاڑوں کی طرف، ہمیں کور دو۔\n31۔ کیونکہ اگر وہ یہ سب سبز درخت میں کریں تو خشک درخت میں کیا کیا جائے گا؟\n32۔ اور اس کے ساتھ دو اور مجرم بھی تھے جنہیں موت کی سزا دی گئی۔\n33۔ اور جب وہ اس جگہ پہنچے، جسے کالواری کہا جاتا ہے، وہاں انہوں نے اسے اور مجرموں کو ایک دائیں اور دوسرے کو بائیں طرف مصلوب کر دیا۔ {کالواری: یا، کھوپڑی کی جگہ}\n34۔ پھر یسوع نے کہا، اے باپ، انہیں معاف کر دے؛ کیونکہ وہ نہیں جانتے کہ وہ کیا کرتے ہیں۔ اور انہوں نے اس کے کپڑے الگ کیے، اور قرعہ اندازی کی۔\n35۔ اور لوگ کھڑے ہو کر دیکھتے رہے۔ اور ان کے ساتھ حکمران بھی اس کا مذاق اڑاتے تھے، کہتے ہوئے، اس نے دوسروں کو بچایا؛ اگر وہ مسیح ہے، خدا کا منتخب کردہ ہے، تو وہ خود کو بچانے دے۔\n36۔ اور سپاہیوں نے بھی اس کا مذاق اڑایا، اس کے پاس آئے اور اسے سرکہ پیش کیا،\n37۔ اور کہا، اگر تم یہودیوں کے بادشاہ ہو تو اپنی جان بچا لو۔\n38۔ اور اس پر یونانی، لاطینی اور عبرانی خطوط میں بھی ایک تحریر لکھی گئی تھی، یہ یہودیوں کا بادشاہ ہے۔\n39۔ اور ایک مجرم، جسے پھانسی دی گئی، نے اس پر تنقید کی اور کہا، اگر تم مسیح ہو تو اپنے اور ہمیں بچا لو۔\n40۔ لیکن دوسرے نے اسے ڈانٹتے ہوئے کہا، کیا تم خدا سے نہیں ڈرتے، جب کہ تم بھی اسی سزا میں ہو؟\n41۔ اور ہم واقعی انصاف کے ساتھ ہیں؛ کیونکہ ہمیں اپنے اعمال کا صلہ ملتا ہے: لیکن اس آدمی نے کچھ غلط نہیں کیا۔\n42۔ اور اس نے یسوع سے کہا، اے خداوند، جب تم اپنی بادشاہی میں آؤ تو مجھے یاد رکھ۔\n43۔ اور یسوع نے اس سے کہا، \"یقینا میں تم سے کہتا ہوں، آج تم میرے ساتھ جنت میں ہو گے۔\n44۔ اور تقریبا چھٹا گھنٹہ تھا، اور زمین پر نویں گھنٹے تک اندھیرا چھا گیا۔ {زمین: یا، زمین}\n45۔ اور سورج مدھم ہو گیا، اور مندر کا پردہ درمیان سے پھٹ گیا۔\n46۔ اور جب یسوع نے بلند آواز میں پکارا، تو کہا، اے باپ، میں اپنی روح کو تیرے ہاتھوں میں دیتا ہوں: اور یہ کہہ کر اس نے بھوت کو چھوڑ دیا۔\n47۔ جب سینچورین نے دیکھا کہ کیا ہوا، تو اس نے خدا کی جلال دی اور کہا، یقینا یہ ایک نیک آدمی تھا۔\n48۔ اور وہ سب لوگ جو اس منظر پر جمع ہوئے، جو کچھ ہوا انہیں دیکھ کر اپنے سینے پر مارا اور واپس آ گئے۔\n49۔ اور اس کے تمام جاننے والے، اور وہ عورتیں جو گلیل سے اس کے پیچھے آئیں، دور کھڑی تھیں، یہ چیزیں دیکھ رہی تھیں۔\n50۔ اور دیکھو، وہاں ایک آدمی تھا جس کا نام یوسف تھا، ایک مشیر؛ {اور وہ} ایک اچھے انسان تھے، اور عادل:\n51۔ (اسی نے ان کے وکیل اور عمل کی منظوری نہیں دی تھی؛) {وہ} اریماتیہ کا تھا، جو یہودیوں کا شہر تھا: جو خود بھی خدا کی بادشاہی کا انتظار کر رہا تھا۔\n52۔ یہ {آدمی} پیلاطس کے پاس گیا، اور یسوع کے جسم کی بھیک مانگی۔\n53۔ اور اس نے اسے اتارا، چادروں میں لپیٹ کر ایک قبر میں رکھا جو پتھر سے تراشا گیا تھا، جہاں پہلے کبھی انسان نہیں رکھا گیا تھا۔\n54۔ اور وہ دن تیاری تھی، اور سبت کا دن قریب آ گیا۔\n55۔ اور وہ عورتیں بھی، جو اس کے ساتھ گلیل سے آئی تھیں، اس کے پیچھے آئیں اور قبر کو دیکھا، اور اس کی لاش کو کیسے رکھا گیا۔\n56۔ اور وہ واپس آئے، اور مصالحے اور مرہم تیار کیے؛ اور حکم کے مطابق سبت کے دن آرام کیا۔","1۔ اب ہفتے کے پہلے دن، بہت صبح سویرے، وہ مقبرے پر پہنچے، وہ مصالحے لے کر آئے جو انہوں نے تیار کیے تھے، اور کچھ {دیگر} بھی۔\n2۔ اور انہوں نے پتھر کو قبر سے دور رول کیا ہوا پایا۔\n3۔ اور وہ اندر داخل ہوئے، لیکن خداوند یسوع کی لاش نہ ملی۔\n4۔ اور ایسا ہوا، جب وہ اس بارے میں بہت حیران تھے، دیکھو، دو آدمی چمکدار لباس میں ان کے پاس کھڑے تھے:\n5۔ اور جب وہ ڈرے ہوئے اور زمین کے سامنے اپنے چہرے جھکے، تو انہوں نے کہا، تم مردوں میں سے زندہ کیوں تلاش کر رہے ہو؟ {زندہ: یا، وہ جو زندہ ہے}\n6۔ وہ یہاں نہیں ہے، بلکہ جی اٹھا ہے: یاد رکھو کہ اس نے تم سے کیسے بات کی جب وہ ابھی گلیل میں تھا،\n7۔ کہتے ہوئے، انسان کا بیٹا گناہ گاروں کے ہاتھوں میں دیا جائے گا، صلیب پر چڑھایا جائے گا، اور تیسرے دن دوبارہ زندہ ہوگا۔\n8۔ اور انہوں نے اس کے الفاظ کو یاد کیا،\n9۔ اور قبر سے واپس آیا، اور یہ سب باتیں گیارہ اور باقی سب کو بتائیں۔\n10۔ یہ مریم مگدلینی، جوانا، اور مریم {یعقوب کی ماں}، اور دیگر {عورتیں} تھیں جو ان کے ساتھ تھیں، جنہوں نے یہ باتیں رسولوں کو بتائیں۔\n11۔ اور ان کے الفاظ انہیں فضول کہانیاں لگے، اور انہوں نے یقین نہیں کیا۔\n12۔ پھر پطرس اٹھا اور قبر کی طرف دوڑا؛ اور جھک کر، اس نے لینن کے کپڑے خود بخود رکھے ہوئے دیکھے، اور روانہ ہو گیا، اپنے آپ میں حیران ہوتا کہ کیا ہوا۔\n13۔ اور دیکھیں، ان میں سے دو اسی دن ایک گاؤں ایماوس گئے، جو یروشلم سے تقریبا تین سو فرلانگ دور تھا۔\n14۔ اور انہوں نے مل کر ان تمام واقعات کے بارے میں بات کی جو پیش آئیں۔\n15۔ اور ایسا ہوا کہ جب وہ مل کر بات کر رہے تھے اور استدلال کر رہے تھے، یسوع خود قریب آیا اور ان کے ساتھ چلا گیا۔\n16۔ لیکن ان کی آنکھیں اس بات پر مرکوز تھیں کہ انہیں اسے نہ جاننا چاہیے۔\n17۔ اور اس نے ان سے کہا، یہ کیا قسم کی بات چیت ہے جو تم ایک دوسرے سے کرتے ہو، جب تم چلتے ہو اور اداس ہو؟\n18۔ اور ان میں سے ایک، جس کا نام کلیوپاس تھا، نے جواب میں کہا، کیا تم یروشلم میں صرف ایک اجنبی ہو، اور کیا تم نے آج کل وہاں ہونے والی چیزوں کو نہیں جانا؟\n19۔ اور اس نے ان سے کہا، کیا باتیں؟ اور انہوں نے اس سے کہا، ناصرت کے یسوع کے بارے میں، جو خدا اور تمام لوگوں کے سامنے عمل اور کلام میں طاقتور نبی تھا:\n20. اور کیسے سردار کاهنوں اور ہمارے حکمرانوں نے اسے موت کی سزا کے لیے پہنچایا اور مصلوب کر دیا۔\n21۔ لیکن ہم نے یقین کیا کہ وہی تھا جسے اسرائیل کو نجات دینی چاہیے تھی: اور اس سب کے علاوہ، آج یہ سب ہونے کو تیسرا دن ہے۔\n22۔ جی ہاں، اور ہماری جماعت کی کچھ خواتین نے بھی ہمیں حیران کر دیا، جو جلدی قبر پر تھیں؛\n23۔ اور جب انہیں اس کی لاش نہ ملی، تو وہ آئے اور کہا کہ انہوں نے فرشتوں کا خواب بھی دیکھا ہے، جس میں کہا گیا ہے کہ وہ زندہ ہے۔\n24۔ اور ان میں سے کچھ جو ہمارے ساتھ تھے، مقبرے پر گئے، اور اسے اسی طرح پایا جیسا کہ عورتوں نے کہا تھا: لیکن وہ اسے نہیں دیکھتے۔\n25۔ پھر اس نے ان سے کہا، اے بے وقوف اور سست دل جو نبیوں نے کہا ہے اس پر یقین کرنے والو:\n26. کیا مسیح کو یہ سب برداشت نہیں کرنا چاہیے تھا، اور وہ اپنی شان میں داخل نہیں ہونا چاہیے تھا؟\n27۔ اور موسیٰ اور تمام نبیوں سے شروع ہو کر، اس نے انہیں تمام صحیفوں میں اپنے بارے میں باتیں بیان کیں۔\n28۔ اور وہ گاؤں کے قریب پہنچے، جہاں وہ گئے: اور اس نے ایسا کیا جیسے وہ آگے جانا چاہتا ہو۔\n29۔ لیکن انہوں نے اسے مجبور کیا، کہا، ہمارے ساتھ رہو، کیونکہ شام کی طرف ہے اور دن بہت گزر چکا ہے۔ اور وہ ان کے ساتھ ٹھہرنے چلا گیا۔\n30۔ اور ایسا ہوا، جب وہ ان کے ساتھ گوشت کھا رہا تھا، اس نے روٹی لی، اسے برکت دی، اور انہیں دیا۔\n31۔ اور ان کی آنکھیں کھل گئیں، اور وہ اسے جانتے تھے؛ اور وہ ان کی نظروں سے اوجھل ہو گیا۔ {غائب...: یا، ان میں سے نظر آنا بند ہو گیا}\n32۔ اور انہوں نے ایک دوسرے سے کہا، کیا ہمارا دل ہمارے اندر نہیں جل رہا تھا، جب وہ ہم سے بات کر رہا تھا، اور جب اس نے ہمیں صحیفے کھول دیے؟\n33۔ اور وہ اسی وقت اٹھے، اور یروشلم واپس آئے، اور گیارہ کو جمع پایا، اور جو ان کے ساتھ تھے،\n34۔ کہتے ہوئے، خداوند واقعی زندہ ہو گیا ہے، اور شمعون پر ظاہر ہوا ہے۔\n35۔ اور انہوں نے بتایا کہ راستے میں کیا کچھ کیا گیا، اور وہ ان کے بارے میں کیسے معلوم ہوا جب وہ روٹی توڑتے تھے۔\n36۔ اور جب وہ اس طرح بول رہے تھے، یسوع خود ان کے درمیان کھڑا تھا اور ان سے کہا، تم پر امن ہو۔\n37۔ لیکن وہ خوفزدہ اور خوفزدہ تھے، اور سمجھا کہ انہوں نے کوئی روح دیکھی ہے۔\n38۔ اور اس نے ان سے کہا، تم پریشان کیوں ہو؟ اور آپ کے دلوں میں خیالات کیوں ابھرتے ہیں؟\n39۔ دیکھو میرے ہاتھ اور پاؤں، کہ یہ میں خود ہوں: مجھے سنبھالو، اور دیکھو؛ کیونکہ روح کے پاس گوشت اور ہڈیاں نہیں ہوتیں، جیسا کہ تم مجھے دیکھتے ہو۔\n40۔ اور جب اس نے یہ کہا، تو اس نے انہیں اپنے ہاتھ اور اپنے پاؤں دکھائے۔\n41۔ اور جب وہ ابھی خوشی کے لیے ایمان نہیں رکھتے تھے اور حیران تھے، تو اس نے ان سے کہا، کیا تم نے یہاں کوئی گوشت لیا ہے؟\n42۔ اور انہوں نے اسے بھونکی ہوئی مچھلی اور شہد کے چھتے کا ایک ٹکڑا دیا۔\n43۔ اور اس نے اسے لیا، اور ان سے پہلے کھایا۔\n44۔ اور اس نے ان سے کہا، یہ وہ الفاظ ہیں جو میں نے تم سے کہے، جب میں تمہارے ساتھ تھا، کہ وہ سب کچھ پورا ہونا چاہیے جو موسیٰ کے قانون میں، اور انبیاء اور زبور میں میرے بارے میں لکھا ہے۔\n45۔ پھر اس نے ان کی سمجھ کھولی، تاکہ وہ صحیفوں کو سمجھ سکیں،\n46۔ اور ان سے کہا، یوں لکھا ہے، اور یوں مسیح پر لازم تھا کہ وہ تکلیف اٹھے، اور تیسرے دن مردوں میں سے زندہ ہو:\n47۔ اور کہ توبہ اور گناہوں کی معافی اس کے نام پر تمام قوموں میں کی جائے، یروشلم سے شروع ہو کر۔\n48۔ اور تم ان باتوں کے گواہ ہو۔\n49۔ اور دیکھو، میں تم پر اپنے باپ کا وعدہ بھیجتا ہوں: لیکن تم یروشلم کے شہر میں رہو، جب تک کہ تمہیں اوپر سے طاقت نہ مل جائے۔\n50۔ اور اس نے انہیں بیت عنیا تک لے جایا، اور اپنے ہاتھ اٹھا کر انہیں دعا دی۔\n51۔ اور ایسا ہوا، جب اس نے انہیں برکت دی، تو وہ ان سے جدا ہو گیا اور آسمان میں لے جایا گیا۔\n52۔ اور انہوں نے اس کی عبادت کی، اور بڑی خوشی سے یروشلم واپس آئے:\n53۔ اور وہ مسلسل مندر میں رہتے تھے، خدا کی حمد اور برکت دیتے۔ آمین۔"];
